# 2026-07-31(운영점검보고서 2026-07-30 §5-2 "총 REST 수요 축소안" (a), 사용자 승인) — 위클리 2북만
# 격분(2분) 주기로 늦춘다.
#
# **배경**: 공유 `_RateLimiter`의 실측 한도는 앱키당 1건/초인데, 07-30 하루 실측 총수요가
# 19,606건/493분 = **0.663건/초로 이미 용량의 66%**였다. 백오프 배율이 1.51배만 넘으면
# (1/1.51 = 0.66건/초) 수요가 용량을 구조적으로 초과하는데, 실제로 오후 시간당 평균 배율이
# 1.29배·최대 2.61배까지 올라 옵션체인 25사이클(5.1%)이 통째로 유실됐다. 지금까지의 스태거링
# 조치(07-09/07-27/07-29/07-31)는 전부 "언제 호출하느냐"만 옮겼을 뿐 총량은 그대로였다 —
# 총수요가 한계선에 붙어 있으면 아무리 재배치해도 해결되지 않는다. 용량을 늘리는 쪽(폴러별
# 페이서 분리)은 2026-07-08 500 폭주로 203분치를 날린 전례가 있어 봉인 상태다.
#
# **왜 옵션체인인가**: 5분당 호출 실측 분해에서 옵션체인이 146건으로 **전체의 72%**다(만기유동성
# 33 / 투자자수급 15 / 매크로 7 / 계좌잔고 1). 여기를 안 건드리면 유의미한 감축이 불가능하다.
#
# **왜 위클리만인가**: 먼슬리는 감마 구조 판단의 주력 북이라 1분 해상도를 유지해야 한다. 위클리
# 2북(월/목)만 2분으로 늦추면 옵션체인 수요가 5분당 146 → 97건으로 줄어든다. 잃는 것은 **위클리
# 그릭스(IV/델타/감마/OI)의 REST 갱신 주기 1분 → 2분**뿐이고, 위클리 **체결 데이터는 WS 실시간
# 구독이라 전혀 영향받지 않는다**(1분봉은 그대로 매분 쌓인다).
#
# **화면/신호에 미치는 영향**: `db.latest_option_chain()`은 `DISTINCT ON (strike, option_type)`으로
# **레그별 최신값**을 취하므로, 위클리를 안 조회한 분에는 직전 값이 그대로 이월돼 체인 스냅샷에
# 구멍이 생기지 않는다(GEX/감마플립 계산 입력이 끊기지 않음).
#
# **격분 판정을 벽시계 분(짝수/홀수)으로 하는 이유**: 프로세스 기동 시각에 좌우되는 내부 카운터
# 대신 `poll_time.minute`을 쓰면 재시작해도 위상이 같고, 로그/DB만 보고도 "이 분에 위클리를 봤어야
# 하는가"를 바로 검증할 수 있다. 사이클이 밀려 분을 건너뛰면 짝수 분이 연달아 나올 수 있는데,
# 그건 벽시계 기준으로는 여전히 2분에 1회 이하라 부하가 늘지 않는다.
# 2026-08-03(운영점검보고서 §2-3 / §4 우선순위 2) — 위클리 2북을 **같은 분에 몰지 않고 서로 다른
# 분 패리티에 나눠 태운다.** 위 축소안 (a)는 "위클리는 2분에 1회"라는 총량만 정했고, 두 북을 모두
# `minute % 2 == 0`(짝수분)에 실었다. 그래서:
#
#   짝수분 = 먼슬리 10 + 위클리 20 = 30레그 → 실측 REST평균 40~51초, 60초 초과 39건
#   홀수분 = 먼슬리 10레그          → 실측 REST평균 12~19초, 60초 초과 0건
#
# 2026-08-03 실측: **밀림 39건의 100%가 짝수 mod10 버킷**이고, 짝수분 사이클이 60초를 넘기면 그
# 다음(홀수) 분이 통째로 스킵되므로 **결손 41분 중 39분이 홀수분**이었다. 분당 호출 수가 14~36으로
# 3:1 쏠려 있는 것이 원인이고, 총량을 줄이는 문제가 아니라 **분산의 문제**다.
#
# 위클리 월을 짝수분, 목을 홀수분에 두면 매 분 20레그로 평탄해진다 — **총 REST 수요는 1건도 늘지
# 않고**(위클리 각 북의 2분 주기도 그대로), 분당 최대-최소가 34/23으로 좁혀진다. 잃는 것이 없다.
#
# 값은 `poll_time.minute % 2`와 비교할 나머지다. 벽시계 분을 쓰는 이유는 축소안 (a) 때와 같다 —
# 프로세스 기동 시각에 좌우되는 내부 카운터 대신 `poll_time.minute`을 쓰면 재시작해도 위상이
# 같고, 로그/DB만 보고도 "이 분에 이 북을 봤어야 하는가"를 바로 검증할 수 있다.
OPTION_CHAIN_SLOW_SERIES_PHASE = {"weekly_mon": 0, "weekly_thu": 1}
OPTION_CHAIN_SLOW_SERIES_EVERY_N_MINUTES = 2

# ===== 2026-08-06 고도화#4 — KIS 혼잡 시간대의 위클리 폴링 감축 (레버는 있고, 내려져 있다) =====
#
# ## 미리 정해둔 규칙
#
# `hypotheses.yaml`의 `2026-08-04-p5`가 **숫자를 보기 전에** 적어둔 사전 대응 규칙이다:
#
#   > `inquire-price`의 p95가 2.5초를 넘는 시간대가 **이틀 연속 같은 시간대에** 나타나면,
#   > 그 시간대에 한해 위클리 폴링을 2분 → 4분 격분으로 늘린다.
#   > **먼슬리는 건드리지 않는다** — 판단 입력이다.
#
# 08-06에 그 조건이 **성립했다**: 10·11·12·13·14시 다섯 구간이 08-05와 이틀 연속 초과.
#
# ## 그런데 왜 켜지 않는가
#
# 08-06 보고서 §5-4의 권고 그대로다. 같은 날 고도화#1(먼슬리 레그 재시도)이 들어갔고,
# **그것만으로 먼슬리 두께가 회복되면 폴링 감축은 불필요하다.** 위클리 커버리지를 50% → 25%로
# 반토막 내는 것은 되돌리기 쉬운 결정이 아니고, 08-06이 위클리 만기일이었으며 핀 집중도 59.6%가
# 실제로 관측됐다 — 만기일에는 위클리가 판단에 유의미할 수 있다.
#
# ## 그러면 왜 구현은 하는가
#
# **"발동은 사람이 한다"가 코드로 표현돼야 하기 때문이다.** 규칙만 문서에 있으면 발동하려는
# 날에 그 자리에서 코드를 짜게 되고, 그때 처음 짜는 코드는 그날 처음 깨진다(워치독을 장전
# 기동 스크립트로 재사용한 것과 같은 이유). 레버를 미리 만들어 두고 **내려둔다**.
#
# ## 켜는 법
#
# 아래 dict에 `{시(int): 4}`를 넣는다. 예: 08-06 실측대로라면
#   OPTION_CHAIN_SLOW_SERIES_CONGESTED_HOURS = {10: 4, 11: 4, 12: 4, 13: 4, 14: 4}
# 그리고 **그 자리에서 `hypotheses.yaml`에 예측치를 적는다.**
#
# 2026-08-10 정정 — **주장 지표를 "그 시간대 p95 하락"으로 쓰면 안 된다.** 종전 이 주석이
# 그렇게 적어 뒀는데, 리포트 §17 교차점검은 이 지연을 **KIS 귀속**으로 판정한다(*"페이서가
# 한가한데 타임아웃이 나는 것은 예약 큐 경합이 아니다 — 스케줄링 최적화로는 줄지 않는다"*).
# KIS 쪽 혼잡이면 **우리가 콜을 줄여도 그들의 p95는 안 바뀐다.** 줄어드는 것은 우리의 노출이다.
#   주장  `budget_exceeded.count` 감소(08-10 기준선 27건)
#   참고  p95 — **예측하지 않는다.** 안 내려가도 이 레버의 반증이 아니다
#   대가  위클리 커버리지 50% → 약 25%
# 절감 규모(08-10 실측): 혼잡 5시간의 위클리 행 1,435 — 2분→4분이면 약 700콜/일(옵션체인의 9.5%).
#
# 자동 적응은 의도적으로 구현하지 않는다 — 지연을 보고 폴링을
# 줄이면 폴링이 줄어 지연이 낮아지고 다시 폴링이 느는 되먹임이 생긴다(2026-07-08에 페이서를
# 나눴다가 500 폭주로 203분을 잃은 전례).
OPTION_CHAIN_SLOW_SERIES_CONGESTED_HOURS: dict[int, int] = {}

# 2026-07-31(운영점검보고서 2026-07-31 §4 우선순위 2) — 밀림으로 건너뛴 분을 먼슬리 10레그로
# 회수할지 결정하는 임계. 다음 격자 틱까지 남은 대기 시간이 이보다 짧으면 회수를 시도하지 않는다
# (회수 사이클까지 밀려 연쇄되는 것을 막는다). 먼슬리 10콜 × 기준 1.0초에 백오프 여유를 더해
# 잡았다 — 07-31 실측 밀림 46건 중 대기 25초 미만은 4건뿐이라 대부분 회수 가능하다.
OPTION_CHAIN_CATCHUP_MIN_DELAY_SECONDS = 25.0

# 2026-08-04(운영점검보고서 §2-6 / Fix#8) — 한 사이클이 REST 수집에 쓸 수 있는 최대 시간.
#
# 08-03 §4-3이 미리 적어둔 판정표에 08-04 실측이 답을 줬다: 느린 호출 362건의 총 2,278초 중
# **HTTP가 2,050초(90%)**, 페이서 대기는 229초(10%)다(08-03은 54%/46%). 페이서 쪽은 1,661 → 229초로
# 86% 줄었으니 **우리가 통제하는 스케줄링 여유분은 사실상 소진됐고**, 남은 밀림 48건은 KIS 응답
# 지연에서 온다. 밀린 사이클의 내부 구성이 그 증거다: REST수집 평균 **78.3초**, DB적재 0.1초,
# rows 20 — 레그당 3.9초(정상 사이클은 1.7초)다.
#
# 지금까지는 "20레그를 다 모을 때까지" 기다렸고, 그래서 느린 레그 몇 개가 **다음 분의 사이클을
# 통째로 덮었다**. 08-04 미회수 결손 5분(14:31 / 15:11 / 15:15 / 15:17 / 15:19)이 전부 그 패턴이다.
#
# 50초 근거: 주기가 60초이고 DB적재+상태기록이 ~0.5초, 결손 회수(`OPTION_CHAIN_CATCHUP_MIN_DELAY_SECONDS`
# =25초)가 남은 시간에 돌아야 한다. 50초를 넘긴 시점의 남은 레그는 이번 분에 넣어도 이미 늦은
# 값이고, 포기하면 다음 분이 정시에 시작된다.
#
# **이것은 교환이지 개선이 아니다**: rows가 20 미만인 사이클이 새로 생긴다(= 그 분의 체인이
# 얇아진다). 검증할 때 `overrun.count` 감소와 `cycles.rows` 분포를 반드시 나란히 읽을 것 —
# rows 20 미만이 하나도 안 생겼다면 예산이 안 걸린 것이고, 절반이 얇아졌다면 임계가 너무 낮다.
OPTION_CHAIN_CYCLE_COLLECT_BUDGET_SECONDS = 50.0

# ===== 2026-08-11 고도화 A — **실패를 시간 예산에서 분리한다** =====
#
# ## 위 예산이 08-11에 드러낸 구조적 결함
#
# 위 50초는 "이 사이클이 REST에 쓸 수 있는 시간"이고, **성공한 호출과 실패한 호출을 구분하지
# 않는다.** 08-11 15:01~15:22에 KIS 응답이 read 타임아웃(4초)을 넘기자 이렇게 됐다:
#
#     레그당 = 페이서 1초 + 타임아웃 4초 = 5초  →  50초에 10레그  →  전부 실패  →  적재 0행
#
# **실패가 성공과 같은 값을 치르므로 사이클이 스스로 못 빠져나온다.** 같은 일이 22분 반복됐다.
#
# Fix#1(`OPTION_CHAIN_CONSECUTIVE_TIMEOUT_ABORT`)이 이 상태를 **감지해서 접는다**. 그것은
# 증상 처리로 옳지만 근본은 예산의 단위다 — 시간이 아니라 **성과**로 재야 한다.
#
# ## 무엇을 바꾸는가
#
# 두 예산을 나란히 둔다. 둘 중 **먼저 소진되는 쪽**이 사이클을 끝낸다.
#
#     시간 예산   50초        위 상수. 다음 분을 정시에 시작하기 위한 상한 — 그대로 둔다.
#     실패 예산   6건         이번 사이클에서 허용하는 **누적 실패 레그 수**.
#
# 실패 예산 6의 근거: 설계 20레그(먼슬리 10 + 위클리 10) 중 **30%**다. 08-11 실측에서 정상
# 사이클의 레그 실패는 분당 0~2건이었고(옵션체인 레그 실패 180건 / 494분), 6건은 그 3배다.
# 그보다 많이 실패하는 분은 "조금 나쁜 날"이 아니라 **그 분의 KIS가 우리에게 응답하지 않는 날**이다.
#
# ## Fix#1과 무엇이 다른가 — 둘 다 필요하다
#
#   Fix#1(연속 3회)   **빠른 감지**. 전멸 패턴을 15초 만에 알아챈다. 단 연속이어야 한다.
#   고도화 A(누적 6건) **누적 감지**. 성공/실패가 섞여 절반이 죽는 분을 잡는다 —
#                      Fix#1의 연속 카운터는 성공 하나에 0으로 돌아가므로 이 패턴을 못 본다.
#
# 08-11 14시대가 정확히 후자였다: 예산 초과 20건인데 전멸은 1건뿐이었다(14:31).
# 나머지 19분은 **섞여서 얇아진** 분이고, 그 분들이 먼슬리 레그 완전성 12.4% 미달의 본체다.
#
# ## 대가 — 이것은 교환이다
#
# 실패 예산에 걸려 접는 분은 **시간 예산이 남아 있어도 끝난다.** 즉 "조금 더 기다렸으면
# 성공했을 레그"를 포기할 수 있다. 그 대가를 받아들이는 이유는 위와 같다 — 실패가 6건 쌓인
# 분에서 남은 레그가 성공할 확률은 낮고, 그 시도는 다음 분의 정시 시작을 갉아먹는다.
# **검증은 `db.monthly_leg_completeness.below_design_pct`로 한다**(08-11 기준선 12.4%):
# 이 값이 나빠지면 예산이 너무 빡빡한 것이다.
OPTION_CHAIN_CYCLE_FAILURE_BUDGET_LEGS = 6

LOG_CHAIN_FAILURE_BUDGET = (
    "옵션체인 실패 예산(%d건) 소진 — 남은 %d레그를 포기하고 이번 사이클을 접습니다"
    "(시간 예산은 %.1f초 남아 있었다, 2026-08-11 고도화 A). 적재 %d행 · 컷당한북=%s · 우선순위위반=%s"
)

# 2026-08-05(운영점검보고서 2026-08-05 §2 이상점 8 / Fix#8) — 장전에는 지수 스팟을 적재하지 않는다.
#
# **KOSPI200 지수는 09:00 이전에 체결되지 않는다.** 그런데 `output3.bstp_nmix_prpr`는 장전에도
# 값을 돌려준다 — **전일 종가**다. 종전에는 그것을 매분 `underlying_spot_1m`에 새 행으로 적재해,
# 07:31~09:00 약 90분치가 "지금 시장"인 것처럼 쌓였다. 행 자체는 1분 전 것이라 **신선도로는
# 절대 걸러낼 수 없다**(값이 낡았지 행이 낡은 게 아니다).
#
# 08-05 실측: 07:31~09:00 내내 정확히 1000.0300(= 08-04 종가), 09:01에 1042.91로 점프.
# 즉 **오버나이트 갭 +4.29%를 장전 90분 동안 못 본 채** GEX/감마플립/감마월/VRP를 계산했고,
# 그 시간대 판단(08:45~09:00, 앙상블 4멤버)이 전부 그 위에서 내려졌다.
#
# 더 큰 피해는 레짐 쪽이다. `regime_pipeline.compute_gap_zscore()`(v6 §16.1 WARMUP ②)는
#   갭 = (오늘 첫 스팟 − 전일 마지막 스팟) / 기대변동폭
# 인데 **"오늘 첫 스팟"이 곧 전일 종가**라 분자가 항상 0이다. DB 전수 확인 결과 개시 이래
# **모든 거래일의 갭이 정확히 0.0000**이었다(07-27~08-05 8일 전수). 2026-07-10에 이 함수를
# 하드코딩 0.0에서 실데이터로 배선했는데, 배선은 됐고 **데이터가 그것을 상수로 만들고 있었다** —
# 08-05에 찾은 다른 결함들(VRP 미전달, MetaLabelContext 기본값)과 정확히 같은 형태다.
#
# 적재를 막으면 장전 조회분은 어디에도 남지 않는다. 그래도 되는 이유: 그 값은 전일 종가이고
# 전일 마지막 행에 **이미 같은 값이 있다**(중복이지 손실이 아니다).
#
# **경계 주의**: 09:00 정각 폴링이 지수 첫 체결보다 앞서면 그 1분은 여전히 전일 종가일 수 있다
# (08-05가 그랬고, 08-04는 09:00에 이미 실값이었다). 90분 → 최대 1분으로 줄지만 0은 아니다 —
# 그래서 `compute_gap_zscore()` 자체는 이번에 손대지 않았다([[NEXT_TODO]]).
MARKET_OPEN_TIME = dtime(9, 0)

# ===== 2026-08-04(고도화#1 규약 A) — 지표성 로그의 포맷 계약 =====
#
# `mahdi/ops/log_metrics.py`가 정규식으로 읽는 줄들이다. 08-03에 `rest_client` 쪽에서 이 계약이
# 세 번 깨졌고(레벨 변경 / 예외 처리 변경 / 트레이스백 제거), 08-04 리포트가 그 셋을 전부
# **개선으로 표시**했다(§2-1). 그때는 rest_client만 상수화했는데, `main.py`의 네 줄은
# **리포트 §1~§4·§8의 거의 전부**(사이클·밀림·결손 회수)를 떠받치므로 위험이 더 크다.
#
# 규약: 이 상수들을 바꾸면 `tests/test_ops_log_metrics_contract.py`가 깨진다. 파서를 함께 고쳐야
# 테스트가 다시 통과한다 — 로그만 바꾸고 넘어가는 일이 조용히 지나갈 수 없게 하는 것이 전부다.
# (`log_metrics`는 여전히 이 모듈을 import하지 않는다 — 순수 파서로 남긴다. 계약은 테스트가 진다.)
# 2026-08-07(§2-1 / Fix#3) — 끝에 `분=HH:MM`(이 사이클이 **적재한 분 라벨**)을 붙인다.
#
# 08-07 15:18에 DB가 0행인데 로그에는 사이클이 완주해 있었다. 원인은 그 사이클이 15:17:59.99x에
# 깨어 `poll_time`이 15:17로 내려깎였고, **직전 분의 행을 UPSERT로 덮어썼다**는 것이다 —
# 행 수가 정상이라 어떤 지표도 못 잡았다(빈 분은 `zero_row_count`가 잡지만, 덮어쓴 분은 안 잡힌다).
#
# 라벨을 로그에 실으면 파서가 **같은 분이 두 번 나오는지**를 직접 셀 수 있다. 괄호 **밖**에
# 붙이는 이유는 규약 A다 — `_CYCLE_RE`가 `\)`로 끝나므로 기존 파서를 깨지 않는다.
LOG_CHAIN_CYCLE_BREAKDOWN = (
    "옵션체인 사이클 소요 분해: REST수집 %.2f초 + DB적재 %.2f초 + 상태기록 %.2f초 + 기타 %.2f초 "
    "(rows=%d, 밀림=%.1f초%s, 타폴러동시호출추정=%s) 분=%s"
)
LOG_CHAIN_OVERRUN = (
    "옵션 체인 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기 "
    "(REST수집 %.2f초, DB적재 %.2f초, rows=%d%s, 타폴러동시호출추정=%s)"
)
LOG_CHAIN_CATCHUP = "옵션체인 결손 회수: %s 분을 먼슬리 %d레그로 채움(밀린 사이클 %s)"
# 2026-08-12 Fix#5 — 꼬리에 `· 우선순위위반=예|아니오`가 붙는다(세 컷 로그 공통).
#
# **`컷당한북`만으로는 판정할 수 없다는 것이 08-12의 발견이다.** 그날 `priority_cut_minutes`가
# 2로 나와 불변식 위반처럼 보였는데, 실측하니 둘 다 **홀수분(먼슬리 단독 사이클)의 꼬리 컷**
# 이었다 — 자를 것이 먼슬리밖에 없는 사이클이라 순서 위반이 성립할 수 없는 분이다. 규약 G와
# 같은 형태의 오류였다(성립할 수 없는 상황에 무조건부 임계를 걸었다).
#
# 그래서 **판정을 로그를 내는 쪽에서 한다** — 그 시점에만 "아직 안 부른 위클리가 남아 있었는가"를
# 알 수 있고, 파서는 그것을 사후에 복원할 수 없다(그 분에 위클리가 due였는지는 위상 설정에
# 달렸고, 설정은 바뀐다).
#
# 파서 안전: 새 필드는 **공백 뒤에** 붙는다. `컷당한북=(\S+)`가 `\S+`로 끊기므로 기존 정규식
# 셋(`_BUDGET_RE`/`_TIMEOUT_ABORT_RE`/`_FAILURE_BUDGET_RE`)이 그대로 통과한다.
LOG_CHAIN_BUDGET_EXCEEDED = (
    "옵션체인 수집 예산(%.0f초) 초과 — 남은 %d레그를 포기하고 %d레그로 이번 분을 마감합니다 "
    "(다음 분 사이클을 정시에 시작하기 위함, §2-6/Fix#8) 컷당한북=%s · 우선순위위반=%s"
)

# ===== 2026-08-11 Fix#1 — 연속 타임아웃이면 이번 사이클을 조기에 접는다 =====
#
# ## 무엇이 일어났는가 (08-11 15:01~15:22, 22분 연속 적재 0행)
#
# KIS 응답이 4초를 넘기기 시작하자 **우리 read 타임아웃(4.0초)이 전 호출을 실패로 바꿨다.**
# 로그의 느린 호출 줄이 그것을 그대로 적고 있다 — `HTTP 4.03~4.06초`가 못 박혀 있고 페이서
# 배율은 내내 1.00배였다(즉 우리 쪽 압력이 아니다, 리포트 §17 KIS 귀속).
#
#     레그당 비용 = 페이서 1초 + 타임아웃 4초 = 5초
#     50초 예산 / 5초 = 10레그 시도 → 전부 실패 → 적재 0행
#
# ## 왜 예산만으로는 못 빠져나오는가
#
# **실패한 호출이 성공한 호출과 똑같이 예산을 먹는다.** 그래서 한 번 이 상태에 들어가면
# 사이클이 스스로 못 빠져나온다 — 50초를 다 태우고 0행을 남기고, 다음 분이 같은 일을 반복한다.
# 08-06 고도화#1의 먼슬리 재시도도 여기서는 안 돈다: 그 경로는 **예산이 남았을 때만** 진입하는데
# 전 레그가 타임아웃되는 분은 정의상 예산이 이미 소진돼 있다(`LOG_CHAIN_CYCLE_EMPTY` 주석).
#
# ## 임계를 3으로 고른 근거 (숫자를 보기 전에 정했다)
#
# 먼슬리는 설계 10레그다. 1~2회는 단발 지터로 일어나고 실제로 08-11에도 정상 분에서 관측된다.
# **3회 연속**은 그 분의 KIS가 계속 4초를 넘긴다는 뜻이고, 그때 남은 레그를 더 부르는 것은
# 예산만 태운다. 3이면 최악의 분에서 15초만 쓰고 35초를 돌려준다.
#
# ## 무엇을 얻는가 — 이 fix는 데이터를 늘리지 않는다
#
# 조기 포기해도 그 분의 행은 여전히 0이다. 얻는 것은 셋이다:
#   1. 다음 분 사이클이 정시에 시작한다(밀림 방지 — 08-04 Fix#8과 같은 목적).
#   2. 확정 실패 호출을 안 쏜다(08-11 22분 x 10레그 = 220콜).
#   3. **원인이 지표로 남는다** — `조기포기=연속타임아웃`이 로그에 실려 "얇게 끝난 분"과
#      "KIS가 죽은 분"이 구분된다. 종전에는 둘 다 `LOG_CHAIN_BUDGET_EXCEEDED` 한 줄이었다.
#
# **연속 카운터는 성공하면 0으로 되돌린다** — 누적이 아니라 연속이어야 단발 지터에 안 걸린다.
OPTION_CHAIN_CONSECUTIVE_TIMEOUT_ABORT = 3

LOG_CHAIN_TIMEOUT_ABORT = (
    "옵션체인 연속 타임아웃 %d회 — 남은 %d레그를 포기하고 이번 사이클을 접습니다"
    "(확정 실패 호출을 안 쏘고 다음 분을 정시에 시작한다, 2026-08-11 Fix#1). "
    "적재 %d행 · 컷당한북=%s · 우선순위위반=%s"
)
# 2026-08-05(운영점검보고서 §2-6) — 사이클은 정상 실행됐는데 **행이 한 줄도 안 남은** 분.
#
# 08-05 14:31이 그랬다: KIS가 53초간 전 레그를 타임아웃시켜 `rows=0`으로 끝났는데, 로그에 남은
# 것은 `LOG_CHAIN_BUDGET_EXCEEDED`(...0레그로 이번 분을 마감합니다) 한 줄뿐이었다. 그 줄은
# **17레그로 마감한 분과 같은 레벨·같은 모양**이라 "조금 잘렸다"와 "통째로 날아갔다"가 구분되지
# 않았고, 결손 지표(로그 기준)는 사이클이 돌았으므로 이 분을 세지 않았다 — DB에는 0행인데
# 리포트 §4는 결손 1분만 보고했다.
#
# 재시도 경로의 `옵션 체인 폴링 재시도도 실패`로는 못 잡는다: 그 경로는 **예산이 남아 있을 때만**
# 진입하는데, 전 레그가 타임아웃되는 날은 정의상 예산이 이미 소진돼 있다.
# 2026-08-10 — 문구 정정. 종전에는 *"이 분은 GEX/감마플립 입력이 없다"* 라고 단언했는데
# **자기가 아는 것보다 넓게 말하고 있었다.** 이 줄은 폴링 루프에서 나오므로 **그 분의 적재**만
# 알고, 판단이 무엇을 봤는지는 모른다. 08-10 15:15 실측: 적재는 0행이었지만 판단은
# `db.option_chain_as_of()`의 **신선도 창** 덕에 직전 스냅샷 10레그로 GEX를 냈다
# (`signal_decisions` 15:15 → `chain_leg_count=10`, `gex` non-null).
# 판단이 실제로 눈이 멀었는지는 §14의 `gex_input_missing_minutes`가 DB 축에서 잰다.
LOG_CHAIN_CYCLE_EMPTY = (
    "옵션체인 이번 분 전멸 — 수집 %d레그 중 적재 0행(예산 %.1f초 소진, 재시도 %s). "
    "이 분의 체인은 비었다 — 판단은 신선도 창 안의 직전 스냅샷을 쓴다(§14 GEX 입력 없던 분에서 확인)"
)

# ===== 2026-08-06 고도화#1 — 먼슬리 레그만 한 번 더 부른다 =====
#
# ## 원래 계획이 틀렸던 지점
#
# 08-06 보고서 §5-1은 *"버려야 한다면 위클리부터 — 레그 큐를 먼슬리 우선으로 정렬한다"* 고 적었다.
# **그 순서는 이미 그렇게 돼 있었다**(`_books_due_this_cycle`이 입력 순서를 유지하고 `books[0]`이
# 먼슬리다. `test_collect_option_chain_cycle_visits_the_monthly_book_first`가 08-05부터 지킨다).
#
# 구현 직전 실측으로 원인을 다시 확인했다:
#   - 먼슬리 10레그 미만  **128분**(9레그 82 / 8레그 33 / 7레그 8 / 6레그 5)
#   - 예산 컷이 먼슬리에 닿은 분  **3분**(rows<10인 사이클 수 — 9행 1 + 10행 2)
#   - 옵션체인 레그 실패 119건 중 **111건이 ReadTimeout**
#
# 즉 먼슬리를 얇게 만든 것은 예산 컷이 아니라 **레그 단위 타임아웃**이다. 순서를 다시 고치는
# 것은 아무것도 바꾸지 않는다 — 실패한 레그를 **다시 부르는 것**이 그 128분을 줄이는 유일한 길이다.
#
# ## 왜 먼슬리만인가
#
# 먼슬리는 GEX/감마플립의 **유일한** 입력이고(v6 §11.4), 위클리는 핀 리스크 전용이다.
# 전 북을 재시도하면 총 호출이 배로 늘어 우리가 방금 고친 EGW00201/백오프를 되살린다.
#
# ## 왜 사이클 예산 안에서만인가
#
# 재시도가 예산을 넘기면 다음 분 사이클이 밀린다 — 08-04 Fix#8이 막으려던 바로 그 일이다.
# 같은 `collect_deadline`을 공유하므로 **예산이 남았을 때만** 돈다. 남은 예산이 없으면
# 이번 분은 얇은 채로 마감하는 것이 옳다(밀림은 다음 분까지 망친다).
OPTION_CHAIN_PRIORITY_SERIES = "regular"

# 한 사이클에 재시도할 최대 레그 수. 설계상 먼슬리는 10레그이므로 그 전부를 허용한다 —
# 상한을 두는 이유는 행사가 창이 넓어지는 미래 변경에서 이 경로가 조용히 커지는 것을 막기 위함이다.
OPTION_CHAIN_PRIORITY_RETRY_MAX_LEGS = 10

LOG_CHAIN_PRIORITY_RETRY = (
    "먼슬리 레그 재시도: %d개 중 %d개 회복(남은 예산 %.1f초) — 판단 주입력(GEX/감마플립)의 두께다"
)
# 2026-08-05(§2-4) — 트레이스백 표본을 다 쓴 뒤의 요약 줄.
#
# `트레이스백 생략 — <유형>` 부분이 계약이다. `log_metrics`가 이 마커로 유형별 건수를 계속
# 세므로(트레이스백이 사라져도 카운터가 안 죽는다), **문구를 바꾸면 계약 테스트가 깨진다.**
# 마커를 이 형태로 고른 이유: 트레이스백 마지막 줄(`httpx.ReadTimeout: ...`)과 **겹치지 않아야**
# 한 사건이 두 번 세어지지 않는다 — `_HANDLED_EXCEPTION_MARKERS`가 부분문자열로 매칭하기 때문이다.
LOG_KIS_FAILURE_TRACEBACK_OMITTED = "%s — %s (트레이스백 생략 — %s, 오늘 %d번째)"

# 프로세스 수명 = 하루(07:30 기동 → 15:45 종료). 상세 근거는 `logutil.TracebackBudget`.
_TRACEBACK_BUDGET = TracebackBudget()

LOG_ATM_ROLL = "ATM 롤링: 스팟 %.2f — 행사가 %s → %s"
LOG_REST_LATENCY = "REST 응답시간(%.0f초 창): %s"

# 2026-08-05 — 이벤트 캘린더 미기입 경고.
#
# 수기 테이블(`mahdi/config/event_calendar.yaml`)의 실패 모드는 "안 채우는 것"이 아니라
# **"안 채운 걸 아무도 모르는 것"** 이다. 안 채우면 `event_proximity_minutes`가 None으로
# 돌아가고, 그것은 2026-08-05 이전(페널티 한 번도 안 걸림)과 **완전히 같은 상태**인데
# 지표상으로는 아무 일도 안 일어난 것처럼 보인다.
#
# 그래서 이 줄은 **`log_metrics._QUALITATIVE_MARKERS`에 등록**돼 자동 리포트 §11 정성 항목에
# 매일 건수로 찍힌다(계약은 `tests/test_ops_log_metrics_contract.py`가 지킨다).
# 문구를 바꾸면 그 테스트가 깨진다 — 08-04 §2-1에서 로그 문구만 바꾸고 파서를 안 고쳐
# 362건이 0건으로 보고된 전례가 있다.
LOG_EVENT_CALENDAR_NOT_COVERED = (
    "이벤트 캘린더 미기입: %s — `mahdi/config/event_calendar.yaml`의 covered_through(%s)가 "
    "오늘(%s)보다 앞선다. 이벤트 근접 페널티가 걸리지 않는 상태다"
)
# 매 사이클(60초) 남기면 하루 495줄이 된다 — 08-04 §2-2에서 고친 로그 폭증의 재현이다.
# 1시간이면 하루 8줄로 §11 카운트에는 충분히 잡히고 사람이 읽는 줄은 거의 안 늘어난다.
EVENT_CALENDAR_WARNING_WINDOW_SECONDS = 3600.0

# 2026-07-29 신규 — 서킷브레이커/거래정지 감지(mahdi/risk/market_halt.py)용 H0UNMKO0(국내주식
# 장운영정보) 구독 대상. CB/시장임시정지는 시장 전체 이벤트라 아무 종목이나 구독해도 그 순간의
# MKOP_CLS_CODE로 시장 전체 상태를 알 수 있다 — KOSPI 최대형주(삼성전자)라 세션 상태 변화를
# 가장 먼저·확실히 반영한다.
MARKET_HALT_REFERENCE_SYMBOL = "005930"

# 2026-07-30(운영점검보고서 §2-4/§4 Fix#4): CB 감지는 "상태 전이가 있을 때만 기록"이라 정상적인
# 거래일에는 로그도 DB 행도 전혀 남기지 않는다 — 07-30 하루 전수 조사에서 `market_halt_status`
# 0행·관련 로그 0건이 나왔는데, 그게 "CB가 없었다"인지 "구독/파싱이 깨져 CB가 와도 못 잡는다"인지
# **구분할 방법이 아예 없었다**. 리스크 최종 안전장치가 라이브 검증 불가능한 상태였던 셈이다.
# 조치는 둘: (1) 구독 직후 현재 상태("정상")를 한 번 upsert해 COCKPIT이 "데이터 없음"이 아니라
# "정상"을 표시하게 하고, (2) 메시지를 실제로 받을 때마다 카운트해서 주기적으로 INFO 로그를
# 남기고 최신 수신 시각을 DB에 반영한다(전이 시에만 알림/이력을 남기는 절제 원칙은 그대로).
#
# 2026-07-31 실측으로 위 (2)의 설계 전제가 반증됐다(운영점검보고서 2026-07-31 §2-2). 하트비트를
# **메시지 핸들러 안에** 두면 "메시지가 오지 않으면 하트비트도 멈춘다" — 그런데 H0UNMKO0은
# 실제로 **세션 전이 시점에만** 발신된다(07-31 하루 총 2건: 08:00 장전세션, 09:00 정규장 개시).
# 그 결과 `market_halt_status.updated_at`이 09:00:05에 멈춘 채 6시간 45분간 갱신되지 않았고,
# 이는 "감지기가 죽었을 때"와 정확히 같은 모습이다 — 즉 생존 증명이 되지 못했다.
#
# 조치(§4 우선순위 4): **생존 신호를 감시 대상과 독립한 타이머에서 낸다.**
#   - `poll_market_halt_heartbeat()`가 메시지 유무와 무관하게 300초마다 현재 상태를 upsert →
#     `updated_at`은 이제 "관측 루프가 살아있다"를 뜻한다(임계 감시 가능).
#   - 메시지를 실제로 받은 시각은 별도 컬럼 `last_message_at`에 남긴다(마이그레이션 018) →
#     "감지기가 최근 무언가를 봤다"를 뜻하며, **정상일에도 6시간 공백이 정상**이므로 임계를 두지
#     않는다(임계를 두면 그 자체가 상시 오경보다 — 07-31 실측이 근거).
# 남는 한계(정직하게): "WS는 살아있는데 H0UNMKO0 구독만 조용히 끊긴 경우"는 KIS가 주기적
# 하트비트를 주지 않는 이상 원리적으로 관측 불가다.
MARKET_HALT_HEARTBEAT_SECONDS = 300.0  # 메시지와 무관하게 이 간격마다 현재 상태를 DB에 갱신
MARKET_HALT_MESSAGE_TOUCH_SECONDS = 60.0  # 수신 시각(last_message_at) DB 갱신 스로틀
MARKET_HALT_RECEIVE_LOG_EVERY = 20  # 수신 N건마다 INFO 1줄(첫 수신은 항상 남김)

# 2026-08-01(§5-4): WS 생존 신호도 같은 원칙 — 메시지와 독립한 타이머가 낸다(마이그레이션 020).
WS_HEARTBEAT_SECONDS = 300.0


@dataclass
class WsLiveness:
    """WS 연결/재연결 감지의 생존 상태 — 관측 루프가 갱신하고 독립 하트비트가 DB에 남긴다.

    2026-08-01(운영점검보고서 2026-07-31 §5-4). 07-31 재연결 0회 — 좋은 일이지만 **재연결 로직이
    살아있는지는 증명되지 않았다**. WS 수신 자체는 `market_raw_1m` 적재로 간접 증명되지만 그건
    "재연결 감지"가 아니다. CB 감지와 같은 패턴(독립 타이머 + 상태 객체 공유)으로 해결한다.
    """

    connected_since: datetime | None = None
    last_message_at: datetime | None = None
    reconnect_count: int = 0
    # 2026-08-03(§4 우선순위 4): H0UNMKO0 구독이 마지막으로 **성립**한 시각(KIS SUBSCRIBE 응답
    # rt_cd=0 수신 시점). `last_message_at`(데이터 수신)과는 전혀 다른 신호다 — 08-03에 장운영정보
    # 데이터가 0건이었는데도 하트비트는 정상이라 "구독이 살아 있는가"를 판별할 방법이 없었다.
    market_op_subscribed_at: datetime | None = None
    # 2026-08-05(COCKPIT 육안 점검 P2-12) — 오늘 ATM±N 행사가 창이 재롤링된 횟수.
    #
    # 08-03에 "창이 하루 종일 한 번도 안 움직였다"를 고치면서 선물 봉마다 재롤링하게 됐는데,
    # 그 반대편 비용이 계측되지 않았다: 08-05 실측 **77회**(08:46~12:20, 평균 2.7분마다).
    # 롤 한 번마다 창을 벗어난 종목은 구독 해제되고 그 종목의 1분봉이 끊긴다 — P0-1에서 고친
    # Flow Radar 공백(11:27~12:02, 35분)이 정확히 그 결과였다. 즉 이 숫자는 **관측 연속성의
    # 직접적인 선행지표**인데 COCKPIT에 없었다(로그를 세야만 알 수 있었다 — 07-31 REST 수요를
    # 계량하기 전과 같은 상태다).
    #
    # `reconnect_count`와 같은 방식으로 관측 루프가 증가시키고 독립 하트비트가 DB에 남긴다.
    # 프로세스가 매일 아침 새로 뜨므로 "오늘" 카운트는 자연히 초기화된다.
    atm_roll_count: int = 0

    # 2026-08-07(운영점검 §B-1 / 고도화#2) — 롤의 **대가**. 마이그레이션 028 참고.
    #
    # 위 `atm_roll_count`는 배지 임계 20회를 이틀 연속 4배 가까이 넘겼는데(08-05 77 / 08-07 76),
    # 08-07에 롤 76회를 전수 검산하니 **전부 히스테리시스 임계를 정당하게 넘은 것**이었다.
    # 롤 횟수는 시장 변동성의 함수라 통제 대상이 아니다 — 우리가 통제하는 것은 그 롤이 구독을
    # 실제로 끊었는가이고(고도화#1의 유지 풀), 그것이 이 값이다. 0이 목표 상태다.
    atm_roll_dropped_subs: int = 0

