MACRO_SNAPSHOT_INSERT_FAILURE_ALERT_STREAK = 2

# 2026-07-24(운영점검보고서 2026-07-24 §2-3/§4 Fix#3): ZN(10년 국채선물) KIS·yfinance 이중
# 실패가 07-22/07-23/07-24 3일 연속 13:01 근처(±5초)로 재현돼 우연이 아닌 것으로 확정됐다.
# 그렇다고 매번 첫 실패에 바로 알리면(기존 동작) 몇 분짜리 일시적 블립까지 "결손"으로 보고하게
# 된다 — MACRO_SNAPSHOT_INSERT_FAILURE_ALERT_STREAK와 동일한 패턴으로, 연속 2회(=10분) 이상
# 지속돼야 진짜 결손으로 보고 알린다(1회는 일시적 블립일 수 있어 조용히 넘어감).
# 2026-07-31 갱신: 아래 MACRO_ITEM_REFRESH_SECONDS로 ZN 조회가 매 5분 → 1시간이 되면서, 이 값의
# 벽시계 의미가 "연속 2회(=10분)"에서 **"연속 2회 시도(=2시간)"** 로 바뀌었다. 스트릭은 ZN을 실제로
# 조회한 사이클에서만 증감한다(미조회 사이클의 NULL을 실패로 세면 안 된다 — poll_macro_snapshot
# 참고). ZN은 어떤 신호 계산에도 안 쓰이는 표시 전용 값이라 알림 지연 2시간을 감수할 수 있다고
# 판단했다.
ZN_DUAL_FAILURE_ALERT_STREAK = 2

# 2026-07-31(운영점검보고서 2026-07-30 후속, 사용자 문의 "한국 장중에 변화가 없지 않은가 / 5분마다
# 가져올 필요가 있는가"에서 출발한 조사 결과) — 매크로 항목별 갱신 주기 분리.
#
# **전제 확인**: ZN/ES는 CME Globex에서 거의 23시간 거래되고 한국 정규장(09:00~15:45 KST =
# 시카고 19:00~01:45)은 그 야간(아시아) 세션 한복판이라 **실제로 움직인다** — 07-30 실측으로
# ES는 99사이클 중 71개가 서로 다른 값(장중 변동폭 0.404%), ZN은 17개(0.231%)였다. "장중에 안
# 변한다"는 전제는 데이터로 반박됐다.
#
# **그럼에도 주기를 나눈 이유**: 소비처를 전수 추적한 결과 항목마다 필요한 해상도가 달랐다.
#   - ES     : `compute_macro_score_proxy`가 최근 12버킷(≈1시간) 추세를 씀      → 5분 유지
#   - USDCNH : `cross_asset_stress`가 24버킷(≈2시간) z-score를 씀                → 5분 유지
#   - VIX    : macro_score의 콘탱고/백워데이션 판단                              → 5분 유지
#   - USDKRW : `cross_asset_stress`/macro_score 둘 다 **일별 시계열만** 조회      → 하루 몇 회면 충분
#   - US10Y  : 위와 동일(일봉 전용). 07-30 하루 고유값 **1개**                    → 하루 몇 회면 충분
#   - MOVE   : **소비처 없음**(COCKPIT 표시 전용). 하루 고유값 **1개**            → 하루 몇 회면 충분
#   - ZN     : **소비처 없음**(COCKPIT 표시 + CBOT 승인 배지). `recent_zn_front_series` 자체가
#              없다 — `cross_asset_stress`가 받는 건 USDKRW/USDCNH/US10Y 셋뿐                → 1시간
#
# **ZN/ES의 KIS 호출을 완전히 없애지 않고 저빈도 "프로브"로 남기는 이유**: 이 두 호출은 계좌에
# CBOT/CME 시세 신청이 안 돼 하루 198건 전부 EGW00552/EGW00550으로 실패한다(값은 yfinance 폴백이
# 채운다). 그렇다고 호출을 아예 빼면 **나중에 신청이 승인돼도 알아챌 방법이 없어진다** —
# COCKPIT의 CBOT 승인 배지가 `zn_front_source == "kis"` 여부로 판정하기 때문이다. 1시간에 한 번
# 두드려보면 승인 당일 안에 감지되고, 실패 로그도 하루 198건 → 16건으로 줄어든다(사람이 읽는
# 로그의 61%를 차지하던 반복 트레이스백이 사실상 사라진다).
#
# 참고: 이 실패들은 페이서 백오프를 키우지는 않는다 — `_is_kis_rate_limit_error()`가 msg_cd가
# 정확히 EGW00201일 때만 백오프를 트리거하고 ZN/ES는 EGW00552/EGW00550이다(2026-07-20 설계 확인).
# 즉 이번 조치의 목적은 백오프 완화가 아니라 (1) 확정 실패 호출 제거 (2) 로그 가독성 (3) yfinance
# 요청량 감소(07-28에 잡은 "13:01 패턴" 재발 위험 추가 완화)다.
MACRO_ITEM_REFRESH_SECONDS: dict[str, float] = {
    "zn": 3600.0,             # ZN 값(yfinance) + KIS 승인 프로브 — 신호 미사용, 표시 전용
    "es_kis_probe": 3600.0,   # ES의 KIS 시도만 저빈도로. 값 자체(yfinance)는 매 사이클 갱신한다
    "daily_series": 21600.0,  # US10Y + USDKRW — 둘 다 일봉 전용이라 6시간(정규장 기준 하루 2회)
    "move": 21600.0,          # MOVE — 소비처 없음 + 일별 인덱스라 하루 종일 불변
}

# VPIN 등거래량 버킷 크기 — 실거래 일평균거래량 관찰 전까지 쓰는 잠정치. 학계 관례는
# "일평균거래량/50"이지만 이 모의투자 환경의 실제 거래량 분포를 아직 모른다(2026-07-06 결정).
# 옵션은 선물보다 훨씬 얇아 버킷이 완성되기까지 오래 걸리거나 VPIN이 0.5(중립) 근처에 자주
# 머물 수 있다는 걸 알고 쓴다(2026-07-06 사용자에게 설명 후 옵션에도 적용하기로 확정).
VPIN_BUCKET_SIZE = 50
_VPIN_HISTORY_LIMIT = 500  # calculate_vpin 기본 window(50)의 10배 — 무한정 누적 방지

# Phase 1.5-③(만기 유동성 기준선, 2026-07-06 추가) — 연구문서(RESEARCH_EXPIRY_SELECTION_v1.md)가
# 권고하는 "ATM±2 집중"(Cao-Wei %스프레드 기준, 스캘핑에 최적인 구간). 도입 당시엔 WS 구독 범위
# (ATM±3)보다 좁았으나, 2026-07-10 위클리 월/목 분리로 STRIKES_EACH_SIDE 자체가 2로 줄어
# 지금은 WS 구독 범위와 폭이 같다(그래도 별도 상수로 유지 — 의미가 달라 향후 STRIKES_EACH_SIDE가
# 다시 늘어나도 유동성 관측 구간은 ATM±2로 고정하고 싶을 수 있음). get_asking_price()는 북당
# 5행사가×2(C/P)=10건 신규 REST 호출이라, 오늘 이미 1x 부하에서 403/500 레이트리밋을 관찰한
# 점을 고려해 폴링 주기를 옵션체인(60초)보다 훨씬 길게 잡았다 — 어차피 이 지표의 용도는 실시간
# 판단이 아니라 20거래일 기준선 축적이라 촘촘히 볼 필요가 없다(사용자 확인 후 %스프레드 포함
# 정식 스펙대로 진행하되, 호출빈도로 부하를 완화하기로 결정).
LIQUIDITY_ATM_EACH_SIDE = 2
# 2026-07-31(운영점검보고서 2026-07-30 §5-2 "총 REST 수요 축소안" (c), 사용자 승인): 300 → 600초.
# 이 폴러는 5분당 33건(호가 30 + 만기확인 3)으로 옵션체인 다음으로 큰 소비자다. 위 도입 주석이
# 이미 명시했듯 **이 지표의 용도는 실시간 판단이 아니라 20거래일 기준선 축적**이라, 해상도를
# 5분 → 10분으로 늦춰도 용도상 손실이 가장 작다(세 축소안 중 유일하게 신호 계산 입력을 건드리지
# 않는다). 단독 효과는 0.663 → 0.62건/초로 작아서, 축소안 (a)(위클리 격분화)와 함께 적용해
# **합계 0.663 → 약 0.456건/초(용량의 46%, 백오프 2.19배까지 여유)** 를 목표로 한다.
# COCKPIT 신선도 배지(`_STALE_DATA_THRESHOLD_SECONDS`=300초)는 `option_analysis_1m`/선물만
# 대상이라 이 변경으로 경고가 뜨지 않는다(확인함).
#
# 2026-07-31(운영점검보고서 2026-07-31 §2-1 원인 a / §4 우선순위 1) — **버스트 분할**.
# 위 (c)안은 주기를 600초로 늦춰 호출 "총량"을 절반으로 줄였지만, 한 사이클이 여전히 33콜을
# **한 번에** 쏘는 구조는 그대로였다. 07-31 하루치 실측으로 그 대가가 처음 계량됐다:
#   버스트 50회 / 점유 시간 중앙 55.5초 · 평균 58.0초 · **최대 109.3초**
#   시작 위치는 10분 창의 1분 35초(50회 중 47회) → 2분대 짝수분 옵션체인 사이클(0~39초 필요)을
#   통째로 덮는다. 그 결과 시작분 mod10=2 구간만 창 안 만기유동성 호출 평균 13.4건 ·
#   REST수집 53.0초 · 밀림 17건(전체 46건의 37%)으로 튀었다.
# 즉 **총량이 아니라 버스트 형태가 남은 병목**이었다(총수요는 이미 용량의 43.6%로 여유가 있다).
#
# 조치: "600초마다 3북 33콜 일괄" → "**60초마다 확인하되 북 하나씩 홀수분 슬롯에서만 조회**".
#   - 홀수분은 축소안 (a) 덕에 옵션체인이 먼슬리 10레그만 돌아 0~13초만 쓰고 **47초가 비어 있다**
#     (07-31 실측 중앙값). 북 1개는 11콜(만기확인 1 + 호가 10) ≈ 13초라 그 안에 여유롭게 들어간다.
#   - 총 호출량은 완전히 동일하다(33콜/10분). 바뀌는 것은 "한 번에 33콜"이 "세 번에 11콜씩"이 된 것뿐.
#   - 북별 조회 시각이 1/3/5분으로 갈리지만 `db.latest_expiry_liquidity()`가 원래부터
#     `DISTINCT ON (series) ORDER BY series, timestamp DESC`로 **북별 최신값**을 취하므로
#     COCKPIT 표시에 영향이 없다(그 함수 docstring이 "북마다 조회 시각이 조금씩 어긋날 수 있어"라고
#     이미 명시하고 있다).
#   - 슬롯 판정을 벽시계 `poll_time.minute % 10`으로 하는 이유는 축소안 (a)와 동일하다 —
#     재시작해도 위상이 같고 로그/DB만으로 검증할 수 있다.
EXPIRY_LIQUIDITY_POLL_INTERVAL_SECONDS = 60
EXPIRY_LIQUIDITY_WINDOW_MINUTES = 10  # 한 바퀴(북 전체를 한 번씩)를 도는 논리 주기
# books 순서(regular / weekly_mon / weekly_thu)대로 배정되는 `minute % 10` 슬롯 — 전부 홀수분이고
# 서로 2분씩 떨어져 있다. 북이 늘어나면 이 튜플만 늘리면 되고, 길이가 모자라면 초과분은 조회되지
# 않으므로 회귀 테스트(test_expiry_liquidity_slots_cover_every_book)가 이를 잡는다.
EXPIRY_LIQUIDITY_BOOK_SLOT_MINUTES = (1, 3, 5)

# 2026-08-06(운영점검 장전편 §2-2 / Fix#2) — 이 폴러의 **장전 슬롯은 구조적으로 0행을 낳는다.**
