# 2026-07-28(운영점검보고서 2026-07-27 §4 Fix#1 재수사, 스케줄 밀림 근본원인 확정 후속): 07-09에
# poll_expiry_liquidity에만 오프셋을 준 뒤로 poll_investor_flow와 poll_macro_snapshot은 여전히
# 오프셋 없이 poll_option_chain과 같은 순간(t=0)에 기동해왔다 — 이번 재수사에서 라이브 계측
# (rate_limit_total_calls 전후차)으로 확인한 결과, poll_investor_flow(옵션체인과 동일하게 60초
# 주기)가 매 사이클 거의 항상 겹쳐 정상 상태 기준선 콜 3건(투자자 수급 3세그먼트) 오염을 유발했고,
# 콜드스타트 직후에는 4개 폴러 전부가 동시에 첫 사이클을 돌며 20건까지 겹쳐 REST수집이 48.6초까지
# 치솟는 걸 실측했다(콜당 정확히 ~1.0초씩 REST수집 시간이 늘어남, 옵션체인 사이클 소요 분해
# 로그의 "타폴러동시호출추정"으로 확인). poll_expiry_liquidity와 동일한 startup_offset_seconds
# 패턴을 나머지 두 폴러에도 적용해 4개 폴러의 위상을 60초 구간 안에서 0/15/30/45초로 고르게
# 분산한다 — investor_flow(15초)와 macro_snapshot(45초)은 서로 다른 잔여(mod 60)를 갖도록 골라
# expiry_liquidity(30초, 300초 주기)와도 겹치지 않는다(15/45는 300으로 나눠도 30과 다른 위상).
# 공유 _RateLimiter 자체(전체 앱키 공용 1건/초 한도, 2026-07-08/07-20 실측)는 그대로 유지 —
# 폴러별로 페이서를 분리하면 합산 호출 빈도가 그 실측 한도를 넘어 500 폭주가 재발할 위험이 있어
# (그 위험 때문에 애초에 단일 공유 리미터로 합쳤던 것, 위 2026-07-08 이력 참고) 이번엔 손대지
# 않는다 — 위상 분산은 총 호출량이나 페이싱 정책을 바꾸지 않고 "언제 겹치는지"만 조정하는
# 저위험 완화책이다.
# 2026-07-31(§4 우선순위 5): 15 → 40초. 15초 자리는 만기유동성 슬롯이 가져갔고, 투자자수급은
# 3콜(≈4초)뿐이라 **짝수분 옵션체인(0~30초 공칭)이 끝난 뒤**에 두는 것이 자연스럽다.
# 2026-08-03(§4 우선순위 2): 40 → 50초. 만기유동성이 30초로 물러나며 30~41초를 쓰게 됐고,
# 40초는 그 한가운데다. 2026-08-03 실측에서 투자자수급(당시 42초)은 **짝수분 옵션체인 창 안에
# 들어간 최대 기여자**(mod10=0에서 창 안 1.6건)였다 — 매 분 3콜뿐이라 가장 늦은 자리로 미루는
# 것이 비용이 가장 싸다. 50~53초로 분 끝에 2콜분(≈7초) 여유를 남긴다.
INVESTOR_FLOW_PHASE_OFFSET_SECONDS = 50.0

# 2026-07-30(운영점검보고서 §2-1/§4 Fix#2) — "5분 그룹 재스태거링".
#
# 07-29 Fix#1이 계좌 잔고 폴러를 60초 그룹에서 빼내는 데는 성공했지만, 옮겨 넣은 자리가 하필
# 이미 만기유동성(30초)·매크로(45초)가 있던 300초 그룹의 바로 옆(60초)이었다. 결과적으로
# **매 5분마다 약 41건의 REST가 30초 폭에 집중**됐다:
#   t=30s 만기유동성 33건 / t=45s 매크로 7건 / t=60s 계좌잔고 1건
# 07-30 하루치 실측에서 이 클러스터가 직접 확인됐다 — 사이클 종료 분(mod 5)별로 나눠보면
# 분%5=3 구간만 타폴러동시호출 평균 22.9건·REST수집 58.2초·60초 초과 40%(다른 구간은 1.7~6.0건,
# 39~41초)로 극단적으로 튀었고, 그 여파로 옵션체인 25사이클(전체의 5.1%)이 통째로 유실됐다.
#
# 조치: 세 폴러를 5분 창 안에서 고르게 흩어 버스트를 3개로 쪼갠다(총 호출량은 그대로 —
# "언제 겹치는지"만 바꾸는 저위험 조치라는 점은 위 2026-07-28 주석과 동일한 원칙).
#   만기유동성 t=35s(0분대) / 매크로 t=155s(2분대) / 계좌잔고 t=275s(4분대)
# 셋 다 각 분의 35초 지점(=옵션체인이 t=0~30초를 쓰고 난 뒤)에 놓아 60초 그룹과도 어긋나게 한다.
# 검증 기준: 다음 거래일에 분%5별 타폴러동시호출 평균이 22.9건에서 내려가고 60초 초과 비율이
# 균등해지는지(특정 분에만 몰리지 않는지) 확인할 것.
#
# 2026-07-31 갱신: 축소안 (c)로 만기유동성 주기가 600초가 되면서 세 폴러의 공통 주기(LCM)는
# 10분이 됐다. 그 10분 창 안의 발사 시각은 아래와 같아 여전히 겹치지 않는다(최소 간격 60초):
#   0:35 만기유동성 / 2:35 매크로 / 4:35 계좌잔고 / 7:35 매크로 / 9:35 계좌잔고
# 오프셋 값 자체는 바꾸지 않았다 — 주기만 늘어나 만기유동성 발사 횟수가 절반이 됐을 뿐이다.
# (이 성질은 `test_five_minute_pollers_are_spread_across_the_window_not_clustered`가 상수에서
#  직접 재계산해 검증하므로, 앞으로 주기/오프셋을 바꾸면 테스트가 충돌을 잡아준다.)
#
# ==========================================================================================
# 2026-07-31(운영점검보고서 2026-07-31 §2-3 / §4 우선순위 5) — **폴러 위상 계획**
#
# 위 07-30 계산("0:35 / 2:35 / 4:35에 흩었다")은 **한 번도 그대로 실현된 적이 없었다.** 07-31
# 하루치 로그에서 엔드포인트별 호출 시각을 역산한 결과:
#   폴러        설계 오프셋   실측 벽시계 위상        차이
#   투자자수급     15초        매 분 47~50초         +32초
#   만기유동성     35초        10분 창의 1:35(=95초)  +60초
#   매크로        155초       5분 창의 3:18~3:25     +43~50초
#   계좌잔고      275초       5분 창의 0:05~0:08     +30초(랩)
# 원인은 `*_STARTUP_OFFSET_SECONDS`가 이름 그대로 **프로세스 기동 시각 기준**이었다는 것이다 —
# `await asyncio.sleep(offset)` 후 첫 사이클이 도는 시점을 `_advance_fixed_tick`이 격자 원점으로
# 고정하므로, 기동 시각과 첫 사이클 소요시간에 따라 벽시계 위상이 **매일 달라진다**. 즉 §2-1(a)의
# 만기유동성 충돌은 "오프셋 값이 나빴다"가 아니라 "오프셋 앵커가 없었다"는 문제였고, 값만 다시
# 튜닝해봐야 내일 기동 시각이 몇 초 달라지면 또 다른 자리로 옮겨간다.
#
# 조치: 모든 폴러를 **벽시계 자정 기준 격자**(`phase_offset + k*interval`)에 앵커한다
# (`_advance_fixed_tick` / `_seconds_until_next_wall_tick`). 이제 상수는 이름 그대로
# "벽시계 위상"이고, 아래 표가 실제로 실현되는 배치다(공통 주기 LCM = 600초):
#
#   폴러          주기    위상            발사 분(mod 10)   콜수   공칭 점유(콜×1.0초)
#   ------------  ------  --------------  ----------------  -----  -------------------
#   옵션체인       60초    0초             매 분             30/10  0~30초(짝) / 0~10초(홀)
#   만기유동성     60초    15초            1, 3, 5 (북별)    11     15~26초
#   투자자수급     60초    40초            매 분             3      40~43초
#   매크로        300초   168초(2:48)     2, 7              ≤7     48~55초
#   계좌잔고      300초   288초(4:48)     4, 9              1      48~49초
#   SignalFusion   60초    10초            매 분             0      (REST 없음)
#
# 겹치는 구간이 하나도 없고, 최소 간격은 30→40초(10초)와 43→48초(5초)다. 짝수분에 만기유동성을
# 두지 않는 것이 이 배치의 핵심이다 — 짝수분은 옵션체인이 30레그를 쓰고, 홀수분은 10레그만 써서
# 47초가 비기 때문이다(축소안 (a)가 만든 여유를 처음으로 실제로 활용한다).
#
# ------------------------------------------------------------------------------------------
# 2026-08-03(운영점검보고서 §2-3 / §4 우선순위 2) — **위 배치의 전제가 틀렸다.**
#
# 위 표는 "짝수분은 30레그, 홀수분은 10레그"라는 **비대칭 자체를 주어진 것으로 놓고** 그 사이의
# 빈 자리를 찾는 방식이었다. 그런데 08-03 실측에서 그 비대칭이 곧 밀림의 원인이었다:
#   밀림 39건의 **100%가 짝수 mod10** / 결손 41분 중 **39분이 홀수분**(짝수분 초과분이 다음
#   분을 통째로 스킵시킨다) / 분당 호출 수 14~36으로 3:1 쏠림.
# 그래서 빈 자리를 찾는 대신 **부하 자체를 평탄하게** 만든다(`OPTION_CHAIN_SLOW_SERIES_PHASE`) —
# 위클리 월/목을 짝/홀로 나누면 총 REST 수요는 그대로인 채 매 분 20레그가 된다.
#
# 옵션체인이 매 분 0~20초(공칭)를 쓰게 되므로 나머지 폴러를 그 뒤로 다시 배치한다:
#
#   폴러          주기    위상            발사 분(mod 10)   콜수   공칭 점유(콜×1.0초)
#   ------------  ------  --------------  ----------------  -----  -------------------
#   옵션체인       60초    0초             매 분             20     0~20초 (전 분 동일)
#   만기유동성     60초    30초            1, 3, 5 (북별)    11     30~41초
#   매크로        300초   150초(2:30)     2, 7              ≤7     30~37초
#   계좌잔고      300초   270초(4:30)     4, 9              1      30~31초
#   투자자수급     60초    50초            매 분             3      50~53초
#   SignalFusion   60초    10초            매 분             0      (REST 없음)
#
# **만기유동성·매크로·계좌잔고가 같은 위상(30초)을 공유하는 것이 이 배치의 핵심이다.** 셋의 발사
# 분 집합 {1,3,5} / {2,7} / {4,9}는 서로소라 같은 분에 절대 만나지 않는다 — 서로 다른 위상을
# 억지로 찾아 분 뒤쪽으로 밀어낼 이유가 없고, 오히려 한 자리에 모으면 그 뒤의 투자자수급까지
# 여유가 커진다. 결과적으로 **모든 분이 동일한 구조**(0~20 옵션체인 / 30~41 저빈도 / 50~53
# 투자자수급)를 갖고, 최소 간격은 20→30초(10초)와 41→50초(9초)다.
#
# 분당 호출 수: mod10 {0,6,8}=23 / {4,9}=24 / {2,7}=30 / {1,3,5}=34 — 최대 34, 최소 23
# (종전 최대 36, 최소 14). 총량과 평균(26.8건/분)은 바뀌지 않는다.
#
# **공칭 점유는 백오프가 없을 때(페이서 1.0초/콜)의 값**이다. 실측 짝수분 옵션체인은 백오프
# 1.3배가 걸려 39.2초를 썼다 — 즉 이 배치의 여유는 백오프 배율에 비례해 줄어들며, 그래서 총
# REST 수요 예산(08-03 실측 45.1%)을 함께 관리해야 한다. 이 성질은
# `test_poller_occupancy_windows_do_not_overlap`이 상수에서 직접 재계산해 검증한다.
# ==========================================================================================
MACRO_SNAPSHOT_PHASE_OFFSET_SECONDS = 150.0


def _seconds_until_next_wall_tick(
    interval_seconds: float, phase_offset_seconds: float, wall_now: datetime
) -> float:
    """
    입력: 폴링 주기, 벽시계 위상(자정 기준 초), 현재 벽시계 시각.
    계산: 자정 기준 격자 `phase_offset + k*interval` 위의 **다음 지점까지 남은 초**를 돌려준다.
         반환값은 항상 (0, interval] 범위다 — 정확히 격자 위에 있으면 "지금"이 아니라 **한 주기
         뒤**를 돌려준다. `_advance_fixed_tick`이 사이클 종료 직후 이 함수를 부르기 때문인데,
         0을 돌려주면 방금 끝난 사이클과 같은 분에 곧바로 한 번 더 도는 이중 실행이 된다.
    해석: 2026-07-31 §2-3 — 종전에는 폴러 위상이 프로세스 기동 시각에 앵커돼 매일 달라졌고,
         그래서 스태거링 설계값(35/155/275초)이 실측(95/198/305초)과 어긋나 있었다. 벽시계
         자정을 원점으로 삼으면 위상이 **기동 시각·재시작과 무관하게 항상 같다** — 설계 표
         (MACRO_SNAPSHOT_PHASE_OFFSET_SECONDS 위 "폴러 위상 계획")가 그대로 실현되고,
         로그 타임스탬프만 보고도 "이 폴러가 제 자리에서 돌았는가"를 검증할 수 있다.
    실패 조건: interval_seconds <= 0이면 격자를 정의할 수 없으므로 0.0(대기 없음).
    """
    if interval_seconds <= 0:
        return 0.0
    since_midnight = (
        wall_now.hour * 3600 + wall_now.minute * 60 + wall_now.second + wall_now.microsecond / 1_000_000
    )
    elapsed_in_cycle = (since_midnight - phase_offset_seconds) % interval_seconds
    if elapsed_in_cycle == 0:
        return interval_seconds
    return interval_seconds - elapsed_in_cycle


async def _sleep_until_first_wall_tick(interval_seconds: float, phase_offset_seconds: float) -> None:
    """
    계산: 폴러 기동 직후 벽시계 격자의 첫 지점까지 대기한다.
    해석: 종전 `await asyncio.sleep(startup_offset_seconds)`의 대체다. 그 방식은 (1) 콜드스타트
         버스트를 막는 효과는 있었지만 (2) 격자 원점을 기동 시각에 못박아 벽시계 위상이 매일
         달라지게 만든 원인이기도 했다(2026-07-31 §2-3). 여기서 격자에 맞춰 기다리면 두 목적이
         한 번에 해결된다 — 폴러마다 위상이 다르므로 콜드스타트에도 서로 흩어지고, 첫 사이클부터
         이미 설계 위상 위에 앉는다.
         최대 대기 시간은 주기와 같다(옵션체인/만기유동성/투자자수급 ≤60초, 매크로/계좌잔고
         ≤300초). 장중 수동 재시작 시 매크로가 최대 5분 늦게 시작할 수 있으나, 원래 5분봉이라
         해상도 손실이 없다.
    """
    wait = _seconds_until_next_wall_tick(interval_seconds, phase_offset_seconds, db.local_now())
    if wait > 0:
        await asyncio.sleep(wait)


# 2026-08-07(운영점검 §A-1 / Fix#3) — 사이클 시작 시각을 분으로 자를 때 **분 경계 직전을 올린다.**
#
# 08-07 실측: `option_analysis_1m`의 07:30이 20행, **07:31이 0행**, 07:32가 20행이었다. 로그
# 축으로는 결손 0분(사이클은 07:31:19에 rows=20으로 완주했다) — 두 축이 어긋난 원인이 이것이다.
#
# `_sleep_until_first_wall_tick`/`_advance_fixed_tick`이 깨우는 시각은 격자점(:00)이지만,
# `asyncio.sleep`은 **일찍 깨는 것을 금지하지 않는다**(이벤트 루프 타이머 해상도·부동소수점
# 누적). 07:30:59.9x에 깨면 `replace(second=0)`가 07:30으로 내려깎아, 스케줄러가 의도한 07:31이
# 아니라 **직전 분**에 적재된다. 그 분은 다음 사이클이 07:32를 쓰므로 영영 빈다.
#
# 스케줄러의 목표 틱을 그대로 쓰는 것이 원리상 정확하지만, `next_tick`은 `time.monotonic()`
# 기준이라 벽시계 datetime으로 되돌리려면 두 시계의 오프셋을 들고 다녀야 한다(그 오프셋 자체가
# 드리프트한다). 대신 **"경계 직전이면 그 경계로 올린다"**는 국소 규칙으로 같은 결과를 얻는다 —
# 고정 틱 폴러는 설계상 격자점에서만 깨므로, 경계 2초 전에 깬 사이클의 의도된 분은 다음 분이다.
#
# 2초 근거: 이벤트 루프 지연은 통상 밀리초 단위이고(08-07 실측 사이클 완료 시각의 초 성분은
# 전부 :09/:19대), 정상 사이클이 분 경계 2초 전에 **시작**하는 일은 고정 틱 설계상 없다
# (`_advance_fixed_tick`이 밀린 사이클도 격자 위 미래 지점으로 스냅한다). 반대로 이 값을 크게
# 잡으면 실제로 늦게 시작한 사이클의 분을 다음 분으로 밀어 **없는 미래에 적재**하게 된다.
POLL_TIME_BOUNDARY_SNAP_SECONDS = 2.0


def _grid_poll_minute(wall_now: datetime, snap_seconds: float = POLL_TIME_BOUNDARY_SNAP_SECONDS) -> datetime:
    """
    입력: 사이클 시작 벽시계 시각, (선택) 경계 스냅 폭.
    계산: 분으로 내려깎되, 다음 분 경계까지 `snap_seconds` 이내면 **그 경계로 올린다.**
    해석: 근거는 `POLL_TIME_BOUNDARY_SNAP_SECONDS` 주석. 이 함수는 적재 행의 분 라벨을 정하므로
         고정 틱 폴러의 **사이클 시작 지점에서만** 쓴다 — 사이클 도중/종료 후의 시각에 쓰면
         한 사이클의 행이 두 분으로 갈린다.
    실패 조건: 없다.
    """
    remainder = 60.0 - (wall_now.second + wall_now.microsecond / 1_000_000)
    if remainder <= snap_seconds:
        wall_now = wall_now + timedelta(seconds=remainder)
    return wall_now.replace(second=0, microsecond=0)


def _advance_fixed_tick(
    next_tick: float | None,
    interval_seconds: float,
    loop_now: float,
    phase_offset_seconds: float = 0.0,
    wall_now: datetime | None = None,
) -> tuple[float, float, float]:
    """
    입력: 직전 예약 시각(첫 사이클이면 None), 폴링 주기, 현재 이벤트 루프 시각, 벽시계 위상,
         현재 벽시계 시각(주입 안 하면 `db.local_now()` — 테스트 이음새).
    계산: 다음 틱을 **원래 위상 격자 위에서만** 예약한다 — 사이클이 주기를 넘겨 예약 시각을
         이미 지나쳤으면, 지나친 틱들을 통째로 건너뛰되 격자에서 벗어나지 않도록 주기의 정수배만
         더한다. 첫 틱(next_tick=None)은 `_seconds_until_next_wall_tick`으로 **벽시계 격자**에
         앵커한다(2026-07-31 §2-3) — 종전에는 `loop_now + interval`이라 격자 원점이 "지금"이었고,
         그래서 구독 워밍업으로 next_tick이 한 번 리셋될 때마다 위상이 임의로 옮겨갔다.
         반환값은 (다음 예약 시각, 대기 시간, 밀린 시간).
    해석: 2026-07-30 운영점검 §2-1 원인(b). 종전에는 밀리면 `next_tick = loop_now`로 **현재 시각에
         위상을 다시 못박았다**. 이러면 한 번 밀릴 때마다 그 폴러의 위상이 조금씩 이동하고,
         이동한 자리가 5분 폴러 버스트 구간이면 계속 겹쳐 또 밀리는 식으로 위상이 끌려다닌다 —
         07-30 실측에서 REST수집 평균이 07시 32.0초 → 14시 58.2초로 단조 악화하고 시간당 사이클
         수가 60 → 52로 줄어든 것이 이 메커니즘과 정합적이다. 격자에 스냅하면 폴러 간 상대 위상이
         하루 종일 고정돼 겹침이 예측 가능한 횟수(5분에 1회)로 제한된다.
         부수 효과로 밀린 직후 즉시 재시작(delay=0) 대신 다음 격자까지 잠깐 쉬게 되는데, 이는
         공유 `_RateLimiter`가 record_success로 백오프를 회복할 여유를 준다는 점에서도 유리하다
         (밀린 사이클의 데이터 자체는 어느 쪽이든 이미 유실된 뒤다 — poll_time이 사이클 시작
         시각 기준이라 즉시 재시작해도 건너뛴 분을 되찾지는 못한다).
    실패 조건: interval_seconds <= 0이면 격자를 정의할 수 없으므로 현재 시각 기준으로 예약한다.
    """
    if next_tick is None:
        if interval_seconds <= 0:
            return loop_now, 0.0, 0.0
        wait = _seconds_until_next_wall_tick(
            interval_seconds, phase_offset_seconds, wall_now if wall_now is not None else db.local_now()
        )
        return loop_now + wait, wait, 0.0

    scheduled = next_tick + interval_seconds
    delay = scheduled - loop_now
    if delay >= 0:
        return scheduled, delay, 0.0

    overrun_seconds = -delay
    if interval_seconds <= 0:
        return loop_now, 0.0, overrun_seconds

    # 지나친 틱 수만큼 주기를 통째로 더해 격자 위의 첫 미래 시각으로 이동한다.
    missed_ticks = math.floor(overrun_seconds / interval_seconds) + 1
    snapped = scheduled + missed_ticks * interval_seconds
    return snapped, snapped - loop_now, overrun_seconds


class _WebsocketsAdapter(WSConnection):
    """websockets 라이브러리의 연결 객체를 KISWebSocketClient가 기대하는 프로토콜에 맞춘다."""

    def __init__(self, ws) -> None:
        self._ws = ws

    async def send(self, message: str) -> None:
        await self._ws.send(message)

    async def recv(self) -> str:
        return await self._ws.recv()

    async def close(self) -> None:
        await self._ws.close()


async def _reroll_books_to_spot(
    subscription_managers: list[RollingSubscriptionManager],
    spot: float,
    ws_liveness: WsLiveness | None = None,
) -> None:
    """
    입력: 구독 롤링 매니저 목록, 방금 완성된 선물 1분봉의 종가, (선택) 생존 상태 객체.
    계산: ATM이 실제로 이동한 매니저만 roll_to_spot()으로 재롤링하고, 이동했을 때만 INFO 1줄을
         남긴다(`roll_to_spot()` 자체가 diff 기반이라 변화가 없으면 무동작이지만, "언제 어디서
         어디로 옮겼는가"는 로그에 남아야 한다).
         `ws_liveness`를 주면 **실제로 이동한 롤 1회를 카운트**한다(2026-08-05 P2-12) —
         매니저가 여러 개라도 "창이 한 번 움직였다"가 사람이 세고 싶은 단위다(로그는 북마다
         한 줄씩 남으므로 줄 수를 3으로 나눠야 하는데, 그렇게 세면 북 수가 바뀔 때 조용히 틀린다).
    해석: 2026-08-03(운영점검보고서 §2-2 후속 조사) — `RollingSubscriptionManager`의 모듈
         docstring은 *"현재가가 바뀌어 ATM이 이동하면 범위를 벗어난 행사가 구독을 해제하고 새로
         진입한 행사가를 구독한다"* 고 선언하지만, **`roll_to_spot()`은 WS 연결당 단 한 번**
         (`run_observation_loop` 진입부 main.py:584)만 호출되고 있었다. 그 결과:

           2026-08-03 실측 — 07:31:03 장전 기동 시점의 지수 호가 1046.81로 ATM이 1047.5에 고정됐고,
           **하루 종일 행사가 1042.50~1052.50 5개가 한 번도 바뀌지 않았다.** 정작 그날 선물
           A01609는 983.15~1015.05, 지수는 982.02~1015 구간에서 움직였다 — 즉 **하루치 옵션
           체인 전체가 스팟에서 약 5.5% 떨어진 외가격(OTM)에서 수집됐다**(수집된 옵션 체결가가
           0.01~5.00에 몰려 있는 것이 그 증거).

         이것이 §2-1의 NaN 오염을 걷어낸 뒤에도 감마플립 산출률이 0%로 남은 이유다: GEX(S)가
         탐색 구간(±5%) 어디에서도 부호를 바꾸지 않는데, 5개 행사가가 전부 한쪽(외가격)에
         몰려 있으면 콜-풋 OI 불균형의 부호가 뒤집힐 자리가 없기 때문이다.

         **선물 종가로 롤링하는 이유**: 이 함수는 WS 수신 태스크 위에서 돈다 — 구독 송신
         (`ws_client.subscribe`)을 REST 폴러 태스크에서 부르면 같은 소켓에 두 태스크가 동시에
         쓰게 된다. 선물↔지수 베이시스는 통상 행사가 간격(2.5p)의 절반 미만이라 ATM 선택이
         한 칸 어긋날 여지가 작고, 무엇보다 **REST 폴링 대상은 매니저의 `desired_strikes`에서
         나오므로 WS 구독과 체인 수집이 항상 같은 행사가 집합을 본다**(어느 쪽을 기준으로 삼든
         둘이 어긋나지 않는 것이 더 중요하다).
    실패 조건: 개별 매니저의 롤링 실패(구독 슬롯 한도 등)는 그대로 전파한다 — 구독 상태가
              불명확해진 채로 관측을 이어가면 안 된다.
    """
    rolled = False
    for subscription_manager in subscription_managers:
        before = subscription_manager.desired_strikes
        await subscription_manager.roll_to_spot(spot)
        after = subscription_manager.desired_strikes
        if before != after:
            rolled = True
            logger.info(
                LOG_ATM_ROLL,
                spot,
                f"{min(before):.1f}~{max(before):.1f}" if before else "(없음)",
                f"{min(after):.1f}~{max(after):.1f}" if after else "(없음)",
            )
    if rolled and ws_liveness is not None:
        ws_liveness.atm_roll_count += 1
        # 2026-08-07 고도화#2 — 대가는 매니저가 아니라 **공용 유지 풀**이 안다(세 북이 슬롯을
        # 공유하므로 축출도 공유 자원에서 일어난다). 매니저에서 꺼내 읽는 이유는 풀을
        # `run_observation_loop_forever` → `run_observation_loop`까지 두 겹 더 내려보내지 않기
        # 위해서다 — 매니저가 이미 그 참조를 소유하고 있고, 세 북이 같은 풀을 공유하므로
        # 아무 매니저에서 읽어도 같은 값이다. 풀이 없으면(테스트/구 경로) 0으로 남는다.
        pool = next(
            (m.retention_pool for m in subscription_managers if m.retention_pool is not None), None
        )
        if pool is not None:
            ws_liveness.atm_roll_dropped_subs = pool.dropped_subscriptions


async def run_observation_loop(
    ws_client: KISWebSocketClient,
    subscription_managers: list[RollingSubscriptionManager],
    rest_client: KISRestClient,
    futures_symbol: str,
    regime_state_machine: RegimeStateMachine,
    market_halt_monitor: MarketHaltMonitor,
    ws_liveness: WsLiveness | None = None,
) -> None:
    """
    입력: 이미 연결된 WS 클라이언트, 구독 롤링 매니저 목록(2026-07-06부터 리스트 — 먼슬리/위클리
         등 여러 만기 북을 동시에 굴리기 위함, 북마다 별도 인스턴스), REST 클라이언트, 최근월
         지수선물 단축코드(예: "101S03" — 분기마다 바뀌므로 종목코드 마스터파일/설정으로 최신화
         필요), 레짐 상태머신(mahdi.engines.regime_pipeline.RegimeStateMachine), 서킷브레이커/
         거래정지 상태머신(mahdi.risk.market_halt.MarketHaltMonitor, 2026-07-29 신규 — WS
         재연결에도 상태가 이어지도록 run_observation_loop_forever가 만들어 그대로 전달한다).
    계산: "선물옵션 시세"(inquire-price, F 시장)로 초기 스팟(KOSPI200 지수) 조회 → 모든 구독
         매니저를 그 스팟으로 롤링(각자 자기 만기 시리즈에서 ATM±N을 계산) → 선물 실시간체결가
         (H0IFCNT0)도 함께 구독(2026-07-06 추가) → 현재 선물 단축코드를 active_futures_symbol에
         등록(대시보드가 "이 종목이 선물인지" 바로 조회 가능하게) → WS 메시지 수신 → 종목(선물·
         옵션·만기북 구분 없이)별로 1분봉 완성 시 market_raw_1m 적재(각 틱에 실린 종목코드를
         그대로 사용 — 북마다 최대 14개 옵션 종목이 동시에 켜지므로 종목별 분리가 필수). 레짐은
         선물봉이 완성될 때만 regime_state_machine.step()으로 갱신한다(2026-07-10 — 레짐은
         기초자산 하나에 대한 판단이라 옵션 레그 봉 완성 타이밍과는 무관해야 함; 이전에는 모든
         종목의 봉 완성마다 재계산해 같은 분에 여러 번 덮어쓰고 있었다). 모든 종목의 틱은
         등거래량 버킷(VolumeBucketAggregator)에도 먹여 VPIN을 계산하고 그 종목의 봉에 실어
         적재한다(2026-07-06: 처음엔 선물에만 적용했으나, 옵션도 원한다는 사용자 요청으로 종목
         구분 없이 통일 — 옵션은 거래량이 얇아 버킷이 느리게 완성되거나 VPIN이 0.5 근처에 자주
         머물 수 있음을 알고 진행).
    실패 조건: DB 연결 실패·WS 단절 시 예외가 위로 전파된다. WS 단절(재연결)은
              run_observation_loop_forever가 감싸서 처리하므로, 이 함수 자체는 여전히 "한 번의
              연결이 끊기면 예외를 던지고 끝"으로 단순하게 남겨둔다(2026-07-19).

    2026-08-12(§2-1 / Fix#2) **첫 줄의 스팟 조회는 예외를 밖으로 내지 않는다.** 상세 근거는
              바로 아래 주석 — 이 함수의 진입부는 기동 경로일 뿐 아니라 **재연결 경로**이기도
              하다는 것이 그날의 교훈이다.
    """
    # ===== 2026-08-12 §2-1 / Fix#2 — 재연결 경로의 REST가 프로세스를 죽였다 =====
    #
    # 10:10:06, 이 한 줄이 KIS로부터 HTTP 500을 받았고 관측 루프 **프로세스 전체가 죽었다**.
    # `run_observation_loop_forever`의 재연결 루프는 `_WS_DISCONNECT_ERRORS`만 잡으므로
    # `httpx.HTTPStatusError`는 `asyncio.gather`까지 올라가 모든 폴러 태스크를 함께 접는다.
    #
    # ## 07-19의 설계는 틀리지 않았다 — 전제가 깨졌다
    #
    # *"연결 문제가 아닌 예외는 재시도 없이 전파한다 — 사람이 봐야 하는 코드/설정 문제이므로"*
    # 는 이 함수가 **하루 한 번** 도는 기동 경로라는 전제 위에 있었다. 08-12에 WS가 09:13~10:10
    # 사이 31회 끊겼고, 재연결마다 이 함수가 처음부터 다시 돌아 **이 호출이 31번 노출됐다.**
    # KIS의 500은 그날 24건(전체의 0.26%)으로 정상 범위다 — 치명이 된 것은 500이 아니라 노출
    # 횟수다. 500은 "사람이 봐야 하는 코드/설정 문제"가 아니라 다음 호출에 사라지는 일과성이다.
    #
    # ## 삼켜도 되는 이유 — 폴백이 **이미 있다**
    #
    # 바로 아래 `if spot > 0:`이 그것이다. 스팟이 없으면 롤링을 건너뛰고 그대로 구독/listen으로
    # 들어가며, 구독은 직전 창을 유지한다(`rebind()` 직후라면 다음 선물봉 완성 때
    # `_reroll_books_to_spot`이 정상 롤링을 회복한다 — 최대 손실은 롤링 1분 지연이다).
    #
    # **`Exception`이 아니라 `httpx.HTTPError`만 잡는다.** 여기서 넓게 잡으면 07-19가 지키려던
    # 것(코드/설정 오류는 사람이 본다)을 통째로 없앤다 — 바로 아래 `float()` 파싱 오류나 DB
    # 오류는 여전히 전파돼야 한다.
    try:
        quote = rest_client.get_quote(futures_symbol, market_div_code=tr_codes.FID_MRKT_DIV_INDEX_FUTURES)
    except httpx.HTTPError as exc:
        logger.warning(
            "기동 스팟 조회 실패 — 롤링 없이 관측을 시작한다(다음 선물봉에서 회복, 2026-08-12 Fix#2): %r",
            exc,
        )
        quote = {}
    # output3 = KOSPI200 지수 자체, output1 = 조회한 선물 계약가(베이시스 존재) — 지수 우선, 없으면 선물가로 폴백
    spot = float(quote.get("output3", {}).get("bstp_nmix_prpr") or quote.get("output1", {}).get("futs_prpr") or 0.0)
    if spot > 0:
        for subscription_manager in subscription_managers:
            await subscription_manager.roll_to_spot(spot)

    # 시세(H0IFCNT0)도 계좌 무관 공개 데이터라 모의투자 전용 도메인이 없다 — MARKET_DATA_WS_DOMAIN
    # 하나로 옵션 구독과 함께 붙는다.
    await ws_client.subscribe(Subscription(tr_codes.WS_TR_FUTURES_CONTRACT, futures_symbol))
    # 서킷브레이커/거래정지 감지(2026-07-29 신규, mahdi/risk/market_halt.py) — 같은 이유로
    # 모의 앱키로도 구독 가능.
    await ws_client.subscribe(Subscription(tr_codes.WS_TR_MARKET_OPERATION_INFO, MARKET_HALT_REFERENCE_SYMBOL))

    with db.get_connection() as conn:
        db.upsert_active_futures_symbol(conn, UNDERLYING, futures_symbol, db.local_now())
        # 2026-07-30 Fix#4: 구독 직후 현재 상태를 한 번 남겨 "감지기가 붙어 있다"를 증명한다 —
        # 값은 MarketHaltMonitor의 실제 현재 상태라 재연결 시에도 진행 중인 차단을 덮어쓰지 않는다.
        db.upsert_market_halt_state(
            conn, db.local_now(), market_halt_monitor.is_halted,
            market_halt_monitor.current_code, market_halt_monitor.label, market_halt_monitor.halted_since,
        )

    # ATM±N 구독은 최대 14개 옵션 종목(행사가×C/P) + 선물 1건을 동시에 켜두므로, 종목별로 별도
    # 집계기가 필요하다 — 하나를 공유하면 서로 다른 종목의 체결가가 한 봉에 뒤섞인다.
    aggregators: dict[str, MinuteBarAggregator] = {}
    volume_buckets: dict[str, VolumeBucketAggregator] = {}
    vpin_returns: dict[str, list[float]] = {}
    vpin_volumes: dict[str, list[float]] = {}

    market_operation_message_count = 0
    market_halt_message_touched_at = 0.0

    async def handle_market_operation_message(raw: str) -> None:
        """
        입력: H0UNMKO0 원시 메시지.
        계산: 사이드카(387/388/397/398)는 시장 자체를 정지시키지 않으므로 상태머신을 건드리지
             않고 INFO 알림만 남긴다. 그 외는 MarketHaltMonitor.update()에 맡기고, 실제로
             차단 여부가 바뀐 경우(changed)에만 DB에 기록하고 Slack을 알린다 — 이 TR은
             구독종목(005930)의 개별 VI 발동/해제 때도 메시지가 오므로(문서: "연결종목의 VI
             발동 시와 VI 해제 시에 데이터 수신") MKOP_CLS_CODE가 HALT_TRIGGER/CLEAR 밖이면
             MarketHaltMonitor가 알아서 무시한다 — 매 수신마다 DB에 쓰면 안 되는 이유이기도 하다.
        생존 계측(2026-07-30 Fix#4 → 2026-07-31 재설계): 전이가 없어도 (a) 수신 건수를 세어 첫
             수신과 이후 MARKET_HALT_RECEIVE_LOG_EVERY건마다 INFO를 남기고, (b) 마지막 수신 시각을
             `market_halt_status.last_message_at`에 남긴다(MARKET_HALT_MESSAGE_TOUCH_SECONDS
             스로틀). **"관측 루프가 살아있다"는 신호는 여기가 아니라 독립 타이머
             `poll_market_halt_heartbeat()`가 낸다** — H0UNMKO0이 세션 전이 시에만 오기 때문에
             (07-31 실측 하루 2건) 메시지 핸들러 안의 하트비트는 감지기가 죽은 것과 구분되지
             않았다(2026-07-31 §2-2). 알림(Slack)/이력 테이블은 종전대로 전이 시에만.
        """
        nonlocal market_operation_message_count, market_halt_message_touched_at

        status = _parse_market_operation(raw)
        if status is None:
            return

        market_operation_message_count += 1
        if (
            market_operation_message_count == 1
            or market_operation_message_count % MARKET_HALT_RECEIVE_LOG_EVERY == 0
        ):
            logger.info(
                "장운영정보(H0UNMKO0) 수신 %d건 — 최근 MKOP_CLS_CODE=%s(%s), 현재 차단여부=%s",
                market_operation_message_count, status.mkop_cls_code,
                MKOP_CLS_LABELS.get(status.mkop_cls_code, "정상 세션 전환/VI 등"),
                market_halt_monitor.is_halted,
            )

        # 사이드카/VI 등 어떤 코드든 "받았다"는 사실 자체는 감지기 생존의 증거이므로, 아래 분기
        # 전에 기록한다(사이드카 분기는 곧바로 return한다).
        now_monotonic = time.monotonic()
        if now_monotonic - market_halt_message_touched_at >= MARKET_HALT_MESSAGE_TOUCH_SECONDS:
            market_halt_message_touched_at = now_monotonic
            try:
                with db.get_connection() as conn:
                    db.mark_market_halt_message_seen(conn, db.local_now())
            except Exception:
                logger.warning("장운영정보 수신 시각 기록 실패 — 감지 자체에는 영향 없음", exc_info=True)

        code = status.mkop_cls_code
        if code in SIDECAR_CODES:
            notify.notify(
                f"ℹ️ {MKOP_CLS_LABELS.get(code, code)} — 프로그램매매 호가효력 일시정지(시장 자체는 정상, 신규진입 차단 없음)",
                "INFO",
            )
            return
        transition = market_halt_monitor.update(status, db.local_now())
        if not transition.changed:
            # 전이가 없으면 상태 행은 건드리지 않는다 — 위에서 last_message_at만 갱신했고,
            # updated_at은 독립 하트비트(poll_market_halt_heartbeat)의 몫이다.
            return
        with db.get_connection() as conn:
            db.upsert_market_halt_state(
                conn, db.local_now(), transition.is_halted,
                market_halt_monitor.current_code, transition.label, market_halt_monitor.halted_since,
            )
            db.append_market_halt_event_history(
                conn, db.local_now(), market_halt_monitor.current_code, transition.label, transition.is_halted,
            )
        if transition.is_halted:
            notify.notify(
                f"🚨 {transition.label}(코드 {market_halt_monitor.current_code}) — "
                f"거래소 매매정지 감지, 신규 진입 자동 차단",
                "CRITICAL",
            )
        else:
            notify.notify(f"✅ {transition.label} — 거래 재개, 신규 진입 차단 해제", "INFO")

    def handle_subscription_ack(message: dict) -> None:
        """
        입력: 파이프 텍스트가 아닌 JSON 제어 메시지.
        계산: 구독 응답(SUBSCRIBE ACK)이면 결과를 로그로 남기고, H0UNMKO0 구독이 성립한 경우
             `WsLiveness.market_op_subscribed_at`을 갱신한다(DB 기록은 하트비트가 맡는다).
        해석: 2026-08-03(§2-4 / §4 우선순위 4). 종전에는 이 메시지를 통째로 버렸는데, 08-03에
             장운영정보 데이터가 하루 0건이었을 때 **"구독이 안 걸린 것"과 "이벤트가 없었던 것"을
             구분할 방법이 없었다.** `last_message_at`에 임계를 걸 수는 없으므로(정상일에도
             0~2건) 구독 성립 쪽을 따로 본다.
        실패 조건: PINGPONG 등 구독 응답이 아닌 제어 메시지면 아무 것도 하지 않는다.
        """
        ack = KISWebSocketClient.parse_subscription_ack(message)
        if ack is None:
            return
        if ack.succeeded and ack.is_unsubscribe:
            # 2026-08-05(§2 이상점 7 / Fix#6): 해제 응답을 "구독 확립"으로 적고 있었다
            # (08-05 하루 1,218줄). ATM 롤링 때마다 나므로 로그의 상당 부분이 사실과 반대였다.
            logger.info("WS 구독 해제 확인: %s %s — %s", ack.tr_id, ack.tr_key, ack.message)
        elif ack.succeeded:
            logger.info("WS 구독 확립: %s %s — %s", ack.tr_id, ack.tr_key, ack.message)
        else:
            logger.warning(
                "WS 구독 실패: %s %s — rt_cd=%s %s %s", ack.tr_id, ack.tr_key,
                ack.rt_cd, ack.msg_code, ack.message,
            )
        # `not ack.is_unsubscribe`(2026-08-05 Fix#6): 이 값은 CB 감지의 **생존 신호**다 —
        # 해제 응답으로 갱신되면 "구독이 살아 있다"는 증거가 거꾸로 만들어진다. 지금은
        # H0UNMKO0을 해제하는 경로가 없어 잠복 상태지만, 생기는 날 조용히 틀린다.
        if (
            ack.tr_id == tr_codes.WS_TR_MARKET_OPERATION_INFO
            and ack.succeeded
            and not ack.is_unsubscribe
            and ws_liveness is not None
        ):
            subscribed_at = db.local_now()
            ws_liveness.market_op_subscribed_at = subscribed_at
            # 2026-08-04(COCKPIT 육안 점검): **여기서 DB에 즉시 쓴다.** 하트비트(300초)에만 맡기면
            # 기동 직후 5분간 NULL이 남는다 — 첫 하트비트는 구독 ACK보다 먼저 돌기 때문이다
            # (08-04 실측: 하트비트 07:31:02.7, ACK 07:31:03.2). 그 5분 동안 COCKPIT이
            # "H0UNMKO0 구독 미성립"을 띄웠고, 실제로는 구독이 성립해 있었다 — **매일 아침
            # 반복되는 오경보**이고, 전날 고친 선물 배지 오경보와 같은 종류다.
            #
            # 2026-08-01의 "메시지 핸들러에서 DB를 만지지 말라"는 원칙은 **체결 메시지 경로**
            # (초당 수십 건)를 두고 한 말이다. 구독 ACK은 기동/재연결 시에만 오는 드문 이벤트라
            # (하루 32~64건) 같은 제약을 적용할 이유가 없다.
            try:
                with db.get_connection() as conn:
                    db.mark_market_op_subscribed(conn, subscribed_at)
            except Exception:
                # 실패해도 다음 하트비트가 메모리 값을 싣고 간다 — 구독 자체에는 영향 없다.
                logger.warning("장운영정보 구독 성립 시각 기록 실패 — 하트비트가 대신 남긴다", exc_info=True)

    async def handle_message(message: dict) -> None:
        raw = message.get("raw")
        if raw is None:
            handle_subscription_ack(message)  # 구독 응답 — PINGPONG 등 나머지는 조용히 무시
            return

        # 2026-08-01(§5-4): 수신 시각은 메모리에만 남기고 DB 쓰기는 하트비트가 맡는다 —
        # 초당 수십 건 들어오는 경로라 여기서 DB를 만지면 안 된다.
        if ws_liveness is not None:
            ws_liveness.last_message_at = db.local_now()

        # H0UNMKO0(장운영정보)는 종목코드가 아니라 헤더의 TR_ID로 구분해야 한다 — 응답 바디에
        # 종목코드 필드 자체가 없다(_parse_market_operation 주석 참고).
        header_parts = raw.split("|", 3)
        if len(header_parts) >= 2 and header_parts[1] == tr_codes.WS_TR_MARKET_OPERATION_INFO:
            await handle_market_operation_message(raw)
            return

        body = raw.split("|", 3)[-1]
        peek_symbol = body.split("^", 1)[0]

        parsed = _parse_futures_tick(raw) if peek_symbol == futures_symbol else _parse_tick(raw)
        if parsed is None:
            return
        tick_symbol, tick = parsed

        bucket = volume_buckets.setdefault(tick_symbol, VolumeBucketAggregator(VPIN_BUCKET_SIZE)).add_tick(
            tick.price, tick.volume
        )
        if bucket is not None:
            returns = vpin_returns.setdefault(tick_symbol, [])
            volumes = vpin_volumes.setdefault(tick_symbol, [])
            returns.append(bucket.open_to_close_return)
            volumes.append(bucket.volume)
            if len(returns) > _VPIN_HISTORY_LIMIT:
                excess = len(returns) - _VPIN_HISTORY_LIMIT
                del returns[:excess]
                del volumes[:excess]

        aggregator = aggregators.setdefault(tick_symbol, MinuteBarAggregator())
        bar = aggregator.add_tick(tick)
        if bar is None:
            return

        with db.get_connection() as conn:
            db.insert_market_raw_1m(
                conn,
                {
                    "timestamp": bar.minute,
                    "symbol": tick_symbol,
                    "open": bar.open,
                    "high": bar.high,
                    "low": bar.low,
                    "close": bar.close,
                    "volume": bar.volume,
                    "vwap": bar.vwap,
                    "vpin": calculate_vpin(vpin_returns.get(tick_symbol, []), vpin_volumes.get(tick_symbol, [])),
                    "ofi": bar.ofi,
                    "microprice": bar.microprice,
                    "bid_ask_spread": bar.bid_ask_spread,
                    "buy_volume": bar.buy_volume,
                    "sell_volume": bar.sell_volume,
                    "quality_flag": bar.quality_flag,
                },
            )
            if tick_symbol == futures_symbol:
                # ===== 2026-08-12 §2-2 / Fix#3 — 레짐이 WS I/O **앞**에 온다 =====
                #
                # 종전 순서는 `적재 → _reroll_books_to_spot → 레짐`이었다. 재롤링은 WS로
                # subscribe/unsubscribe를 보내므로 **끊긴 소켓에서 예외를 던진다**. 그러면
                # 그 예외가 `listen()`을 뚫고 `run_observation_loop_forever`의 재연결 핸들러로
                # 올라가고, 이 아래에 있던 레짐은 **도달조차 못 한다.**
                #
                # 08-12 실측이 그 형태를 그대로 남겼다 — 선물봉(`market_raw_1m` A01609)은
                # 09:13~09:29 17분이 **전부 있는데** `regime_state`는 그 구간이 **0분**이다.
                # 같은 날 09:35~09:38(4분)·10:01~10:09(9분)까지 **30분**이 이렇게 사라졌고,
                # 로그에는 그 사실을 말하는 줄이 하나도 없었다(「WS 재연결 후 다시 끊김」 30줄이
                # 전부다). 트레이스백이 `_reroll_books_to_spot → ensure_free → unsubscribe`를
                # 정확히 가리키고 있었지만, 그것이 레짐 결손을 뜻한다는 것은 DB를 대조해야만
                # 보였다.
                #
                # ## 순서만 바꾼다 — 예외를 삼키지 않는다
                #
                # 재롤링 실패는 여전히 위로 전파돼 재연결을 태운다. **단절 감지는 그대로**이고,
                # 레짐만 그 예외 앞에서 확정된다. 예외를 여기서 삼키면 끊긴 소켓을 붙든 채
                # 계속 도는 상태가 되는데, 그것은 08-12보다 나쁜 고장이다.
                #
                # ## 대가 — 얇은 봉으로 레짐이 돈다
                #
                # 끊김 직전/직후의 봉은 틱이 빠져 얇다(08-12 09:13 봉은 volume 71, 평시 ~200).
                # 그 봉으로 레짐을 돌리는 것이 이 순서의 대가다. **새 위험은 아니다** — 그 봉은
                # 종전에도 `market_raw_1m`에 그대로 적재됐고, `quality_flag`가 이미 그것을
                # 표시한다. 바뀌는 것은 「얇은 봉으로 계산한 레짐」과 「레짐이 아예 없는 분」 중
                # 어느 쪽을 남기느냐이고, 후자는 그 사실조차 안 남는다.
                regime_state_machine.update_bar(bar)
                state = regime_state_machine.step(conn, bar.minute)
                db.insert_regime_state(
                    conn,
                    timestamp=bar.minute,
                    regime=int(state.regime),
                    prob_vector=list(state.prob_vector),
                    higher_tf_regime=int(state.higher_tf_regime) if state.higher_tf_regime is not None else None,
                    stability_flag=state.stability_flag,
                    # 2026-08-05(COCKPIT 육안 점검 P1-7, 마이그레이션 025) — `RegimeState.is_warmup`은
                    # 2026-07-10부터 필드로 있었지만 여기서 버려져 **DB에 한 번도 저장된 적이 없었다.**
                    # 그 결과 COCKPIT은 warmup_fallback()의 one-hot 상수를 학습된 사후확률과
                    # 구분하지 못하고 "평균회귀 100%"로 그렸다.
                    is_warmup=state.is_warmup,
                )
                await _reroll_books_to_spot(subscription_managers, bar.close, ws_liveness)

    await ws_client.listen(handle_message)


# WS 재연결(2026-07-19, 운영점검보고서 §5-2) — 재연결 시도 사이 대기시간. 반복적으로 계속
# 끊기는 상황(네트워크 장애 등)에서 무한정 짧은 간격으로 재시도해 KIS 서버에 부하를 주지 않도록
# 지수 백오프를 쓰되, 한 번이라도 연결에 성공하면 다음 끊김부터는 다시 초기값부터 시작한다
# (연결이 오래 잘 유지되다 어쩌다 한 번 끊긴 경우까지 계속 escalate될 이유가 없음).
WS_RECONNECT_INITIAL_BACKOFF_SECONDS = 5.0
WS_RECONNECT_MAX_BACKOFF_SECONDS = 60.0

# websockets 라이브러리 자체 예외(ConnectionClosed 등)는 WebSocketException 계열이고, 소켓 단의
# 실패(연결 거부 등)는 OSError(ConnectionError는 OSError의 서브클래스) 계열이다 — 재연결 대상은
# 이 둘뿐이다. DB 예외/ValueError(구독 슬롯 한도 등)는 재시도로 해결되지 않는 별개의 문제라
# 여기서 잡지 않고 그대로 전파해 사람이 보게 한다.
_WS_DISCONNECT_ERRORS = (OSError, websockets.WebSocketException)


async def run_observation_loop_forever(
    ws_client: KISWebSocketClient,
    subscription_managers: list[RollingSubscriptionManager],
    rest_client: KISRestClient,
    futures_symbol: str,
    regime_state_machine: RegimeStateMachine,
    market_halt_monitor: MarketHaltMonitor,
    approval_key: str,
    connect=websockets.connect,
    ws_liveness: WsLiveness | None = None,
) -> None:
    """
    입력: run_observation_loop과 동일 + 이미 연결된 첫 WS 클라이언트(호출측이 최초 1회 연결해
         넘긴다 — main()의 `async with websockets.connect(...)` 블록 안에서 만든 것), 재연결 시
         새 WS 클라이언트를 만드는 데 쓸 approval_key, connect(테스트 주입용, 기본값 websockets.connect).
    계산: run_observation_loop을 감싸 WS 단절(_WS_DISCONNECT_ERRORS) 시 프로세스를 죽이는 대신
         backoff초 대기 후 재연결한다. 2026-07-16 점검(§3-1B/§4/§5-2)에서 "WS 연결이 끊기면
         재연결 로직이 아예 없어 그대로 죽는다"고 지적된 항목 — Phase1(관측)에서는 "관측 공백"
         정도지만 Phase2가 실제 포지션을 잡기 시작하면 "포지션을 인지 못 하는" 리스크가 되므로
         Phase2 착수 전에 먼저 처리해야 한다는 게 그 이유. 재연결마다 새 KISWebSocketClient를
         만들고 모든 subscription_managers를 rebind()한다 — rebind()가 각 매니저의
         _desired_strikes를 비우므로, 다음 run_observation_loop() 안의 roll_to_spot() 호출이
         diff가 아니라 현재 ATM±N 범위 전체를 새 연결에 처음부터 다시 구독한다(그렇지 않으면
         서버 쪽 구독 상태는 재연결로 완전히 사라졌는데 매니저만 "이미 구독 중"이라고 착각해
         아무것도 재구독하지 않는 버그가 생긴다). asyncio.gather로 함께 도는 REST 폴러
         (poll_option_chain 등)는 이 함수와 독립된 태스크라 재연결 시도 중에도 계속 관측을
         이어간다 — 이번 수정 전에는 WS 단절 하나가 asyncio.run(main())까지 예외를 전파시켜
         REST 폴러까지 전부 함께 죽었다. 2026-07-19(§5-4): "연결됨→끊김" 전환 시점에 한 번,
         "끊김→재연결 성공" 전환 시점에 한 번만 Slack 알림을 보낸다(재연결 재시도마다 매번
         보내면 네트워크 장애가 길어질 때 스팸이 된다) — currently_connected 플래그로 전환
         시점만 골라낸다. 이미 끊긴 상태에서 반복되는 재연결 시도 실패 로그는(§5-5 "로그 위생")
         WarningThrottle로 60초당 최초 1건만 남긴다 — 장애가 길어지면 백오프 간격(5~60초)마다
         계속 같은 경고가 찍혀 로그 파일이 그 반복으로 파묻히는 걸 막는다.
    실패 조건: DB 오류·ValueError(구독 슬롯 한도 등) 등 연결 문제가 아닌 예외는 재시도 없이 그대로
              전파한다 — 재시도로 해결되지 않는 코드/설정 문제이므로 사람이 봐야 한다. 정상적으로는
              run_observation_loop이 listen()의 무한 수신 루프라 정상 반환하지 않지만, 혹시라도
              반환하면(예: 테스트) 재연결 없이 그대로 종료한다.
    """
    backoff = WS_RECONNECT_INITIAL_BACKOFF_SECONDS
    currently_connected = True
    warning_throttle = WarningThrottle(logger, window_seconds=WARNING_THROTTLE_WINDOW_SECONDS)
    if ws_liveness is not None:
        ws_liveness.connected_since = db.local_now()
    try:
        await run_observation_loop(
            ws_client, subscription_managers, rest_client,
            futures_symbol=futures_symbol, regime_state_machine=regime_state_machine,
            market_halt_monitor=market_halt_monitor, ws_liveness=ws_liveness,
        )
        return
    except _WS_DISCONNECT_ERRORS:
        logger.warning("WS 연결 끊김 — %.0f초 후 재연결 시도", backoff, exc_info=True)
        notify.notify("WS 연결 끊김 — 자동 재연결 시도 중. 장시간 지속되면 KIS/네트워크 상태 확인 필요.", "CRITICAL")
        currently_connected = False

    while True:
        await asyncio.sleep(backoff)
        backoff = min(backoff * 2, WS_RECONNECT_MAX_BACKOFF_SECONDS)
        try:
            async with connect(tr_codes.MARKET_DATA_WS_DOMAIN) as raw_ws:
                new_client = KISWebSocketClient(approval_key=approval_key, connection=_WebsocketsAdapter(raw_ws))
                for manager in subscription_managers:
                    manager.rebind(new_client)
                backoff = WS_RECONNECT_INITIAL_BACKOFF_SECONDS  # 연결 성공 — 다음 끊김은 다시 초기값부터
                if not currently_connected:
                    notify.notify("WS 재연결 성공 — 관측 재개.", "INFO")
                    currently_connected = True
                # 2026-08-01(§5-4): 재연결이 실제로 일어났다는 사실을 남긴다 — 07-31처럼 0회인
                # 날에도 "감지기가 붙어 있다"는 것은 독립 하트비트가 따로 증명한다.
                if ws_liveness is not None:
                    ws_liveness.connected_since = db.local_now()
                    ws_liveness.reconnect_count += 1
                    # 새 연결은 KIS 쪽 구독 상태가 전부 초기화된 상태다 — 재구독 ACK이 올
                    # 때까지는 "구독 성립"이 아니다(2026-08-03 §4 우선순위 4). 직전 연결의
                    # 시각을 그대로 두면 끊긴 구독이 살아 있는 것처럼 보인다.
                    ws_liveness.market_op_subscribed_at = None
                await run_observation_loop(
                    new_client, subscription_managers, rest_client,
                    futures_symbol=futures_symbol, regime_state_machine=regime_state_machine,
                    market_halt_monitor=market_halt_monitor, ws_liveness=ws_liveness,
                )
                return
        except _WS_DISCONNECT_ERRORS:
            if currently_connected:
                logger.warning("WS 재연결 후 다시 끊김 — %.0f초 후 재시도", backoff, exc_info=True)
                notify.notify("WS 연결 끊김 — 자동 재연결 시도 중. 장시간 지속되면 KIS/네트워크 상태 확인 필요.", "CRITICAL")
                currently_connected = False
            else:
                # 2026-07-19(§5-5): 장애가 길어지면 백오프 간격마다(5~60초) 계속 반복되는 경고 —
                # 이미 위에서 "끊김" 알림은 한 번 나갔으므로 여기선 로그 위생만 신경 쓴다.
                warning_throttle.warning(
                    "ws_reconnect_attempt_failed", "WS 재연결 시도 실패 — %.0f초 후 재시도", backoff, exc_info=True,
                )
            continue


# H0IOCNT0(지수옵션 실시간체결가) 응답 필드 인덱스 — "^" 구분, 0-based.
# 출처: docs/efriend/한국투자증권_오픈API_전체문서 시트 "지수옵션  실시간체결가"(API ID 실시간-014).
_IDX_MKSC_SHRN_ISCD = 0  # 유가증권 단축종목코드 — ATM±N 구독은 종목이 여러 개라 필수로 읽어야 함
_IDX_BSOP_HOUR = 1  # 영업시간 HHMMSS
_IDX_OPTN_PRPR = 2  # 옵션 현재가
_IDX_LAST_CNQN = 9  # 최종 거래량(해당 체결의 체결수량)
_IDX_OPTN_ASKP1 = 41  # 옵션 매도호가1
_IDX_OPTN_BIDP1 = 42  # 옵션 매수호가1
_IDX_ASKP_RSQN1 = 43  # 매도호가 잔량1
_IDX_BIDP_RSQN1 = 44  # 매수호가 잔량1
_MIN_FIELDS = _IDX_BIDP_RSQN1 + 1


def _parse_tick(raw: str, today: date | None = None) -> tuple[str, Tick] | None:
    """
    KIS 실시간 체결가(H0IOCNT0) "^" 구분 파서 — 필드 순서는 위 _IDX_* 상수 참고(공식 문서 실측).

    입력: WS로 수신한 원시 문자열 1건. KIS 실시간 프레임은 "암호화유무|TR_ID|데이터건수|실제데이터"
         형태로, 실제 "^" 구분 데이터 앞에 "|" 구분 헤더 3개가 붙어 있다(2026-07-06 실거래 중
         VARCHAR(20) 오버플로로 발견 — 헤더를 안 벗기면 0번 필드에 헤더 전체가 종목코드 앞에
         달라붙는다). idx1(BSOP_HOUR) 이후 필드는 헤더와 무관하게 그대로 정렬되므로 영향 없음.
    계산: "|"로 헤더를 먼저 제거한 뒤 "^"로 실제 필드를 나눈다. 영업시간(BSOP_HOUR, HHMMSS)을
         오늘 날짜와 결합해 틱 타임스탬프로 사용 — 수신 지연이 있어도 거래소 기준 시각으로 1분
         버킷을 나눌 수 있다. 종목코드(0번 필드)를 함께 반환한다 — ATM±N 구독은 최대 14개 종목을
         동시에 켜두므로, 어느 종목의 틱인지 모르면 서로 다른 옵션의 체결가가 한 봉에 뒤섞인다.
    실패 조건: 필드 수가 부족하거나 숫자 파싱 실패 시 None(해당 틱 무시).
    """
    body = raw.split("|", 3)[-1]  # 암호화유무|TR_ID|데이터건수 헤더 제거(헤더 없는 입력은 그대로 통과)
    fields = body.split("^")
    if len(fields) < _MIN_FIELDS:
        return None
    try:
        hhmmss = fields[_IDX_BSOP_HOUR]
        tick_time = dtime(int(hhmmss[0:2]), int(hhmmss[2:4]), int(hhmmss[4:6]))
        timestamp = datetime.combine(today or date.today(), tick_time)
        symbol = fields[_IDX_MKSC_SHRN_ISCD]
        tick = Tick(
            timestamp=timestamp,
            price=float(fields[_IDX_OPTN_PRPR]),
            volume=float(fields[_IDX_LAST_CNQN]),
            bid_px=float(fields[_IDX_OPTN_BIDP1]),
            bid_qty=float(fields[_IDX_BIDP_RSQN1]),
            ask_px=float(fields[_IDX_OPTN_ASKP1]),
            ask_qty=float(fields[_IDX_ASKP_RSQN1]),
        )
        return symbol, tick
    except (ValueError, IndexError):
        return None


# H0IFCNT0(지수선물 실시간체결가) 응답 필드 인덱스 — "^" 구분, 0-based. 옵션(H0IOCNT0)과 필드
# 순서가 다르다(가격 idx5, 매도/매수호가 idx34/35 등). 출처: docs/efriend 시트 "지수선물
# 실시간체결가"(API ID 실시간-010), 2026-07-06 실측.
_FUT_IDX_SHRN_ISCD = 0  # 선물 단축종목코드
_FUT_IDX_BSOP_HOUR = 1  # 영업시간 HHMMSS
_FUT_IDX_PRPR = 5  # 선물 현재가
_FUT_IDX_LAST_CNQN = 9  # 최종 거래량(체결량)
_FUT_IDX_ASKP1 = 34  # 선물 매도호가1
_FUT_IDX_BIDP1 = 35  # 선물 매수호가1
_FUT_IDX_ASKP_RSQN1 = 36  # 매도호가 잔량1
_FUT_IDX_BIDP_RSQN1 = 37  # 매수호가 잔량1
_FUT_MIN_FIELDS = _FUT_IDX_BIDP_RSQN1 + 1


def _parse_futures_tick(raw: str, today: date | None = None) -> tuple[str, Tick] | None:
    """
    KIS 실시간 체결가(H0IFCNT0, 지수선물) "^" 구분 파서 — 필드 순서는 위 _FUT_IDX_* 참고.

    입력/계산/실패 조건: _parse_tick과 동일한 파이프 헤더 스트립 로직을 공유한다(암호화유무|
    TR_ID|데이터건수 헤더 제거 후 "^" 분리) — 옵션과 필드 순서만 다를 뿐 헤더 형태는 동일.
    """
    body = raw.split("|", 3)[-1]
    fields = body.split("^")
    if len(fields) < _FUT_MIN_FIELDS:
        return None
    try:
        hhmmss = fields[_FUT_IDX_BSOP_HOUR]
        tick_time = dtime(int(hhmmss[0:2]), int(hhmmss[2:4]), int(hhmmss[4:6]))
        timestamp = datetime.combine(today or date.today(), tick_time)
        symbol = fields[_FUT_IDX_SHRN_ISCD]
        tick = Tick(
            timestamp=timestamp,
            price=float(fields[_FUT_IDX_PRPR]),
            volume=float(fields[_FUT_IDX_LAST_CNQN]),
            bid_px=float(fields[_FUT_IDX_BIDP1]),
            bid_qty=float(fields[_FUT_IDX_BIDP_RSQN1]),
            ask_px=float(fields[_FUT_IDX_ASKP1]),
            ask_qty=float(fields[_FUT_IDX_ASKP_RSQN1]),
        )
        return symbol, tick
    except (ValueError, IndexError):
        return None


# H0UNMKO0(국내주식 장운영정보, 통합) 응답 필드 인덱스 — "^" 구분, 0-based. 이 TR은 옵션/선물
# 체결가와 달리 응답에 종목코드 필드가 없다(Layout이 TRHT_YN부터 바로 시작) — 그래서
# handle_message는 이 TR을 심볼이 아니라 헤더의 TR_ID로 분기한다. 출처: docs/efriend 문서 "국내주식
# 장운영정보 (통합)" 시트 Response Body(2026-07-29 실측).
_MKOP_IDX_TRHT_YN = 0
_MKOP_IDX_TR_SUSP_REAS_CNTT = 1
_MKOP_IDX_MKOP_CLS_CODE = 2
_MKOP_IDX_VI_CLS_CODE = 7
_MKOP_MIN_FIELDS = 9  # TRHT_YN..EXCH_CLS_CODE 9개 필드


def _parse_market_operation(raw: str) -> MarketOperationStatus | None:
    """
    KIS 실시간 장운영정보(H0UNMKO0) "^" 구분 파서 — 필드 순서는 위 _MKOP_IDX_* 참고.

    입력/계산: 다른 파서들과 동일한 파이프 헤더 스트립(암호화유무|TR_ID|데이터건수 헤더 제거) 후
         "^" 분리. 종목코드 필드가 없으므로 반환값은 심볼 없이 상태만 담는다 — 호출측이 TR_ID로
         이 TR인지 이미 확인했다고 가정한다.
    실패 조건: 필드 수가 부족하면 None(해당 메시지 무시).
    """
    body = raw.split("|", 3)[-1]
    fields = body.split("^")
    if len(fields) < _MKOP_MIN_FIELDS:
        return None
    return MarketOperationStatus(
        trht_yn=fields[_MKOP_IDX_TRHT_YN],
        tr_susp_reas_cntt=fields[_MKOP_IDX_TR_SUSP_REAS_CNTT],
        mkop_cls_code=fields[_MKOP_IDX_MKOP_CLS_CODE],
        vi_cls_code=fields[_MKOP_IDX_VI_CLS_CODE],
    )


def _parse_option_quote(
    resp: dict, strike: float, option_type: str, poll_time: datetime
) -> tuple[dict, float] | None:
    """
    입력: KISRestClient.get_quote() 응답(output1=그릭스/IV/OI, output3=KOSPI200 지수 자체 —
         어느 옵션 종목을 조회하든 항상 지수 자체가 돌아온다), 요청한 행사가/콜풋 구분,
         폴링 시각(분 단위로 맞춰 같은 사이클 내 upsert 타임스탬프를 통일).
    계산: option_analysis_1m 1행(dict)과 기초자산 스팟을 함께 반환한다. gex는
         mahdi.features.options_intel.calculate_gex로 이 레그 하나만 넣어 즉시 계산해 저장
         (콜+/풋- 부호 규약은 calculate_gex 내부에서 처리). rv_5d는 KIS hist_vltl(과거변동성)을
         근사치로 사용 — 정확한 5일 realized vol 재계산은 Phase1 범위 밖(추후 개선 대상).
    실패 조건: 필수 필드가 없거나 숫자 변환 실패 시 None(해당 레그 스킵 — 폴링 루프가 계속 돌게 함).
    참고: 여기서 새 KIS 필드를 DB 컬럼에 매핑하기 전에 `docs/dev_memory/KIS_RAW_FIELD_RANGES.md`부터
         확인할 것 — theta가 정규화 안 된 원화 절대값이라 DECIMAL(8,6)에서 상시 오버플로우하던
         버그(2026-07-16 발견, 2026-07-21 근본원인 확정)를 반복하지 않기 위한 참고표다.
    """
    output1 = resp.get("output1") or {}
    output3 = resp.get("output3") or {}
    try:
        spot = float(output3["bstp_nmix_prpr"])
        expiry = datetime.strptime(output1["futs_last_tr_date"], "%Y%m%d").date()
        gamma = float(output1["gama"])
        iv = float(output1["hts_ints_vltl"]) / 100
        rv = float(output1["hist_vltl"]) / 100
        oi = float(output1["hts_otst_stpl_qty"])
        t_years = max((expiry - poll_time.date()).days, 0) / 365.0
        leg = OptionLeg(strike=strike, option_type=option_type.lower(), oi=oi, iv=iv, t_years=t_years, gamma=gamma)
        row = {
            "timestamp": poll_time,
            "underlying": UNDERLYING,
            "expiry": expiry,
            "strike": strike,
            "option_type": option_type,
            "delta": float(output1["delta_val"]),
            "gamma": gamma,
            "theta": float(output1["theta"]),
            "vega": float(output1["vega"]),
            "vanna": None,
            "charm": None,
            "iv": iv,
            "rv_5d": rv,
            "vrp": calculate_vrp(iv, rv),
            "skew_25d": None,
            "gex": calculate_gex([leg], spot),
            "oi": int(oi),
            "oi_change": int(float(output1["otst_stpl_qty_icdc"])),
            "volume": int(float(output1["acml_vol"])),
            "spread_state": None,
            # DB 컬럼이 아닌 진단용 필드 — _upsert()는 _OPTION_ANALYSIS_1M_COLUMNS에 있는
            # 키만 읽으므로 여기 얹어도 INSERT 쿼리에 섞이지 않는다. 2026-07-16 점검에서
            # 특정 행사가의 IV 등이 DECIMAL(8,6) 범위를 넘어 삽입이 실패하는데 원인(실제 raw
            # 값이 뭐였는지)을 알 길이 없었던 문제 — 실패 시점에 KIS 원본 응답을 그대로 로깅할
            # 수 있게 파싱 이전 output1을 함께 들고 다닌다.
            "_raw_kis_output1": output1,
        }
        return row, spot
    except (KeyError, ValueError, TypeError):
        return None


async def _collect_option_chain_cycle(
    rest_client: KISRestClient,
    books: list[tuple[RollingSubscriptionManager, str]],
    master: IndexDerivativesMaster,
    underlying: str,
    poll_time: datetime,
    warning_throttle: WarningThrottle,
    deadline: float | None = None,
) -> tuple[list[dict], float | None, bool]:
    """
    입력/계산: poll_option_chain 한 사이클분 — 북마다 행사가×콜/풋 각각에 get_quote()를 호출해
         파싱 성공한 행(option_analysis_1m용)과 마지막으로 확인된 기초자산 스팟을 모은다.
         warning_throttle은 poll_option_chain이 사이클 전체에서 공유하는 인스턴스를 그대로
         전달받는다(레그별 실패 로그를 §5-5와 동일하게 60초당 최초 1건으로 억제하기 위함,
         2026-07-20).
    실패 조건: 개별 종목 조회/파싱 실패는 건너뛰고 다음 종목을 계속 처리한다(rows에서 빠질 뿐).
              반환하는 any_strikes=False는 "아직 구독 자체가 없다"(기동 초입)를 뜻하고, rows가
              빈 리스트인 것과는 구분된다 — 호출측이 재시도 여부를 판단하는 데 쓴다.
    로그(2026-07-20): 조회 실패는 `_log_kis_call_failure`로 응답 바디(레이트리밋 등 KIS 원인
              코드)를 함께 남기고, `warning_throttle`로 반복을 억제한다 — 이전에는 매 건 풀
              트레이스백이 그대로 찍혀 로그가 파묻혔고, 원인(레이트리밋 vs 그 외)도 알 수 없었다.

    2026-08-04(§2-6 / Fix#8) `deadline`(monotonic 초, None이면 무제한): 이 시각을 지나면 남은
              레그를 **포기하고 지금까지 모은 rows로 반환한다**. 근거는
              `OPTION_CHAIN_CYCLE_COLLECT_BUDGET_SECONDS` 주석. 북 순서가 먼슬리 우선이므로
              (`_books_due_this_cycle`) 잘려나가는 쪽은 항상 위클리 뒤쪽이다 — 판단 입력인
              먼슬리가 먼저 채워지는 것이 이 순서의 존재 이유다.

    2026-08-12(§2-6 / Fix#4) **조기 포기에도 그 순서를 적용한다.** 상세 근거는 아래
              `_ABORT_SCOPE_*` 주석 — 시간 예산은 순서를 지켰는데 조기 포기(Fix#1/고도화 A)는
              사이클을 통째로 접어 **먼슬리부터 잘랐다.**
    """
    # ===== 2026-08-12 §2-6 / Fix#4 — 조기 포기가 먼슬리를 먼저 잘랐다 =====
    #
    # ## 08-12 실측
    #
    #     조기 포기(연속 타임아웃) 발동            50회
    #     그중 컷당한북에 `regular`(먼슬리) 포함    50회 (전부)
    #     그중 `regular` **단독**                   26회
    #     예산 컷(Fix#8) 발동                       74회
    #     그중 먼슬리에 닿은 것                      2회
    #
    # 시간 예산 경로에는 순서가 있고(먼슬리를 먼저 채우므로 뒤에서 잘린다), **조기 포기 경로에는
    # 없었다.** `aborted`가 서면 남은 레그를 북 구분 없이 전부 건너뛰므로, 먼슬리 폴링 도중에
    # 걸리면 아직 시작도 안 한 위클리와 함께 **먼슬리 잔여분이 같이 죽는다.**
    #
    # ## 무엇을 바꾸는가 — 두 단계로 접는다
    #
    #     1단계 `non_priority`  아직 안 부른 **비우선 북이 남아 있을 때만** 발동. 그 북들을
    #                           버리고 먼슬리는 계속 부른다. 트리거 카운터를 초기화해 먼슬리에
    #                           같은 크기의 예산을 새로 준다.
    #     2단계 `all`           1단계 뒤에 또 걸리면 그때 전부 접는다.
    #
    # ## 무엇을 **안** 바꾸는가 — 홀수분(먼슬리 단독 사이클)
    #
    # 버릴 비우선 북이 없으면 1단계를 건너뛰고 종전대로 즉시 전부 접는다. 08-12의 「`regular`
    # 단독 26회」가 그것이고, **그 26회는 위반이 아니다** — 자를 것이 먼슬리밖에 없는 사이클에서
    # 먼슬리를 자르는 것은 순서 문제가 아니다. 여기서 먼슬리에 두 번째 기회를 주면 Fix#1이
    # 어제 실측을 근거로 포기한 것(*"확정 실패 호출을 안 쏜다"*)을 하루 만에 되돌리게 된다.
    #
    # ## 왜 사이클이 길어지지 않는가
    #
    # `deadline`(50초) 검사는 이 스코프와 **독립**이다. 1단계로 살아난 먼슬리 폴링도 그 시각을
    # 넘기면 즉시 잘린다 — 즉 최악의 경우가 종전과 같은 50초다. 조기 포기가 돌려주던 시간을
    # 위클리가 아니라 **먼슬리에 쓰는 것**이지 예산을 늘리는 것이 아니다.
    _ABORT_SCOPE_NON_PRIORITY = "non_priority"
    _ABORT_SCOPE_ALL = "all"

    latest_spot: float | None = None
    rows: list[dict] = []
    any_strikes = False
    skipped = 0
    # 2026-08-06 고도화#1 — **놓친 먼슬리 레그**(실패/파싱불가/예산절단 전부). 호출측이 예산이
    # 남았을 때 이것만 다시 부른다. 우선 북 외의 실패는 담지 않는다 — 재시도 대상이 아니다.
    missing_priority: list[tuple[float, str]] = []
    # 2026-08-11 Fix#2 — **어느 북이 잘렸는가**. 08-06이 "예산 컷이 먼슬리에 닿은 분 3분"을
    # 손으로 세어 원인을 가렸는데(그 실측이 고도화#1의 방향을 정했다), 그 값이 지표로는 없었다.
    cut_books: list[str] = []
    # 2026-08-11 Fix#1 — 연속 read 타임아웃. **성공하면 0으로 되돌린다**(누적이 아니라 연속).
    consecutive_timeouts = 0
    # 2026-08-11 고도화 A — 누적 실패. 성공해도 안 줄어든다(연속 카운터가 못 보는 패턴을 잡는다).
    failed_legs = 0
    # Fix#4 1단계에서 먼슬리에 새 실패 예산을 주기 위한 기준점(그 시점의 누적 실패 수).
    failure_budget_base = 0
    abort_scope: str | None = None
    abort_reason: str | None = None
    # 1단계를 **거쳤는가**. `abort_scope`는 2단계에서 덮이므로 그것만으로는 못 본다.
    # 이 값이 True면 위클리는 **먼저 의도적으로 버려진 것**이고, 그 뒤의 먼슬리 컷은 순서
    # 위반이 아니다(순서를 지킨 결과다). 구현 중 테스트가 이 구분을 잡았다.
    dropped_non_priority_first = False
    # 2026-08-12 Fix#5 — **순서 위반의 실측**. "먼슬리가 잘렸다"가 아니라 **"아직 안 부른 위클리를
    # 두고 먼슬리를 잘랐다"**. Fix#4가 들어가면 구조적으로 0이어야 하는 불변식이고, 먼슬리 단독
    # 사이클의 꼬리 컷과 갈린다(상세 근거는 `log_metrics._priority_before_others_minutes`).
    priority_cut_before_others = False

    # 레그를 **먼저 펼친다.** 「지금 이 레그 뒤에 비우선 북이 남아 있는가」를 알아야 1단계를
    # 판단할 수 있는데, 중첩 루프 안에서는 그 질문에 답할 수 없다(앞을 못 본다).
    legs: list[tuple[str, bool, float, str, str]] = []  # (series, is_priority, strike, type, symbol)
    for subscription_manager, series in books:
        strikes = subscription_manager.desired_strikes
        if not strikes:
            continue
        any_strikes = True
        is_priority = series == OPTION_CHAIN_PRIORITY_SERIES
        for strike in sorted(strikes):
            for option_type in ("C", "P"):
                symbol = master.option_symbol(option_type, strike, underlying=underlying, series=series)
                if symbol is None:
                    continue
                legs.append((series, is_priority, strike, option_type, symbol))
    # `non_priority_ahead[i]` = i번째 레그 **뒤에** 아직 안 부른 비우선 레그가 있는가.
    non_priority_ahead = [False] * (len(legs) + 1)
    for i in range(len(legs) - 1, -1, -1):
        non_priority_ahead[i] = non_priority_ahead[i + 1] or not legs[i][1]

    # 스코프가 서도 루프를 빠져나가지 않는다 — 남은 레그를 아래 건너뛰기 분기로 흘려보내야
    # skipped/cut_books/missing_priority 회계가 완전해진다. `break`로 나가면 남은 레그가
    # **어디에도 안 세어져** 로그가 "남은 1레그"라고 거짓말한다(구현 중 테스트가 잡았다).
    # 그 경로는 REST를 한 건도 안 부르므로 순회 비용은 무시할 수 있다.
    for index, (series, is_priority, strike, option_type, symbol) in enumerate(legs):
        def _trigger(reason: str) -> None:
            """조기 포기 트리거 — 1단계(비우선만)로 접을 수 있으면 그렇게 하고, 아니면 전부 접는다."""
            nonlocal abort_scope, abort_reason, consecutive_timeouts, failure_budget_base
            nonlocal dropped_non_priority_first
            if abort_scope is None and is_priority and non_priority_ahead[index + 1]:
                abort_scope = _ABORT_SCOPE_NON_PRIORITY
                dropped_non_priority_first = True
                # 먼슬리에 같은 크기의 예산을 새로 준다 — 1단계는 "위클리를 버리고 먼슬리를
                # 계속한다"이므로, 방금 그 트리거를 먼슬리에도 그대로 물리면 즉시 2단계가 된다.
                consecutive_timeouts = 0
                failure_budget_base = failed_legs
            else:
                abort_scope = _ABORT_SCOPE_ALL
            # **처음 선 이유를 유지한다.** 컷이 시작된 원인이 그것이고, 한 사이클은 한 줄만
            # 남기므로(아래) 두 이유를 표현할 자리가 없다. 2단계 이유로 덮으면 08-11이 갈라놓은
            # 「KIS가 천장에 닿았다」와 「섞여서 죽었다」의 귀속이 다시 흐려진다.
            if abort_reason is None:
                abort_reason = reason

        cut_by_scope = abort_scope == _ABORT_SCOPE_ALL or (
            abort_scope == _ABORT_SCOPE_NON_PRIORITY and not is_priority
        )
        if cut_by_scope or (deadline is not None and time.monotonic() >= deadline):
            skipped += 1
            if series not in cut_books:
                cut_books.append(series)
            if is_priority:
                missing_priority.append((strike, option_type))
                # **위클리를 이미 버린 뒤라면 위반이 아니다.** 그때 먼슬리가 잘리는 것은 순서를
                # 지킨 결과이지 어긴 결과가 아니다 — 이 조건이 빠지면 Fix#4가 제대로 동작한
                # 사이클까지 위반으로 세어져, 불변식이 자기가 고친 것을 반증으로 찍는다.
                if non_priority_ahead[index + 1] and not dropped_non_priority_first:
                    priority_cut_before_others = True
            continue
        try:
            resp = await asyncio.to_thread(rest_client.get_quote, symbol)
        except Exception as exc:
            _log_kis_call_failure(
                f"옵션 체인 폴링 실패: {symbol}", exc,
                throttle=warning_throttle, category="option_chain_leg_fetch_failure",
            )
            if is_priority:
                missing_priority.append((strike, option_type))
            failed_legs += 1
            if isinstance(exc, httpx.ReadTimeout):
                consecutive_timeouts += 1
                if consecutive_timeouts >= OPTION_CHAIN_CONSECUTIVE_TIMEOUT_ABORT:
                    _trigger("timeout")
            else:
                consecutive_timeouts = 0
            # 고도화 A — 연속이 아니어도 누적이 예산을 넘으면 접는다. 08-11 14시대가
            # 이 형태였다(예산 초과 20건 중 전멸은 1건 — 나머지는 섞여서 얇아진 분).
            if failed_legs - failure_budget_base >= OPTION_CHAIN_CYCLE_FAILURE_BUDGET_LEGS:
                _trigger("failure_budget")
            continue
        consecutive_timeouts = 0
        parsed = _parse_option_quote(resp, strike, option_type, poll_time)
        if parsed is None:
            if is_priority:
                missing_priority.append((strike, option_type))
            continue
        row, spot = parsed
        rows.append(row)
        latest_spot = spot
    if skipped:
        # 사이클당 최대 1줄 — 레그마다 남기면 08-04 §2-2의 로그 폭증을 우리 손으로 재현한다.
        # **세 원인은 서로 다른 줄로 낸다**: 시간 예산(우리가 느렸다) / 연속 타임아웃(KIS가
        # 천장에 닿았다) / 누적 실패(섞여서 죽었다). 08-11 이전에는 셋이 한 줄이었고, 그래서
        # 22분 전멸과 "조금 잘린 분"이 같은 지표로 보고됐다.
        cut_label = ",".join(cut_books) or "—"
        violation_label = "예" if priority_cut_before_others else "아니오"
        if abort_reason == "timeout":
            logger.warning(
                LOG_CHAIN_TIMEOUT_ABORT,
                consecutive_timeouts, skipped, len(rows), cut_label, violation_label,
            )
        elif abort_reason == "failure_budget":
            remaining = (deadline - time.monotonic()) if deadline is not None else 0.0
            logger.warning(
                LOG_CHAIN_FAILURE_BUDGET,
                OPTION_CHAIN_CYCLE_FAILURE_BUDGET_LEGS, skipped, max(remaining, 0.0),
                len(rows), cut_label, violation_label,
            )
        else:
            logger.warning(
                LOG_CHAIN_BUDGET_EXCEEDED,
                OPTION_CHAIN_CYCLE_COLLECT_BUDGET_SECONDS, skipped, len(rows),
                cut_label, violation_label,
            )
    return rows, latest_spot, any_strikes, missing_priority


async def _retry_priority_legs(
    rest_client: KISRestClient,
    missing: list[tuple[float, str]],
    master: IndexDerivativesMaster,
    underlying: str,
    poll_time: datetime,
    warning_throttle: WarningThrottle,
    deadline: float | None,
) -> tuple[list[dict], float | None, int]:
    """
    입력: 놓친 먼슬리 레그 목록(`_collect_option_chain_cycle`의 4번째 반환값), 사이클 데드라인.
    반환: (회복된 행, 마지막 스팟, 시도한 레그 수).
    계산: 예산이 남아 있는 동안 먼슬리 레그만 한 번 더 조회한다. 상세 근거는
         `OPTION_CHAIN_PRIORITY_SERIES` 위 주석.
    해석: **회복이 0건인 것과 시도가 0건인 것은 다르다** — 전자는 KIS가 계속 느린 것이고,
         후자는 예산이 없었던 것이다. 그래서 시도 수를 함께 돌려주고 로그도 둘을 나란히 찍는다.
    실패 조건: 재시도의 실패는 조용히 넘어간다(원래 실패에서 이미 한 번 로그가 남았다) —
              같은 레그로 두 줄을 남기면 08-04 §2-2의 로그 폭증을 우리 손으로 되살린다.
    """
    recovered: list[dict] = []
    latest_spot: float | None = None
    attempted = 0
    for strike, option_type in missing[:OPTION_CHAIN_PRIORITY_RETRY_MAX_LEGS]:
        if deadline is not None and time.monotonic() >= deadline:
            break
        symbol = master.option_symbol(
            option_type, strike, underlying=underlying, series=OPTION_CHAIN_PRIORITY_SERIES
        )
        if symbol is None:
            continue
        attempted += 1
        try:
            resp = await asyncio.to_thread(rest_client.get_quote, symbol)
        except Exception:
            continue
        parsed = _parse_option_quote(resp, strike, option_type, poll_time)
        if parsed is None:
            continue
        row, spot = parsed
        recovered.append(row)
        latest_spot = spot
    return recovered, latest_spot, attempted


def _macro_items_due(
    last_fetched_at: dict[str, float],
    now_monotonic: float,
    item_refresh_seconds: dict[str, float] | None = None,
) -> frozenset[str]:
    """
    입력: 항목별 마지막 조회 시각(monotonic 초, 아직 한 번도 안 했으면 키 없음), 현재 monotonic 시각,
         (선택) 항목별 갱신 주기 — 기본은 `MACRO_ITEM_REFRESH_SECONDS`. 테스트가 전부 0으로 넘기면
         매 사이클 전 항목이 due가 되어 주기 분리 이전과 동일하게 동작한다(스트릭/알림 로직처럼
         조회 주기와 무관한 동작을 검증할 때 쓰는 이음새).
    계산: 주어진 항목 중 갱신 주기가 지난 것들의 집합을 반환한다.
    해석: 2026-07-31 — 매크로 항목마다 필요한 해상도가 달라 5분 사이클 안에서 선택적으로만
         조회한다(상세 근거는 `MACRO_ITEM_REFRESH_SECONDS` 주석). 첫 사이클에는 키가 없어
         전부 due가 되므로, 기동 직후에는 종전과 동일하게 모든 값이 한 번에 채워진다.
    실패 조건: 없음 — 알 수 없는 항목은 애초에 딕셔너리에 없으므로 반환되지 않는다.
    """
    refresh = MACRO_ITEM_REFRESH_SECONDS if item_refresh_seconds is None else item_refresh_seconds
    return frozenset(
        item
        for item, refresh_seconds in refresh.items()
        if now_monotonic - last_fetched_at.get(item, float("-inf")) >= refresh_seconds
    )


def _books_due_this_cycle(
    books: list[tuple[RollingSubscriptionManager, str]], poll_time: datetime
) -> list[tuple[RollingSubscriptionManager, str]]:
    """
    입력: 전체 (구독 매니저, series) 목록, 이번 사이클의 분 단위 시각.
    계산: `OPTION_CHAIN_SLOW_SERIES_PHASE`에 등록된 북(위클리 2북)은 `poll_time.minute`을
         `OPTION_CHAIN_SLOW_SERIES_EVERY_N_MINUTES`로 나눈 나머지가 **그 북에 배정된 값과 같은**
         사이클에만 포함하고, 나머지 북(먼슬리)은 항상 포함한다.
    해석: 2026-07-31 총 REST 수요 축소안 (a)의 총량(위클리 2분 주기)은 그대로 두고, 2026-08-03
         §4 우선순위 2로 **분산**만 고친다 — 상세 근거는 `OPTION_CHAIN_SLOW_SERIES_PHASE` 주석 참고.
         반환 순서는 입력 순서를 유지한다(먼슬리를 먼저 조회해 스팟/ATM IV가 항상 주력 북 기준으로
         잡히도록 — 호출측 `_update_atm_iv`가 rows 기준으로 ATM을 고르기 때문).
    실패 조건: 없음 — 알 수 없는 series는 "느린 북이 아니다"로 보아 매 사이클 포함한다(새 북을
              추가했을 때 조용히 폴링에서 빠지는 쪽보다 안전하다).

    2026-08-06 고도화#4: `OPTION_CHAIN_SLOW_SERIES_CONGESTED_HOURS`에 등록된 시간대에서는 위클리
              주기를 그 값으로 늘린다(기본은 빈 dict = 종전과 완전히 동일). **먼슬리는 어느
              시간대에도 안 건드린다** — 판단 입력이다. 상세 근거는 그 상수 위 주석.
    """
    every_n = OPTION_CHAIN_SLOW_SERIES_CONGESTED_HOURS.get(
        poll_time.hour, OPTION_CHAIN_SLOW_SERIES_EVERY_N_MINUTES
    )
    return [
        (manager, series)
        for manager, series in books
        if series not in OPTION_CHAIN_SLOW_SERIES_PHASE
        or poll_time.minute % every_n == OPTION_CHAIN_SLOW_SERIES_PHASE[series]
    ]


def _update_atm_iv(regime_state_machine: RegimeStateMachine | None, rows: list[dict], latest_spot: float | None) -> None:
    """
    입력: 레짐 상태머신(없으면 아무 것도 안 함), 이번 사이클에서 파싱된 옵션체인 행들, 최신 스팟.
    계산: **먼슬리(최근월) 북 한 개**로 좁힌 뒤, 스팟에 가장 가까운 행사가를 ATM으로 보고 그
         행사가의 콜/풋 IV 평균을 구해 RegimeFeatureBuilder의 iv_chg 롤링 윈도에 흘려넣는다
         (§7.3 ATM IV 변화율 근사 입력).

    **왜 북을 좁히는가(2026-08-10)**: 종전 구현은 `rows` 전체에서 ATM 행사가를 고르고 **그
    행사가를 가진 모든 북의 IV를 평균**했다. 그런데 위클리는 `_books_due_this_cycle()`로 격분에만
    조회되므로, 같은 행사가라도 **짝수분에는 위클리+먼슬리 평균 / 홀수분에는 먼슬리 단독**이
    된다. 08-10 실측: 짝수분 평균 IV 0.5285 vs 홀수분 0.7387 — ATM IV가 **분 단위 구형파**가 되고
    `iv_change_rate`가 매분 +0.34 / −0.29로 진동했다(전 이력 차분 자기상관 −0.900).

    피해는 레짐 엔진을 켜는 순간 드러났다. 그 진동을 학습한 HMM이 **"짝수분=TREND_UP_STRONG /
    홀수분=VOL_COMPRESSION"을 94% 일치로 재현**했고, 08-10 재생에서 분당 99.2%가 레짐 전이였다.
    `stability_flag`도 못 잡는다 — 모델은 매분 **확률 1.000으로 확신하며** 뒤집혔다.
    24영업일간 WARMUP 폴백이었기에 아무도 몰랐을 뿐, `feature_store.iv_chg`는 처음부터 오염돼 있었다.

    이 위 `_books_due_this_cycle()` docstring은 이미 *"먼슬리를 먼저 조회해 스팟/ATM IV가 항상
    주력 북 기준으로 잡히도록"* 이라고 적고 있었다 — **의도는 맞았고 구현이 그것을 안 지켰다.**
    조회 순서로는 못 지킨다. 필터가 `strike` 기준이라 뒤에 온 위클리 행이 같은 행사가면 그대로
    평균에 섞이기 때문이다. 2026-08-06 Fix#4가 체인 나이 지표에서 고친 것과 같은 계열이다
    (*"`chain_rows`가 아니라 `monthly_rows`에서 잰다"*).

    규칙 자체는 `options_intel.monthly_atm_iv()`에 있다 — **오프라인 재계산
    (`scripts/fit_regime_engine.reconstruct_iv_chg`)이 같은 함수를 쓰기 때문이다.** 학습이 쓰는
    피처와 라이브가 쓰는 피처가 다른 코드에서 나오면 그 둘이 갈라지는 것을 아무도 못 본다.
    실패 조건: 상태머신이 없거나 ATM IV를 못 구하면 건너뛴다.
    """
    if regime_state_machine is None:
        return
    atm_iv = monthly_atm_iv(rows, latest_spot)
    if atm_iv is not None:
        regime_state_machine.update_iv(atm_iv)


# 2026-08-04(고도화#5) — REST 응답시간 요약 주기. 5분이면 하루 99줄로 로그 부담이 없고
# (08-04 사람이 읽는 줄 7,539줄 대비 1.3%), 시간대별 혼잡 패턴을 보기에 충분한 해상도다.
REST_LATENCY_SNAPSHOT_SECONDS = 300.0


async def poll_rest_latency_snapshot(
    rest_client: KISRestClient,
    interval_seconds: float = REST_LATENCY_SNAPSHOT_SECONDS,
) -> None:
    """
    계산: `interval_seconds`마다 엔드포인트별 HTTP 응답시간 p50/p95/p99를 INFO 한 줄로 남긴다.
    해석: 2026-08-04 고도화#5 — §2-6이 밀림의 90%를 KIS 응답 지연으로 귀속시켰는데, 지금
         리포트는 그 지연을 **우리 지표(밀림 건수)로만** 본다. `slow_calls`는 임계(5초) 위쪽
         꼬리만 보므로 "오늘 KIS가 평소보다 느렸는가"에 답할 수 없다.

         **왜 폴러로 빼는가**: 옵션체인 사이클 끝에 붙이면 하루 445줄이 되고(그 자체가 §2-2에서
         고친 로그 폭증의 재현이다), 사이클 실패 시 계측도 함께 사라진다. 안전장치 생존 신호를
         독립 타이머로 분리한 것과 같은 원칙이다(§5-4).

         **자동 적응은 하지 않는다**: "p95가 임계를 넘으면 폴링을 줄인다"는 규칙은
         `hypotheses.yaml`(2026-08-04-p5)에 **숫자를 보기 전에** 적어뒀지만, 지연을 보고 폴링을
         바꾸면 폴링이 줄어 지연이 낮아지고 다시 폴링이 늘어나는 되먹임이 생긴다. 2026-07-08에
         페이서를 나눴다가 500 폭주로 203분을 잃은 전례가 있다 — **먼저 며칠 재고, 규칙은
         사람이 발동한다.**
    실패 조건: 표본이 없으면(그 창에 호출이 없었으면) 아무 줄도 남기지 않는다 — 장전/장후에
              매 5분 빈 줄을 찍지 않기 위함.
    """
    while True:
        await asyncio.sleep(interval_seconds)
        try:
            stats = rest_client.drain_http_latency()
        except Exception:
            logger.warning("REST 응답시간 스냅샷 실패 — 관측 자체에는 영향 없음", exc_info=True)
            continue
        if not stats:
            continue
        # `엔드포인트=n건 p50/p95/p99/max` 를 호출 수 내림차순으로 이어 붙인다.
        body = " ".join(
            f"{endpoint}={s['n']}건 {s['p50']:.2f}/{s['p95']:.2f}/{s['p99']:.2f}/{s['max']:.2f}초"
            for endpoint, s in sorted(stats.items(), key=lambda kv: kv[1]["n"], reverse=True)
        )
        logger.info(LOG_REST_LATENCY, interval_seconds, body)


async def poll_ws_heartbeat(
    ws_liveness: WsLiveness,
    interval_seconds: float = WS_HEARTBEAT_SECONDS,
) -> None:
    """
    계산: 메시지 수신과 무관하게 interval_seconds마다 `ws_status`를 upsert한다 —
         `updated_at`이 "관측 루프의 WS 파트가 살아있다"를 뜻하게 만든다.
    해석: §5-4 원칙("생존 신호는 감시 대상과 독립한 타이머에서")의 세 번째 적용이다.
         `last_message_at`은 **장중에만** 의미가 있다 — 장외에는 체결이 없어 비어 있는 게 정상이라
         COCKPIT이 장중에만 임계를 건다(CB 감지에서 배운 대로, 정상을 이상으로 표시하지 않는다).
    실패 조건: DB 기록 실패는 로그만 남기고 다음 주기를 기다린다 — 하트비트가 죽어도 WS 수신과
              재연결 자체는 계속 동작해야 한다.
    """
    while True:
        try:
            with db.get_connection() as conn:
                db.upsert_ws_status(
                    conn, db.local_now(), ws_liveness.connected_since,
                    ws_liveness.last_message_at, ws_liveness.reconnect_count,
                    ws_liveness.market_op_subscribed_at,
                    # 2026-08-05(P2-12) — 관측 연속성의 선행지표. `reconnect_count`와 같은 방식으로
                    # 관측 루프가 메모리에서 세고 이 하트비트가 DB에 남긴다.
                    ws_liveness.atm_roll_count,
                    # 2026-08-07(고도화#2) — 그 롤이 실제로 끊은 구독 수. 롤 횟수와 나란히 읽어야
                    # "창은 따라갔는데 대가는 없었다"를 말할 수 있다.
                    ws_liveness.atm_roll_dropped_subs,
                )
        except Exception:
            logger.warning("WS 하트비트 기록 실패 — 관측 자체에는 영향 없음", exc_info=True)
        await asyncio.sleep(interval_seconds)


async def poll_process_heartbeat(
    interval_seconds: float = liveness.HEARTBEAT_INTERVAL_SECONDS,
) -> None:
    """
    계산: `interval_seconds`마다 `logs/.observation_loop_heartbeat.json`에 PID와 현재 시각을
         남긴다. 워치독(`scripts/watchdog_observation_loop.py`)이 그 파일의 나이만 보고
         **관측 루프가 살아 있는지** 판정한다(2026-08-06 §2-1 / Fix#2).
    해석: 이 파일의 나이는 *"이벤트 루프가 마지막으로 스케줄을 돌린 시각"* 이다 — DB도 KIS도
         거치지 않는다. 08-06 10:04에 프로세스가 흔적 없이 사라졌을 때 그 사실을 아는 주체가
         하나도 없었고, 사람이 16분 뒤 화면을 보고 알았다.
         **다른 하트비트(WS/CB)와 달리 DB에 쓰지 않는 이유**: DB가 죽어도 이 신호는 살아야
         한다. 관측 루프가 죽는 것과 DB가 죽는 것은 다른 사건이고, 조치도 다르다.
    실패 조건: 쓰기 실패는 `liveness.write_heartbeat()` 안에서 삼킨다 — 생존 신호를 못 썼다고
              관측이 멈추면 본말이 뒤집힌다. 못 쓰면 파일이 늙고, 워치독이 그것을 본다.
    """
    beats = 0
    while True:
        beats += 1
        liveness.write_heartbeat(
            liveness.heartbeat_path(LOG_DIR), db.local_now(), beats=beats
        )
        await asyncio.sleep(interval_seconds)


async def poll_market_halt_heartbeat(
    market_halt_monitor: MarketHaltMonitor,
    interval_seconds: float = MARKET_HALT_HEARTBEAT_SECONDS,
) -> None:
    """
    입력: 관측 루프가 WS 메시지로 갱신하는 서킷브레이커/거래정지 상태머신.
    계산: **메시지 수신과 무관하게** interval_seconds마다 현재 상태를 `market_halt_status`에
         upsert한다 — `updated_at`이 "관측 루프가 이 시각까지 살아 있었다"를 뜻하게 만든다.
    해석: 2026-07-31 §2-2 / §4 우선순위 4. 07-30에 넣은 하트비트는 메시지 핸들러 안에 있어
         "메시지가 안 오면 하트비트도 멈추는" 구조였고, H0UNMKO0이 실제로는 세션 전이 시에만
         오기 때문에(07-31 하루 총 2건: 08:00·09:00) `updated_at`이 09:00:05에서 6시간 45분간
         멈춰 있었다 — 감지기가 죽은 모습과 구분되지 않았다. **생존 신호는 감시 대상과 독립한
         타이머에서 나와야 한다**는 원칙(보고서 §5-4)을 여기서 처음 적용한다.
         "감지기가 최근 실제로 무언가를 봤는가"는 별도 컬럼 `last_message_at`이 답하며, 정상일에도
         6시간 공백이 정상이므로 거기엔 임계를 두지 않는다.
    실패 조건: DB 기록 실패는 로그만 남기고 다음 주기를 기다린다 — 하트비트가 죽어도 CB 감지
              자체(WS 핸들러)는 계속 동작해야 한다.
    """
    while True:
        try:
            with db.get_connection() as conn:
                db.upsert_market_halt_state(
                    conn, db.local_now(), market_halt_monitor.is_halted,
                    market_halt_monitor.current_code, market_halt_monitor.label,
                    market_halt_monitor.halted_since,
                )
        except Exception:
            logger.warning("장운영정보 하트비트 기록 실패 — 감지 자체에는 영향 없음", exc_info=True)
        await asyncio.sleep(interval_seconds)


async def _catch_up_missed_option_chain_minute(
    rest_client: KISRestClient,
    books: list[tuple[RollingSubscriptionManager, str]],
    master: IndexDerivativesMaster,
    underlying: str,
    overran_poll_time: datetime,
    warning_throttle: WarningThrottle,
) -> bool:
    """
    입력: 방금 주기를 초과한 사이클의 poll_time, 그리고 그 사이클이 쓴 것과 같은 인자들.
    계산: 밀림으로 **통째로 건너뛴 분**을 먼슬리 북만으로 한 번 회수한다. 회수 대상 분은 "지금
         이 순간의 벽시계 분"이다 — 격자 스냅으로 다음 틱까지 대기 중이므로, 지금 분이 곧 마지막
         으로 건너뛴 분이다(예: 14:30:00 시작 사이클이 14:32:36에 끝나고 다음 틱이 14:33:00이면
         지금은 14:32분 → 14:31·14:32 중 최신인 14:32를 채운다). 반환값은 실제로 회수했는지 여부.
    해석: 2026-07-31 §2-1 / §4 우선순위 2. 07-30 Fix#3(위상 격자 스냅)은 위상 고착을 해결한
         대신 **밀림 1회 = 결손 1분을 확정**시켰다 — 종전의 즉시 재시작(`next_tick = loop_now`)은
         다음 분을 앞당겨 채우는 회수 효과가 있었는데 그 경로가 사라졌기 때문이다. 07-31 실측에서
         밀림 46건 → 결손 47분(먼슬리 커버리지 95.0% → 90.5%)으로 나타났다. 격자를 되돌리지 않고
         (되돌리면 위상 고착이 재발한다) 대기 시간 안에서 결손만 메운다.
    비용: 먼슬리 10레그뿐이다. 07-31 밀림 46건 기준 하루 +460건(총수요 0.436 → 약 0.452건/초,
         용량의 45.2%) — 목표 50% 이내를 유지한다. 위클리는 회수하지 않는다(축소안 (a)가 이미
         격분 해상도를 선택했으므로 일관).
    실패 조건: 회수 사이클이 또 밀리는 것을 막기 위해 **재귀하지 않는다**(호출측이 남은 대기
              시간이 충분할 때만 부른다). 회수할 분이 원래 사이클과 같으면(=실은 안 건너뛰었으면)
              아무 것도 하지 않는다. 조회/적재 실패는 정규 사이클과 동일하게 격리한다.
    """
    catchup_time = db.local_now().replace(second=0, microsecond=0)
    if catchup_time <= overran_poll_time:
        return False
    fast_books = [book for book in books if book[1] not in OPTION_CHAIN_SLOW_SERIES_PHASE]
    if not fast_books:
        return False

    rows, latest_spot, any_strikes, _missing = await _collect_option_chain_cycle(
        rest_client, fast_books, master, underlying, catchup_time, warning_throttle
    )
    if not any_strikes or not rows:
        return False

    try:
        with db.get_connection() as conn:
            for row in rows:
                try:
                    db.insert_option_analysis_1m(conn, row)
                except Exception:
                    warning_throttle.warning(
                        "option_chain_leg_insert_failure",
                        "옵션 체인 적재 실패(값 이상 등): strike=%s type=%s raw_kis_output1=%s",
                        row.get("strike"), row.get("option_type"), row.get("_raw_kis_output1"),
                        exc_info=True,
                    )
                    conn.rollback()
                    continue
            # 장전이면 전일 종가, **15:20 이후면 현물 단일가/종가의 잔상**이다 —
            # 어느 쪽도 실시간 스팟이 아니므로 적재하지 않는다(`session.is_equity_spot_live`
            # 주석, 2026-08-07 Fix#1·#2). 장전 차단은 2026-08-05 `9ffcb9c`가 먼저 했다.
            if latest_spot is not None and session.is_equity_spot_live(catchup_time):
                try:
                    db.insert_underlying_spot(conn, catchup_time, underlying, latest_spot)
                except Exception:
                    logger.warning("기초자산 스팟 적재 실패(결손 회수)", exc_info=True)
                    conn.rollback()
    except Exception:
        logger.warning("옵션체인 결손 회수 적재 실패 — 회수만 건너뜀", exc_info=True)
        return False

    logger.info(
        LOG_CHAIN_CATCHUP,
        catchup_time.strftime("%H:%M"), len(rows), overran_poll_time.strftime("%H:%M"),
    )
    return True


async def poll_option_chain(
    rest_client: KISRestClient,
    books: list[tuple[RollingSubscriptionManager, str]],
    master: IndexDerivativesMaster,
    underlying: str = UNDERLYING,
    interval_seconds: float = OPTION_CHAIN_POLL_INTERVAL_SECONDS,
    retry_backoff_seconds: float = CYCLE_RETRY_BACKOFF_SECONDS,
    regime_state_machine: RegimeStateMachine | None = None,
    phase_offset_seconds: float = OPTION_CHAIN_PHASE_OFFSET_SECONDS,
) -> None:
    """
    입력: REST 클라이언트, (구독 매니저, series) 튜플 목록(2026-07-06부터 리스트 — 먼슬리
         "regular" 북과 위클리(월) "weekly_mon"/위클리(목) "weekly_thu" 북을 동시에 폴링하기
         위함, 2026-07-10 위클리 분리). 각 북은 WS와 동일한 행사가
         집합을 공유), 종목코드 마스터.
    계산: 북마다 WS 구독 중인 행사가×콜/풋 각각에 대해 주기적으로 get_quote()를 호출해
         그릭스/IV/OI를 option_analysis_1m에, 기초자산 스팟을 underlying_spot_1m에 적재한다.
         **2026-07-31부터 위클리 2북은 격분(2분)에만 조회하고, 2026-08-03부터는 월/목이 서로 다른
         분 패리티를 쓴다**(`_books_due_this_cycle`/`OPTION_CHAIN_SLOW_SERIES_PHASE` 주석 참고 —
         매 분 먼슬리 1북 + 위클리 1북 = 20레그로 평탄해진다). 먼슬리는 매분 그대로다.
         get_quote()는 동기(블로킹) httpx 호출이라 asyncio.to_thread로 실행해 WS 수신 루프를
         막지 않는다. 구독 종목이 있는데 한 건도 성공하지 못했다면(레이트리밋 버스트 등으로
         사이클 전체가 실패) retry_backoff_seconds 뒤 그 사이클을 한 번만 재시도한다.
    실패 조건: 개별 종목 조회/파싱 실패는 건너뛰고 다음 종목을 계속 처리한다 — REST 폴링 중
              하나가 실패했다고 WS 관측 전체가 죽으면 안 된다. 재시도까지 실패하면 이번 사이클은
              포기하고(로그만 남김) 다음 정규 사이클(interval_seconds)로 넘어간다. 북 전부가
              아직 구독이 없으면(기동 초입) 2초 뒤 재확인.
    스케줄: "작업 후 interval만큼 sleep"이 아니라 절대시각 기준 고정 틱(next_tick)으로 다음
           사이클을 예약한다 — 사이클 소요시간(레이트리밋 대기 포함)만큼 실제 주기가 매번 밀리면
           poll_time(분 단위로 자른 시각)이 분 경계를 건너뛰어 그 분의 1분봉이 통째로 유실되는
           현상을 2026-07-09에 DB로 확인했다. 사이클이 interval_seconds보다 오래 걸려 다음 틱을
           이미 지나쳤으면 따라잡으려 하지 않되, 2026-07-30(운영점검 §2-1/§4 Fix#3)부터는 현재
           시각으로 재기준하지 않고 **원래 위상 격자의 다음 틱으로 스냅**한다(`_advance_fixed_tick`).
    알림(2026-07-19, §5-4): 마지막으로 rows를 받은 시각(last_success_time) 대비
              OPTION_CHAIN_GAP_ALERT_SECONDS(5분)를 넘겨도 재시도까지 계속 실패하면 결손을
              Slack으로 한 번 알리고(gap_alerted), 다음에 rows가 다시 들어오면 복구를 한 번
              알린다 — 매 사이클(60초)마다 반복 경고하면 스팸이 되므로 상태 전환 시점에만 보낸다.
    로그 위생(2026-07-19, §5-5): 얇은 옵션 종목의 NumericValueOutOfRange(§3-1)는 한 사이클 안에서
              레그마다(최대 수십 건) 반복 재발할 수 있다 — WarningThrottle로 60초당 최초 1건만
              실제로 로깅해 105MB까지 로테이션 없이 누적됐던 로그가 이 반복으로 다시 파묻히지
              않게 한다.
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    next_tick: float | None = None
    last_success_time: datetime | None = None
    gap_alerted = False
    warning_throttle = WarningThrottle(logger, window_seconds=WARNING_THROTTLE_WINDOW_SECONDS)
    while True:
        # 2026-07-28(운영점검보고서 2026-07-27 §4 Fix#1 후속): record_rate_limiter_status()
        # 소요시간(db_write_seconds, 아래)만 계측해서는 07-27 실측(슬로우 경고 0건)처럼 그
        # 가설이 반증돼도 다음 후보를 못 좁힌다 — 사이클 전체를 REST수집/DB적재/상태기록/기타
        # 네 구간으로 나눠 어디가 실제로 늘어나는지 매 사이클 비교할 수 있게 한다.
        cycle_started = time.monotonic()
        poll_time = _grid_poll_minute(db.local_now())
        # 2026-07-28: 공유 _RateLimiter는 이 폴러 혼자 쓰는 게 아니라 poll_investor_flow/
        # poll_expiry_liquidity/poll_macro_snapshot과 asyncio.gather로 동시에 나눠 쓴다
        # (main.py의 run_observation_loop가 KISRestClient 인스턴스 하나를 전부에 넘김) — REST수집
        # 소요시간이 이 사이클이 실제로 시도한 콜 수(own_calls_expected, 아래)만으로 설명되는지,
        # 아니면 그 사이 다른 폴러가 같은 페이서에 끼어든 콜이 있는지(rate_limit_total_calls
        # 차이로 역산) 구분하기 위해 전후 값을 남긴다. 속성이 없는 테스트 더블에서도 죽지 않게
        # getattr 기본값 None을 쓴다(있으면 실측, 없으면 "측정 불가"로 조용히 건너뜀).
        calls_before = getattr(rest_client, "rate_limit_total_calls", None)
        # 2026-07-31 총 REST 수요 축소안 (a): 위클리 2북은 격분에만 조회한다(_books_due_this_cycle).
        # 이후 이 사이클의 모든 계산(수집/재시도/자기콜수 추정)은 due_books 기준이어야 한다 —
        # 전체 books로 own_calls_expected를 세면 "타폴러동시호출추정"이 홀수 분마다 20건씩 부풀려진다.
        due_books = _books_due_this_cycle(books, poll_time)
        collect_started = time.monotonic()
        # 2026-08-04 Fix#8: 예산은 **사이클 시작 기준**으로 한 번만 잡는다. 재시도 경로도 같은
        # 데드라인을 쓰므로 "재시도 때문에 2배로 밀리는" 일이 생기지 않는다.
        collect_deadline = collect_started + OPTION_CHAIN_CYCLE_COLLECT_BUDGET_SECONDS
        rows, latest_spot, any_strikes, missing_priority = await _collect_option_chain_cycle(
            rest_client, due_books, master, underlying, poll_time, warning_throttle,
            deadline=collect_deadline,
        )
        # 2026-08-06 고도화#1 — 놓친 먼슬리 레그를 예산 안에서 한 번 더 부른다.
        # `rows`가 비어 있으면 아래 전체 재시도 경로가 어차피 전 레그를 다시 도므로 여기서는
        # 건너뛴다(같은 레그를 두 번 부르는 낭비를 막는다).
        priority_retry_calls = 0
        if rows and missing_priority:
            recovered, retry_spot, priority_retry_calls = await _retry_priority_legs(
                rest_client, missing_priority, master, underlying, poll_time,
                warning_throttle, collect_deadline,
            )
            rows.extend(recovered)
            if retry_spot is not None:
                latest_spot = retry_spot
            if priority_retry_calls:
                logger.info(
                    LOG_CHAIN_PRIORITY_RETRY,
                    priority_retry_calls, len(recovered),
                    max(collect_deadline - time.monotonic(), 0.0),
                )
        collect_seconds = time.monotonic() - collect_started

        if not any_strikes:
            next_tick = None  # 구독 전이므로 아직 고정 스케줄을 시작하지 않음
            await asyncio.sleep(2.0)
            continue

        retried = False
        own_calls_expected = sum(
            len(subscription_manager.desired_strikes) * 2
            for subscription_manager, _ in due_books
            if subscription_manager.desired_strikes
        )
        # 2026-08-04 Fix#8: 예산이 이미 끝났으면 재시도해도 전 레그가 즉시 건너뛰어져 빈손으로
        # 돌아온다 — 백오프 대기 시간만 다음 분을 더 밀 뿐이다. 이번 분은 포기하고 정시 복귀한다.
        if not rows and time.monotonic() < collect_deadline:
            logger.warning("옵션 체인 폴링 전체 실패 — %.0f초 후 재시도", retry_backoff_seconds)
            await asyncio.sleep(retry_backoff_seconds)
            retried = True
            retry_started = time.monotonic()
            rows, latest_spot, any_strikes, _missing = await _collect_option_chain_cycle(
                rest_client, due_books, master, underlying, poll_time, warning_throttle,
                deadline=collect_deadline,
            )
            collect_seconds += time.monotonic() - retry_started
            if not rows:
                logger.warning("옵션 체인 폴링 재시도도 실패 — 이번 사이클 포기")
        if not rows:
            # 2026-08-05 §2-6 — 예산 소진으로 재시도조차 못 한 경로가 여기로 떨어진다.
            # ERROR인 이유: 이 분은 판단의 주입력이 통째로 없고, 결손 지표(로그 기준)에는
            # 사이클이 돌았으므로 안 잡힌다. 상세 근거는 `LOG_CHAIN_CYCLE_EMPTY` 주석.
            logger.error(
                LOG_CHAIN_CYCLE_EMPTY,
                own_calls_expected, collect_seconds, "함" if retried else "안 함",
            )
        calls_after = getattr(rest_client, "rate_limit_total_calls", None)
        if calls_before is None or calls_after is None:
            other_poller_calls: int | None = None
        else:
            # 2026-08-06 고도화#1 — 먼슬리 재시도 콜도 **우리 몫**이다. 안 더하면 그 콜이
            # 「타폴러동시호출추정」으로 잘못 귀속돼, 08-07부터 남의 폴러가 갑자기 붐비는 것처럼
            # 보인다(07-28에 이 추정값 하나로 밀림 원인을 특정했던 계측이다 — 오염시키면 안 된다).
            own_calls_actual = own_calls_expected * (2 if retried else 1) + priority_retry_calls
            other_poller_calls = max((calls_after - calls_before) - own_calls_actual, 0)

        if rows:
            if gap_alerted:
                notify.notify("옵션 체인(option_analysis_1m) 데이터 결손 복구됨 — 정상 수신 재개.", "INFO")
                gap_alerted = False
            last_success_time = poll_time
        elif last_success_time is not None and not gap_alerted:
            gap_seconds = (poll_time - last_success_time).total_seconds()
            if gap_seconds >= OPTION_CHAIN_GAP_ALERT_SECONDS:
                notify.notify(
                    f"옵션 체인(option_analysis_1m) 데이터가 {gap_seconds / 60:.0f}분째 결손 중 — "
                    f"REST 폴링이 계속 실패하고 있습니다.",
                    "WARNING",
                )
                gap_alerted = True

        _update_atm_iv(regime_state_machine, rows, latest_spot)

        insert_started = time.monotonic()
        if rows:
            with db.get_connection() as conn:
                for row in rows:
                    try:
                        db.insert_option_analysis_1m(conn, row)
                    except Exception:
                        # 2026-07-06 위클리 도입 후 실측: 거래가 없는 얇은 종목이 IV 등에 비정상적으로
                        # 큰 값을 돌려줘 DECIMAL(8,6) 컬럼 범위를 넘는 numeric field overflow가 발생함 —
                        # 레그 하나가 죽는다고 사이클 전체(선물 틱 수신까지)가 죽으면 안 되므로 스킵.
                        # rollback 필수: psycopg는 실패한 트랜잭션에서 커밋 없이 다음 execute를 허용 안 함.
                        # 2026-07-16: strike/type만으로는 "왜" 범위를 넘었는지(delta_val이 이상한지,
                        # hts_ints_vltl이 이상한지 등) 알 수 없었다 — KIS 원본 응답(output1)을 함께
                        # 남겨 다음 재발 시 바로 원인 필드를 특정할 수 있게 한다.
                        # 2026-07-19: 같은 사이클 안에서 레그마다 반복될 수 있어(§3-1, 한 사이클에
                        # 최대 수십 건) 60초당 최초 1건만 실제로 로깅한다(§5-5).
                        warning_throttle.warning(
                            "option_chain_leg_insert_failure",
                            "옵션 체인 적재 실패(값 이상 등): strike=%s type=%s raw_kis_output1=%s",
                            row.get("strike"), row.get("option_type"), row.get("_raw_kis_output1"),
                            exc_info=True,
                        )
                        conn.rollback()
                        continue
                # 장전이면 전일 종가, **15:20 이후면 현물 단일가/종가의 잔상**이다 —
                # 근거는 `session.is_equity_spot_live` 주석(2026-08-07 Fix#1·#2).
                if latest_spot is not None and session.is_equity_spot_live(poll_time):
                    try:
                        db.insert_underlying_spot(conn, poll_time, underlying, latest_spot)
                    except Exception:
                        logger.warning("기초자산 스팟 적재 실패", exc_info=True)
                        conn.rollback()
        insert_seconds = time.monotonic() - insert_started
        other_poller_calls_text = (
            "측정불가" if other_poller_calls is None else f"{other_poller_calls}건"
        )

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                LOG_CHAIN_OVERRUN,
                interval_seconds, overrun_seconds, delay, collect_seconds, insert_seconds, len(rows),
                ", 재시도함" if retried else "", other_poller_calls_text,
            )
        # 2026-07-23(운영점검보고서 §2-1/§4 Fix#4): 관측 루프와 COCKPIT은 별도 프로세스라
        # 공유 _RateLimiter의 실시간 배율을 COCKPIT이 직접 읽을 수 없다 — 매 사이클(60초)마다
        # 싱글턴 행에 최신 배율/직전 밀림 초를 기록해 "오늘의 점검 요약" 배지가 재시작 없이
        # 바로 보게 한다. 기록 실패가 폴링 루프 자체를 막으면 안 되므로 조용히 넘어간다.
        # 2026-07-24(운영점검보고서 §2-1/§4 Fix#1): 이 기록이 07-23 밤 처음 추가된 뒤 07-24
        # 하루치 실측에서 스케줄 밀림이 임계값 원복과 무관하게 3일 연속 악화됐다 — 이 동기 DB
        # 왕복(커넥션 풀 없이 매번 새 TCP 연결을 열고 닫음)이 원인 후보다. asyncio.to_thread로
        # 옮기는 방안도 검토했으나, 위 next_tick 스케줄링을 검증하는 기존 테스트들이
        # asyncio.get_running_loop()를 시각만 반환하는 가짜 객체로 통째로 모킹해둬(to_thread
        # 내부는 실제 이벤트 루프의 run_in_executor를 요구) 제어 흐름을 바꾸면 그 모킹과 충돌해
        # 더 위험해진다. 그래서 우선은 제어 흐름은 그대로 두고 소요시간만 계측한다 —
        # time.monotonic()은 이벤트 루프 시계와 무관해 기존 스케줄링 테스트에 영향을 주지 않는다.
        db_write_started = time.monotonic()
        try:
            with db.get_connection() as conn:
                # db.local_now()를 다시 부르지 않고 이번 사이클의 poll_time을 그대로 쓴다 — 일부
                # 테스트가 db.local_now()를 정해진 시각 시퀀스로 모킹해두는데, 여기서 한 번 더
                # 부르면 그 시퀀스를 예상보다 빨리 소진시켜 poll_time 자체가 어긋난다.
                # 2026-08-01(§5-5): 누적 호출 수를 함께 남긴다 — 두 행의 차이로 "총 REST 수요
                # (건/초)"가 나와 COCKPIT이 다음날 로그 집계를 기다리지 않고 바로 볼 수 있다.
                # 속성이 없는 테스트 더블에서도 죽지 않게 getattr 기본값 None을 쓴다.
                db.record_rate_limiter_status(
                    conn, poll_time, rest_client.rate_limit_backoff_multiplier, overrun_seconds,
                    getattr(rest_client, "rate_limit_total_calls", None),
                )
                # 2026-07-29(운영점검보고서 §2-5/Fix#3): 위 싱글턴 기록은 "지금 상태"만 보존해
                # 시계열 조회가 불가능하다 — 같은 값을 append-only 테이블에도 남겨 언제부터
                # 배율이 오르기 시작했는지 등을 사후에 되짚어볼 수 있게 한다.
                db.append_rate_limiter_status_history(
                    conn, poll_time, rest_client.rate_limit_backoff_multiplier, overrun_seconds,
                    getattr(rest_client, "rate_limit_total_calls", None),
                )
        except Exception:
            logger.warning("레이트리밋 근접도 기록 실패", exc_info=True)
        db_write_seconds = time.monotonic() - db_write_started
        if db_write_seconds > RATE_LIMITER_STATUS_WRITE_SLOW_SECONDS:
            logger.warning(
                "레이트리밋 근접도 기록에 %.2f초 소요(임계 %.1f초 초과) — 스케줄 밀림 원인 후보 확인용 계측",
                db_write_seconds, RATE_LIMITER_STATUS_WRITE_SLOW_SECONDS,
            )
        # 2026-07-28: 위 db_write_seconds 계측은 07-27 실측(슬로우 경고 0건)으로 "record_rate_
        # limiter_status 쓰기가 원인"이라는 07-24 가설을 반증했다 — 다음 후보(REST수집/옵션체인
        # DB적재)를 밀린 사이클뿐 아니라 정상 사이클과도 비교할 수 있도록 매 사이클 INFO로
        # 남긴다("기타"는 위 세 구간으로 설명 안 되는 나머지 — notify.notify()의 DB 조회,
        # asyncio.to_thread 컨텍스트 스위칭, 재시도 대기(retry_backoff_seconds), 이벤트 루프
        # 스케줄링 잡음 등). WARNING이 아니라 INFO인 이유: 정상 사이클도 함께 쌓아야 "밀릴 때만
        # 유독 어떤 구간이 늘어나는지" 비교 기준선이 생긴다 — 하루 약 405사이클이라 로그 볼륨
        # 부담도 크지 않다.
        other_seconds = max(
            (time.monotonic() - cycle_started) - collect_seconds - insert_seconds - db_write_seconds,
            0.0,
        )
        logger.info(
            LOG_CHAIN_CYCLE_BREAKDOWN,
            collect_seconds, insert_seconds, db_write_seconds, other_seconds,
            len(rows), overrun_seconds, ", 재시도함" if retried else "", other_poller_calls_text,
            poll_time.strftime("%H:%M"),
        )
        if overrun_seconds > 0 and delay >= OPTION_CHAIN_CATCHUP_MIN_DELAY_SECONDS:
            # 회수에 쓴 시간만큼 남은 대기를 줄인다. 이벤트 루프 시계가 아니라 time.monotonic()을
            # 쓰는 이유는 위 db_write_seconds 계측과 같다 — 기존 스케줄링 테스트들이
            # asyncio.get_running_loop()를 정해진 시각 시퀀스로 모킹해둬 한 번 더 부르면 어긋난다.
            catchup_started = time.monotonic()
            await _catch_up_missed_option_chain_minute(
                rest_client, books, master, underlying, poll_time, warning_throttle
            )
            delay = max(delay - (time.monotonic() - catchup_started), 0.0)
        await asyncio.sleep(delay)


def _atm_liquidity_window(strikes: frozenset[float], each_side: int) -> list[float]:
    """
    입력: 구독 매니저의 ATM±STRIKES_EACH_SIDE 전체 행사가 집합(WS 구독 범위, 2026-07-10부터
         ATM±2=5개), 유동성 지표에 쓸 편측 개수(LIQUIDITY_ATM_EACH_SIDE=2 — 현재는 WS 구독
         범위와 폭이 같아 사실상 전체를 그대로 씀).
    계산: 오름차순 정렬 후 정중앙(ATM)을 기준으로 ±each_side만 잘라낸다 — strikes_around_atm()이
         항상 ATM을 중앙에 두는 대칭 격자를 만들기 때문에 정렬 후 중앙 인덱스를 잡으면 된다.
    실패 조건: strikes가 비어 있으면 빈 리스트(호출측이 이번 사이클을 건너뜀).
    """
    ordered = sorted(strikes)
    if not ordered:
        return []
    mid = len(ordered) // 2
    lo = max(mid - each_side, 0)
    hi = min(mid + each_side + 1, len(ordered))
    return ordered[lo:hi]


def _parse_asking_price_leg(resp: dict) -> dict | None:
    """
    입력: KISRestClient.get_asking_price() 응답(output1=현재가/누적거래량, output2=5단계 호가).
    계산: %스프레드(호가잔량 포함)와 누적거래량을 서로 독립적으로 파싱한다 — Cao & Wei(2010)가
         옵션은 만기·머니니스에 따라 달러 스프레드가 기계적으로 달라지므로 유동성 지표로 부적합
         하다고 지적한 근거를 따라 %스프레드를 쓴다.
    해석: 원래는 호가(ask1/bid1)가 없어 %스프레드를 못 구하면 acml_vol이 이미 찍혀 있어도 레그
         전체를 버렸다 — 2026-07-10 위클리(목)의 누적거래량이 매 사이클 0으로만 나와 조사한
         결과, 얇은 신규 위클리 종목은 순간적으로 양쪽 호가가 비는 경우가 잦아(체결은 있었지만
         지금 이 순간 MM 호가가 없는 상태) 그 레그의 실제 누적거래량까지 통째로 누락되고
         있었다. 스프레드/깊이와 거래량을 독립적으로 얻어, 호가가 없어도 거래량만은 살린다.
    실패 조건: 스프레드/깊이/거래량 셋 다 파싱 불가(필드 누락·숫자 변환 실패, 양쪽 호가 모두
              비어 mid<=0 등)면 None — 이번 레그에서 아무 것도 못 건진 경우만 집계에서 제외.
    """
    output1 = resp.get("output1") or {}
    output2 = resp.get("output2") or {}

    volume: float | None
    try:
        volume = float(output1["acml_vol"])
    except (KeyError, ValueError, TypeError):
        volume = None

    spread_pct: float | None = None
    depth: float | None = None
    try:
        ask1 = float(output2["futs_askp1"])
        bid1 = float(output2["futs_bidp1"])
        ask_qty = float(output2["askp_rsqn1"])
        bid_qty = float(output2["bidp_rsqn1"])
        mid = (ask1 + bid1) / 2
        if mid > 0:
            spread_pct = (ask1 - bid1) / mid
            depth = ask_qty + bid_qty
    except (KeyError, ValueError, TypeError):
        pass

    if volume is None and spread_pct is None:
        return None
    return {"spread_pct": spread_pct, "depth": depth, "volume": volume}


def _expiry_liquidity_books_due(
    books: list[tuple[RollingSubscriptionManager, str]], poll_time: datetime
) -> list[tuple[RollingSubscriptionManager, str]]:
    """
    입력: (구독 매니저, series) 튜플 목록, 이번 사이클의 폴링 시각.
    계산: 08:30(`EXPIRY_LIQUIDITY_FIRST_POLL_TIME`) 이전이면 **무조건 빈 목록**이고(Fix#2 —
         장전에는 호가가 없어 어떤 슬롯도 행을 남기지 못한다), 그 뒤로는
         `EXPIRY_LIQUIDITY_BOOK_SLOT_MINUTES`가 books 인덱스별로 지정한 `minute % 10` 슬롯과
         일치하는 북만 돌려준다 — 슬롯이 아닌 분에는 빈 리스트(이번 분은 조회 안 함).
    해석: 2026-07-31 §2-1 원인(a) — 3북 33콜을 한 번에 쏘던 것을 북 하나씩 홀수분에 흩는다.
         상세 근거는 `EXPIRY_LIQUIDITY_BOOK_SLOT_MINUTES` 주석 참고. 슬롯 배정을 벽시계 분으로
         하므로 재시작해도 위상이 같다(축소안 (a)의 `_books_due_this_cycle`과 동일 원칙).
    실패 조건: 슬롯 튜플보다 북이 많으면 초과분은 영영 조회되지 않는다 —
              `test_expiry_liquidity_slots_cover_every_book`이 이 불일치를 잡는다.
    """
    if poll_time.time() < EXPIRY_LIQUIDITY_FIRST_POLL_TIME:
        return []
    slot = poll_time.minute % EXPIRY_LIQUIDITY_WINDOW_MINUTES
    return [
        book
        for index, book in enumerate(books)
        if index < len(EXPIRY_LIQUIDITY_BOOK_SLOT_MINUTES)
        and EXPIRY_LIQUIDITY_BOOK_SLOT_MINUTES[index] == slot
    ]


async def poll_expiry_liquidity(
    rest_client: KISRestClient,
    books: list[tuple[RollingSubscriptionManager, str]],
    master: IndexDerivativesMaster,
    underlying: str = UNDERLYING,
    interval_seconds: float = EXPIRY_LIQUIDITY_POLL_INTERVAL_SECONDS,
    phase_offset_seconds: float = 0.0,
) -> None:
    """
    입력: REST 클라이언트, (구독 매니저, series) 튜플 목록(먼슬리 "regular" + 위클리(월)
         "weekly_mon" + 위클리(목) "weekly_thu", 2026-07-10 위클리 분리),
         종목코드 마스터, 벽시계 위상(phase_offset_seconds — 2026-07-09 추가: poll_option_chain과
         동시에 기동하면 두 폴러의 정규 사이클이 계속 같은 순간에 겹쳐 공유 레이트리미터 큐가
         길어지므로 사이클 시작 시각을 어긋나게 둔다. 2026-07-31부터 이 값은 기동 시각이 아니라
         **벽시계 자정 기준 위상**이다 — `_seconds_until_next_wall_tick` 참고).
    계산: **2026-07-31부터 이 폴러는 매 분 돌되 그 분의 슬롯에 배정된 북 하나만 조회한다**
         (`_expiry_liquidity_books_due` — 홀수분 1/3/5, 한 바퀴 = 10분). 종전에는 600초마다
         3북 33콜을 한 번에 쏴서 중앙 55.5초(최대 109초)를 점유했고, 그게 2분대 짝수분 옵션체인
         사이클을 통째로 덮어 밀림 17건(전체의 37%)을 만들었다. 총 호출량은 완전히 동일하다.
         북마다 ATM±2(_atm_liquidity_window) 구간의 콜/풋 각각에 get_asking_price()를 호출해
         %스프레드·깊이·거래량을 집계하고, 만기일은 ATM 종목 1건만 get_quote()로 별도 확인해
         (_parse_option_quote 재사용) expiry_liquidity_1m에 적재한다. 만기 확인용 get_quote()는
         북당 사이클당 1건뿐이라 REST 부하에 미치는 영향은 무시할 만하다. poll_option_chain과
         동일하게 절대시각 고정 틱(next_tick)으로 다음 사이클을 예약해 사이클 소요시간에 따라
         실제 주기가 매번 밀리지 않게 한다.
         북별 적재 시각이 1/3/5분으로 갈리지만, `db.latest_expiry_liquidity()`가 원래부터
         `DISTINCT ON (series)`로 북별 최신값을 취하므로 COCKPIT 표시에는 영향이 없다.
    실패 조건: 개별 레그 조회/파싱 실패는 건너뛰고 나머지로 계속 집계한다. 유효한 레그가 하나도
              없거나 만기를 확인하지 못하면 그 북은 이번 사이클을 건너뛴다. 슬롯 북에 아직 구독
              행사가가 없으면(기동 초입) 2초 뒤 재확인.
    로그(2026-07-20): REST 조회 실패는 poll_option_chain과 동일하게 `_log_kis_call_failure`로
              응답 바디를 남기고 `warning_throttle`로 반복을 억제한다 — 만기확인용 get_quote()
              실패는 이전엔 아예 로그도 안 남기고 조용히 삼켰다(원인 추적 불가능한 사각지대였음).
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    next_tick: float | None = None
    warning_throttle = WarningThrottle(logger, window_seconds=WARNING_THROTTLE_WINDOW_SECONDS)
    while True:
        poll_time = _grid_poll_minute(db.local_now())
        due_books = _expiry_liquidity_books_due(books, poll_time)
        any_strikes = False
        rows: list[dict] = []
        for subscription_manager, series in due_books:
            window = _atm_liquidity_window(subscription_manager.desired_strikes, LIQUIDITY_ATM_EACH_SIDE)
            if not window:
                continue
            any_strikes = True

            atm_strike = window[len(window) // 2]
            anchor_symbol = master.option_symbol("C", atm_strike, underlying=underlying, series=series)
            expiry = None
            if anchor_symbol is not None:
                try:
                    anchor_resp = await asyncio.to_thread(rest_client.get_quote, anchor_symbol)
                    parsed_anchor = _parse_option_quote(anchor_resp, atm_strike, "C", poll_time)
                except Exception as exc:
                    _log_kis_call_failure(
                        f"만기 유동성 만기확인 조회 실패: {anchor_symbol}", exc,
                        throttle=warning_throttle, category="expiry_liquidity_anchor_fetch_failure",
                    )
                    parsed_anchor = None
                if parsed_anchor is not None:
                    expiry = parsed_anchor[0]["expiry"]
            if expiry is None:
                continue

            spread_values: list[float] = []
            depth_total = 0.0
            volume_total = 0.0
            for strike in window:
                for option_type in ("C", "P"):
                    symbol = master.option_symbol(option_type, strike, underlying=underlying, series=series)
                    if symbol is None:
                        continue
                    try:
                        resp = await asyncio.to_thread(rest_client.get_asking_price, symbol)
                    except Exception as exc:
                        _log_kis_call_failure(
                            f"만기 유동성 폴링 실패: {symbol}", exc,
                            throttle=warning_throttle, category="expiry_liquidity_leg_fetch_failure",
                        )
                        continue
                    parsed_leg = _parse_asking_price_leg(resp)
                    if parsed_leg is None:
                        continue
                    if parsed_leg["spread_pct"] is not None:
                        spread_values.append(parsed_leg["spread_pct"])
                    if parsed_leg["depth"] is not None:
                        depth_total += parsed_leg["depth"]
                    if parsed_leg["volume"] is not None:
                        volume_total += parsed_leg["volume"]

            if not spread_values:
                continue

            rows.append(
                {
                    "timestamp": poll_time,
                    "underlying": underlying,
                    "series": series,
                    "expiry": expiry,
                    "atm_spread_pct": sum(spread_values) / len(spread_values),
                    "depth": depth_total,
                    "volume": volume_total,
                    "days_to_expiry": max((expiry - poll_time.date()).days, 0),
                }
            )

        # 슬롯이 아닌 분(due_books 비어 있음)은 "구독 전"이 아니라 정상적인 무작업 사이클이므로
        # 워밍업 재확인 경로로 새면 안 된다 — 그러면 위상 격자가 매 분 리셋된다(2026-07-31).
        if due_books and not any_strikes:
            next_tick = None  # 구독 전이므로 아직 고정 스케줄을 시작하지 않음
            await asyncio.sleep(2.0)
            continue

        if rows:
            with db.get_connection() as conn:
                for row in rows:
                    try:
                        db.insert_expiry_liquidity_1m(conn, row)
                    except Exception:
                        logger.warning("만기 유동성 적재 실패: series=%s", row.get("series"), exc_info=True)
                        conn.rollback()
                        continue

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                "만기 유동성 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기",
                interval_seconds, overrun_seconds, delay,
            )
        await asyncio.sleep(delay)


def _parse_overseas_future_last_price(resp: dict) -> float | None:
    """입력: get_overseas_future_price() 응답. 계산: output1.last_price를 float로(KIS 필드는
    앞에 공백 패딩이 있으나 float()가 알아서 무시한다). 실패 조건: 필드 없음/변환 불가면 None."""
    try:
        return float(resp["output1"]["last_price"])
    except (KeyError, ValueError, TypeError):
        return None


def _parse_overseas_daily_last_price(resp: dict) -> float | None:
    """입력: get_overseas_daily_chartprice() 응답(국채구분 I/환율구분 X 등 공통 스키마). 계산:
    output1.ovrs_nmix_prpr(최신 종가 — I구분이면 수익률%, X구분이면 환율)를 float로. 실패 조건:
    필드 없음/변환 불가면 None."""
    try:
        return float(resp["output1"]["ovrs_nmix_prpr"])
    except (KeyError, ValueError, TypeError):
        return None


def _log_kis_call_failure(
    message: str,
    exc: Exception,
    *,
    throttle: WarningThrottle | None = None,
    category: str | None = None,
) -> None:
    """
    입력: 로그 메시지, 발생한 예외, (선택) 반복 경고 억제용 WarningThrottle과 그 category.
    계산: httpx.HTTPStatusError는 KIS의 실제 에러 코드/메시지(rt_cd/msg_cd/msg1)가 응답 바디에
         있는데, raise_for_status()가 만드는 예외 메시지 자체엔 그게 안 실려 그냥 재로깅하면
         "Server error 500"만 남고 원인(레이트리밋/계좌 미신청/일시 장애 등)을 구분할 수 없다
         (2026-07-10 CBOT 신청 후에도 ZN 조회가 500을 반복해 원인 확인 중 필요해짐) — 바디
         텍스트를 함께 남긴다.
         2026-07-20: `_collect_option_chain_cycle`의 레그별 조회 실패처럼 한 사이클 안에서 레그마다
         (최대 수십 건) 반복 재발할 수 있는 호출측은 throttle/category를 함께 넘기면 §5-5와 동일한
         패턴(WarningThrottle)으로 억제된다. 매크로 스냅샷처럼 사이클당 호출이 1건뿐이라 반복
         스팸 우려가 없는 호출측은 throttle을 안 넘기면 기존처럼 즉시 로깅된다.
         2026-08-03(운영점검보고서 §2-8 / §4 우선순위 3): **HTTPStatusError에는 트레이스백을
         붙이지 않는다.** 이 경우 원인은 이미 응답 바디에 전부 실려 있고(rt_cd/msg_cd/msg1),
         스택은 항상 같은 세 프레임(`_collect_*_cycle` → `to_thread` → `_get`)이라 정보가 0이다.
         08-03 실측: 이 트레이스백만 하루 약 1,700줄이었고 그중 306줄이 ZN/ES 해외시세 18건인데,
         그건 "CBOT/CME SUB거래소 신청 계좌가 아닙니다"라는 **계정 권한 문제라 코드로는 절대
         해결되지 않는 항상 실패**다. 반대로 HTTPStatusError가 **아닌** 예외(파싱 오류, 예상 못 한
         런타임 오류 등)는 어디서 났는지가 곧 원인이므로 트레이스백을 그대로 남긴다.
    실패 조건: 없음 — 로깅 자체는 항상 성공한다고 가정.
    """
    if isinstance(exc, httpx.HTTPStatusError):
        fmt, args, exc_info = "%s — %s", (message, exc.response.text), False
    else:
        keep, nth = _TRACEBACK_BUDGET.take(exc)
        if keep:
            fmt, args, exc_info = "%s", (message,), True
        else:
            # 2026-08-05 §2-4 — 표본을 다 썼다. 트레이스백 대신 **유형·메시지·누적 건수**를
            # 한 줄로 남긴다. 유형 표기가 트레이스백 마지막 줄과 같아야 집계가 유형을 잃지
            # 않는다(상세 근거는 `TracebackBudget.type_name`).
            fmt = LOG_KIS_FAILURE_TRACEBACK_OMITTED
            args = (message, exc, TracebackBudget.type_name(exc), nth)
            exc_info = False
    if throttle is not None and category is not None:
        throttle.warning(category, fmt, *args, exc_info=exc_info)
    else:
        logger.warning(fmt, *args, exc_info=exc_info)


async def _collect_macro_snapshot_cycle(
    rest_client: KISRestClient,
    overseas_master: OverseasFutureMaster,
    poll_time: datetime,
    due_items: frozenset[str] = frozenset(MACRO_ITEM_REFRESH_SECONDS),
) -> dict | None:
    """
    입력: REST 클라이언트, 해외선물 종목코드 마스터, 폴링 시각(분 단위로 자름), 이번 사이클에
         조회할 저빈도 항목 집합(`_macro_items_due()` 결과 — 기본값은 전부 조회라 기존 호출부/
         테스트는 종전과 동일하게 동작한다).
    계산: VIX 선물(CBOE VX) 근월·차근월, USDCNH 선물(HKEx CNH) 근월 현재가를 조회해 콘탱고/
         백워데이션(vix_term_structure = vix_next/vix_front - 1)을 계산하고, US10Y·USDKRW는 일봉
         API(해외주식 종목_지수_환율기간별시세, 국채구분 I / 환율구분 X)로 최신 종가를, ZN·ES
         선물(둘 다 CME 상장) 근월물 현재가로 5분 주기 급변 감지용 값을, MOVE(ICE BofA MOVE
         Index)는 yfinance 전용으로 함께 담는다.
         - ZN·ES: CME 계열 실시간시세는 KIS 유료 항목(2026-07-20 HTS [7936] 확인: 월 228.8불,
           ZN은 CME|CBOT·ES는 CME|CME 서브거래소로 별개 구독)이라 모의투자 개발 단계에서는
           미구독 상태다 — KIS 조회가 안 되면(마스터 미매핑·EGW00552 등)
           mahdi/data/yfinance_fallback.py로 대신 채우고, *_source 필드("kis"|"yfinance_fallback"|
           None)로 실제 출처를 구분한다.
         - USDKRW: 해외선물옵션이 아니라 해외주식 도메인(inquire-daily-chartprice)이라 애초에
           CBOT 같은 SUB거래소 신청 게이트가 없다 — US10Y와 동일하게 계좌 제약 없이 무료로 얻는다.
         - MOVE: 장외 파생 인덱스라 KIS 해외선물옵션 마스터파일에 상품 자체가 없음 — KIS 경로가
           없으므로 처음부터 yfinance_fallback만 시도한다.
         종목코드를 마스터에서 못 찾거나 개별 조회가 실패해도 나머지 필드는 계속 채운다(부분 실패
         허용).
    실패 조건: vix_front/vix_next/usdcnh 셋 다 실패하면(레이트리밋 버스트 등) None을 반환해
              호출측이 이번 사이클 적재를 건너뛰게 한다 — 나머지 필드만 성공한 상태로 5분 행을
              남기는 건 의미가 없다.
    """
    vix_front_code, vix_next_code = overseas_master.front_two_codes(tr_codes.OVERSEAS_FUTURE_PRODUCT_VIX)
    cnh_front_code, _ = overseas_master.front_two_codes(tr_codes.OVERSEAS_FUTURE_PRODUCT_CNH)
    zn_front_code, _ = overseas_master.front_two_codes(tr_codes.OVERSEAS_FUTURE_PRODUCT_ZN)
    es_front_code, _ = overseas_master.front_two_codes(tr_codes.OVERSEAS_FUTURE_PRODUCT_ES)

    vix_front = vix_next = usdcnh = None
    if vix_front_code is not None:
        try:
            vix_front = _parse_overseas_future_last_price(
                await asyncio.to_thread(rest_client.get_overseas_future_price, vix_front_code)
            )
        except Exception as exc:
            _log_kis_call_failure(f"VIX 근월물 조회 실패: {vix_front_code}", exc)
    if vix_next_code is not None:
        try:
            vix_next = _parse_overseas_future_last_price(
                await asyncio.to_thread(rest_client.get_overseas_future_price, vix_next_code)
            )
        except Exception as exc:
            _log_kis_call_failure(f"VIX 차근월물 조회 실패: {vix_next_code}", exc)
    if cnh_front_code is not None:
        try:
            usdcnh = _parse_overseas_future_last_price(
                await asyncio.to_thread(rest_client.get_overseas_future_price, cnh_front_code)
            )
        except Exception as exc:
            _log_kis_call_failure(f"USDCNH 선물 조회 실패: {cnh_front_code}", exc)

    if vix_front is None and vix_next is None and usdcnh is None:
        return None

    date_to = poll_time.strftime("%Y%m%d")
    date_from = (poll_time - timedelta(days=US10Y_LOOKBACK_DAYS)).strftime("%Y%m%d")

    # 2026-07-31: 아래 항목들은 due_items에 들어있는 사이클에만 조회한다(주기별 근거는
    # MACRO_ITEM_REFRESH_SECONDS 주석). 조회하지 않은 항목은 이 행에서 None으로 남고,
    # db.latest_macro_snapshot()이 직전 값으로 LOCF(forward-fill)해 COCKPIT 표시가 끊기지 않는다.
    us10y_yield = None
    usdkrw = None
    if "daily_series" in due_items:
        try:
            us10y_yield = _parse_overseas_daily_last_price(
                await asyncio.to_thread(
                    rest_client.get_overseas_daily_chartprice,
                    tr_codes.FID_MRKT_DIV_OVERSEAS_TREASURY,
                    tr_codes.FID_INPUT_ISCD_US10Y,
                    date_from,
                    date_to,
                )
            )
        except Exception as exc:
            _log_kis_call_failure("US10Y 일봉 조회 실패", exc)

        try:
            usdkrw = _parse_overseas_daily_last_price(
                await asyncio.to_thread(
                    rest_client.get_overseas_daily_chartprice,
                    tr_codes.FID_MRKT_DIV_OVERSEAS_FX,
                    tr_codes.FID_INPUT_ISCD_USDKRW,
                    date_from,
                    date_to,
                )
            )
        except Exception as exc:
            _log_kis_call_failure("USDKRW 일봉 조회 실패", exc)

    zn_front = None
    zn_front_source = None
    if "zn" in due_items:
        if zn_front_code is not None:
            try:
                zn_front = _parse_overseas_future_last_price(
                    await asyncio.to_thread(rest_client.get_overseas_future_price, zn_front_code)
                )
                if zn_front is not None:
                    zn_front_source = "kis"
            except Exception as exc:
                _log_kis_call_failure(f"ZN(10년 국채선물) 근월물 조회 실패: {zn_front_code}", exc)

        if zn_front is None:
            # CME|CBOT 실시간시세는 KIS 유료 항목(HTS [7936] 확인: 월 228.8불)이라 모의투자 개발
            # 단계에서는 미구독 상태다 — KIS 조회가 안 됐을 때만(마스터 미매핑이든 호출 실패든)
            # 여기서 yfinance 폴백을 시도한다. 폴백도 실패하면 zn_front_source는 None으로 남는다.
            zn_front = await asyncio.to_thread(
                yfinance_fallback.fetch_last_close, yfinance_fallback.ZN_FALLBACK_SYMBOL
            )
            if zn_front is not None:
                zn_front_source = "yfinance_fallback"

    es_front = None
    es_front_source = None
    # ES는 macro_score의 실제 입력이라 **값 자체는 매 사이클** 갱신한다 — 저빈도로 돌리는 건
    # 100% 실패가 확정된 KIS 시도(es_kis_probe)뿐이고, 값은 아래 yfinance 폴백이 계속 채운다.
    if "es_kis_probe" in due_items and es_front_code is not None:
        try:
            es_front = _parse_overseas_future_last_price(
                await asyncio.to_thread(rest_client.get_overseas_future_price, es_front_code)
            )
            if es_front is not None:
                es_front_source = "kis"
        except Exception as exc:
            _log_kis_call_failure(f"ES(E-mini S&P500) 근월물 조회 실패: {es_front_code}", exc)

    if es_front is None:
        # CME|CME(ES) 실시간시세도 ZN(CME|CBOT)과 마찬가지로 KIS 유료 항목 — 미구독 상태에서는
        # yfinance 폴백으로 대신 채운다.
        es_front = await asyncio.to_thread(yfinance_fallback.fetch_last_close, yfinance_fallback.ES_FALLBACK_SYMBOL)
        if es_front is not None:
            es_front_source = "yfinance_fallback"

    # MOVE(ICE BofA MOVE Index)는 장외 파생 인덱스라 KIS 해외선물옵션 마스터파일에 상품 자체가
    # 없다 — KIS 시도 없이 처음부터 yfinance 폴백만 쓴다.
    move_index = None
    move_index_source = None
    if "move" in due_items:
        move_index = await asyncio.to_thread(
            yfinance_fallback.fetch_last_close, yfinance_fallback.MOVE_FALLBACK_SYMBOL
        )
        move_index_source = "yfinance_fallback" if move_index is not None else None

    vix_term_structure = (vix_next / vix_front - 1) if (vix_front and vix_next) else None

    return {
        "timestamp": poll_time,
        "vix_front": vix_front,
        "vix_next": vix_next,
        "vix_term_structure": vix_term_structure,
        "usdcnh": usdcnh,
        "us10y_yield": us10y_yield,
        "usdkrw": usdkrw,
        "zn_front": zn_front,
        "zn_front_source": zn_front_source,
        "es_front": es_front,
        "es_front_source": es_front_source,
        "move_index": move_index,
        "move_index_source": move_index_source,
        "quality_flag": 0 if (vix_front is not None and vix_next is not None and usdcnh is not None) else 1,
    }


async def poll_macro_snapshot(
    rest_client: KISRestClient,
    overseas_master: OverseasFutureMaster,
    interval_seconds: float = MACRO_SNAPSHOT_POLL_INTERVAL_SECONDS,
    phase_offset_seconds: float = 0.0,
    item_refresh_seconds: dict[str, float] | None = None,
) -> None:
    """
    입력: REST 클라이언트, 해외선물 종목코드 마스터(main() 기동 시 1회 로드), 기동 시 최초
         사이클을 지연시킬 초(startup_offset_seconds — 2026-07-28 추가: poll_expiry_liquidity의
         2026-07-09 패턴과 동일 — 오프셋 없이는 매 5분마다 poll_option_chain과 같은 순간에
         겹친다).
    계산: Cross-asset stress 원시값(VIX 기간구조·USDCNH·US10Y, v6 §7.3)을 5분 주기로
         macro_snapshot_5m에 적재한다. poll_option_chain/poll_investor_flow와 동일하게 절대시각
         고정 틱(next_tick)으로 다음 사이클을 예약해 사이클 소요시간에 따라 실제 주기가 밀리지
         않게 한다.
    실패 조건: 이번 사이클 전체가 실패하면(_collect_macro_snapshot_cycle이 None) 적재를
              건너뛰고 다음 정규 사이클을 기다린다 — 재시도 백오프는 두지 않는다(사이클당
              REST 호출이 4건뿐이라 다른 폴러만큼 레이트리밋에 취약하지 않음).
    알림(2026-07-19, §5-4; 2026-07-20 문구 갱신; 2026-07-24 스트릭 조건 추가): zn_front가
              ZN_DUAL_FAILURE_ALERT_STREAK회 연속(KIS 미구독 + yfinance 폴백까지 실패 — 둘 다
              안 되는 경우만 해당, yfinance_fallback.py 참고) None이면 Slack으로 한 번만
              알린다. 2026-07-24 운영점검보고서 §2-3: 이 이중 실패가 07-22/07-23/07-24 3일
              연속 13:01 근처(±5초)로 재현돼 우연이 아닌 것으로 확정됐지만, 그렇다고 매
              사이클(5분) 첫 실패에 바로 알리면 몇 분짜리 일시적 블립까지 결손으로 보고하게
              된다 — insert_failure_streak와 동일한 패턴으로 연속 실패가 누적돼야만 알린다
              (한 번이라도 성공하면 스트릭만 0으로 리셋). cbot_alert_sent 자체는 기존 설계
              그대로 이 프로세스 실행당(=거래일당) 영구 latch를 유지한다 — 정규장 최대
              78사이클 동안 간헐적으로 반복 실패할 경우까지 재알림하면 스팸이 되기 때문
              (2026-07-19 결정 유지, 스트릭 조건은 "언제" 그 최초 1회를 보낼지만 늦춘다).
    알림(2026-07-21 추가): INSERT 자체가 MACRO_SNAPSHOT_INSERT_FAILURE_ALERT_STREAK회 연속
              실패하면(2026-07-21 실측: 마이그레이션 라이브 미적용으로 UndefinedColumn이 종일
              반복됐는데 로그에만 WARNING으로 남고 아무도 알아채지 못함) Slack으로 알린다. 이후
              한 번이라도 성공하면 복구 알림을 보내고 스트릭/알림 상태를 리셋 — gap_alerted
              (poll_option_chain)와 동일한 "지속되면 알리고, 회복되면 알린다" 패턴.
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    next_tick: float | None = None
    cbot_alert_sent = False
    zn_dual_failure_streak = 0
    insert_failure_streak = 0
    insert_failure_alerted = False
    # 2026-07-31: 항목별 마지막 조회 시각(monotonic). 첫 사이클에는 비어 있어 전부 due가 된다.
    macro_last_fetched_at: dict[str, float] = {}
    while True:
        poll_time = _grid_poll_minute(db.local_now())
        fetch_started = time.monotonic()
        due_items = _macro_items_due(macro_last_fetched_at, fetch_started, item_refresh_seconds)
        row = await _collect_macro_snapshot_cycle(rest_client, overseas_master, poll_time, due_items)
        if row is not None:
            # 조회를 실제로 시도한 항목만 "했다"고 기록한다 — row가 None이면 VIX/USDCNH 전부 실패로
            # 조기 반환된 것이라 저빈도 항목은 시도조차 안 됐다(다음 사이클에 다시 due로 남는다).
            for item in due_items:
                macro_last_fetched_at[item] = fetch_started

        if row is None:
            logger.warning("매크로 스냅샷 폴링 전체 실패 — 이번 사이클 건너뜀")
        else:
            insert_ok = True
            with db.get_connection() as conn:
                try:
                    db.insert_macro_snapshot_5m(conn, row)
                except Exception:
                    logger.warning("매크로 스냅샷 적재 실패", exc_info=True)
                    conn.rollback()
                    insert_ok = False
            if insert_ok:
                if insert_failure_alerted:
                    notify.notify("매크로 스냅샷(macro_snapshot_5m) 적재 복구됨 — 정상 적재 재개.", "INFO")
                    insert_failure_alerted = False
                insert_failure_streak = 0
            else:
                insert_failure_streak += 1
                if insert_failure_streak >= MACRO_SNAPSHOT_INSERT_FAILURE_ALERT_STREAK and not insert_failure_alerted:
                    insert_failure_alerted = True
                    notify.notify(
                        f"매크로 스냅샷(macro_snapshot_5m) 적재가 {insert_failure_streak}회 연속 실패했습니다 "
                        "— db/migrations 라이브 미적용(스키마 불일치) 등 DB 문제일 수 있습니다. 로그 확인 필요.",
                        "WARNING",
                    )
            # 2026-07-31: ZN을 실제로 조회한 사이클에서만 스트릭을 증감한다 — 미조회 사이클의
            # NULL은 "실패"가 아니라 "이번엔 안 봤다"는 뜻이라, 그걸 세면 조회 주기(1시간)와
            # 무관하게 매 5분 스트릭이 올라 오경보가 된다.
            if "zn" in due_items:
                if row["zn_front"] is None:
                    zn_dual_failure_streak += 1
                else:
                    zn_dual_failure_streak = 0
            if zn_dual_failure_streak >= ZN_DUAL_FAILURE_ALERT_STREAK and not cbot_alert_sent:
                cbot_alert_sent = True
                notify.notify(
                    f"ZN(10년 국채선물) 데이터를 KIS·yfinance 폴백 양쪽 모두에서 {zn_dual_failure_streak}회 "
                    "연속 가져오지 못했습니다 — zn_front가 계속 NULL. 네트워크 상태 또는 yfinance 응답을 확인해주세요.",
                    "WARNING",
                )

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                "매크로 스냅샷 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기",
                interval_seconds, overrun_seconds, delay,
            )
        await asyncio.sleep(delay)


_INVESTOR_FLOW_SECTORS = (
    tr_codes.FID_INVESTOR_FLOW_FUTURES,
    tr_codes.FID_INVESTOR_FLOW_CALL_OPTION,
    tr_codes.FID_INVESTOR_FLOW_PUT_OPTION,
)


async def _collect_investor_flow_cycle(
    rest_client: KISRestClient, warning_throttle: WarningThrottle
) -> tuple[float, float, float, bool]:
    """
    입력/계산: poll_investor_flow 한 사이클분 — 선물/콜/풋 세 세그먼트를 조회해 합산한다.
         warning_throttle은 poll_investor_flow가 사이클 전체에서 공유하는 인스턴스를 그대로
         전달받는다(§5-5와 동일 패턴, 2026-07-20).
    실패 조건: 세그먼트 하나 실패는 건너뛰고 나머지로 합산 계속. got_any=False는 셋 다 실패했음을
              뜻한다 — 호출측이 재시도 여부를 판단하는 데 쓴다.
    로그(2026-07-20): 조회 실패는 `_log_kis_call_failure`로 응답 바디(레이트리밋 등 KIS 원인
              코드)를 함께 남기고, `warning_throttle`로 반복을 억제한다(poll_option_chain과 동일).
    """
    foreign_total = 0.0
    institution_total = 0.0
    individual_total = 0.0
    got_any = False

    for sector in _INVESTOR_FLOW_SECTORS:
        try:
            resp = await asyncio.to_thread(rest_client.get_investor_flow, tr_codes.FID_MRKT_DIV_DERIVATIVES, sector)
            output = resp.get("output") or []
            row = output[0] if isinstance(output, list) else output
            foreign_total += float(row["frgn_ntby_tr_pbmn"])
            institution_total += float(row["orgn_ntby_tr_pbmn"])
            individual_total += float(row["prsn_ntby_tr_pbmn"])
            got_any = True
        except Exception as exc:
            _log_kis_call_failure(
                f"투자자 수급 폴링 실패: {sector}", exc,
                throttle=warning_throttle, category="investor_flow_segment_fetch_failure",
            )
            continue

    return foreign_total, institution_total, individual_total, got_any


async def poll_investor_flow(
    rest_client: KISRestClient,
    underlying: str = UNDERLYING,
    interval_seconds: float = OPTION_CHAIN_POLL_INTERVAL_SECONDS,
    retry_backoff_seconds: float = CYCLE_RETRY_BACKOFF_SECONDS,
    phase_offset_seconds: float = 0.0,
) -> None:
    """
    입력: REST 클라이언트, 기초자산 라벨, 기동 시 최초 사이클을 지연시킬 초(startup_offset_seconds
         — 2026-07-28 추가: poll_option_chain과 동일하게 60초 주기라 오프셋 없이는 두 폴러의
         정규 사이클이 계속 같은 순간에 겹친다, poll_expiry_liquidity의 2026-07-09 패턴을 그대로
         적용).
    계산: KOSPI200 파생상품시장(선물+콜옵션+풋옵션) 세 세그먼트의 투자자별(외국인/기관계/개인)
         순매수 거래대금을 조회해 합산한 뒤 investor_flow_1m에 적재한다. "시장별 투자자매매동향
         (시세)"는 세션 누적치라, 이 값은 "1분간의 변화량"이 아니라 "그 시점까지의 누적 수급
         우위" 스냅샷이다. get_quote()류와 마찬가지로 동기 호출이라 asyncio.to_thread로 실행.
         세 세그먼트가 모두 실패하면(레이트리밋 버스트 등) retry_backoff_seconds 뒤 한 번만
         재시도한다.
    실패 조건: 세그먼트 하나 실패는 건너뛰고 나머지로 합산 계속 — 셋 다 실패하고 재시도까지
              실패하면 이번 사이클은 적재를 건너뛴다(마지막 성공값이 다음 사이클까지 화면에
              남는다).
    스케줄: poll_option_chain과 동일하게 절대시각 고정 틱(next_tick)으로 다음 사이클을 예약한다
           (2026-07-09 — "작업 후 sleep" 누적 드리프트로 poll_time이 분 경계를 건너뛰는 것을 방지).
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    next_tick: float | None = None
    warning_throttle = WarningThrottle(logger, window_seconds=WARNING_THROTTLE_WINDOW_SECONDS)
    while True:
        foreign_total, institution_total, individual_total, got_any = await _collect_investor_flow_cycle(
            rest_client, warning_throttle
        )

        if not got_any:
            logger.warning("투자자 수급 폴링 전체 실패 — %.0f초 후 재시도", retry_backoff_seconds)
            await asyncio.sleep(retry_backoff_seconds)
            foreign_total, institution_total, individual_total, got_any = await _collect_investor_flow_cycle(
                rest_client, warning_throttle
            )
            if not got_any:
                logger.warning("투자자 수급 폴링 재시도도 실패 — 이번 사이클 포기")

        if got_any:
            poll_time = db.local_now().replace(second=0, microsecond=0)
            with db.get_connection() as conn:
                db.insert_investor_flow(
                    conn, poll_time, underlying,
                    foreign_net=foreign_total, institution_net=institution_total, individual_net=individual_total,
                )

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                "투자자 수급 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기",
                interval_seconds, overrun_seconds, delay,
            )
        await asyncio.sleep(delay)


# 2026-08-05(§2-8) — 종가 단일가 구간의 OFI 부재 사유.
#
# 08-05 15:36~15:44에 `orderflow_ofi_vpin`이 죽어 앙상블이 4 → 3으로 얇아졌는데, 사유가
# `ofi/queue_imbalance 없음`으로만 남아 **장애와 구분되지 않았다.** 원인은 결함이 아니라 시장
# 구조다(연속 체결이 없으니 WS 1분봉이 안 만들어진다 — `mahdi.session` 참고).
#
# 사유만 가른다. **멤버를 살리지는 않는다** — 없는 값을 지어내는 것과 왜 없는지 아는 것은 다르다.
MEMBER_UNAVAILABLE_CLOSING_AUCTION = "종가 단일가(연속체결 없음)"

# 2026-08-06(운영점검 장전편 §2-5 / Fix#5) — 장전 스팟 부재 사유. 위와 **완전히 같은 계열**이다.
#
# 08-05 `9ffcb9c`가 장전 스팟 적재를 의도적으로 끊은 뒤로, 07:31~09:00의 `options_flow` 미가용은
# **설계된 정상**이다(스팟이 없으면 GEX·감마플립·VRP를 틀린 값 대신 미가용으로 남긴다).
# 그런데 사유가 `입력 없음: gex, spot, 기준선(flip/wall)`으로만 남아 장애와 구분되지 않았고,
# 그래서 08-06 장전 내내 COCKPIT 신호 도달률 배지가 노란불로
# *"options_flow가 한 번도 활성화되지 않았다"* 를 냈다 — **매일 90분씩 나는 구조적 오경보**다.
#
# 여기서도 멤버를 살리지 않는다. 사유만 가른다.
MEMBER_UNAVAILABLE_PREOPEN = "장전(스팟 미적재)"

# 2026-08-07(§3-1 / Fix#2) — **현물 장 마감 이후 스팟 부재.** 위 둘과 같은 계열의 세 번째다.
#
# 유가증권시장은 15:20~15:30이 장 마감 동시호가이고 그 뒤로는 종가에 고정된다. 반면 옵션은
# 15:45까지 계속 거래되므로, 15:20~15:45의 25분 동안 **체인은 살아 있는데 스팟만 죽어 있다.**
# 08-07까지는 그 죽은 스팟(08-07 실측 975.03 고정, 같은 시각 선물 978.40~980.25)으로 GEX를
# 계산했다 — 두 입력이 서로 다른 시각을 보고 있었다.
#
# **왜 선물 스팟으로 대체하지 않는가**(사용자 결정, 2026-08-07): 그러면 하루 중 시간대에 따라
# 스팟 소스가 달라지고, 그 순간 GEX 시계열이 두 개의 다른 것을 이어 붙인 값이 된다.
# 08-05 §2-3이 지적한 "감시자와 감시 대상이 입력을 공유한다" 문제와 같은 계열의 오염이다.
# **없는 값을 지어내지 않는다** — 스팟이 없는 구간은 없다고 쓰고, 그 25분은 진입 컷오프
# (14:50) 이후라 신규 진입에 영향이 없다.
MEMBER_UNAVAILABLE_EQUITY_CLOSED = "현물 장마감(스팟 미적재)"


def _member_scores_for_record(scores) -> dict[str, float]:
    """
    입력: `FusionDecision.member_scores`(없으면 빈 dict).
    계산: 산출된 멤버만 `{이름: 점수}`로 남긴다 — None인 멤버는 키 자체를 빼고,
         그 사유는 `member_unavailable`이 이미 담는다(두 dict의 키는 서로 배타적이다).
    해석: 2026-08-05 고도화#4 — 08-05에 판단이 살아났는데(가용 멤버 4, 전이 83회) **방향
         ±0.692가 어느 멤버에서 왔는지 DB로 역산할 수 없었다.** 가용성만 남기고 점수를 버렸기
         때문이다. `member_unavailable`과 짝을 이뤄 "누가 살아 있었고 무엇을 말했는가"가 완성된다.
    실패 조건: 없음.
    """
    if scores is None:
        return {}
    return {
        name: float(value)
        for name in MEMBER_FIELDS
        if (value := getattr(scores, name, None)) is not None
    }


def _member_unavailable_reasons(inputs: SignalInputs, now: datetime, scores=None) -> dict[str, str]:
    """
    입력: 이번 사이클의 SignalInputs, **판단 시각**(필수),
         (선택) 이미 계산된 `MemberScores` — 없으면 여기서 계산한다.
    계산: 산출되지 **않은** 앙상블 멤버마다 "어느 원재료가 없어서인가"를 한 줄로 남긴다.
    해석: 2026-08-04 고도화#2 — 종전에는 `available_member_count` 숫자 하나뿐이라, 08-04에
         "2개"가 어느 둘인지 알아내려고 사람이 `signal_layer.py`를 읽어 역산해야 했다.
         그리고 그 역산 끝에 `orderflow_ofi_vpin`이 **데이터가 있는데도** 죽어 있다는 것이
         나왔다(§2-5). 사유를 남겨두면 다음에는 판단 행 조회 한 번으로 끝난다.
         2026-08-05(§2-8): OFI 부재는 **장애와 시장 구조**를 가른다 — 상세 근거는
         `MEMBER_UNAVAILABLE_CLOSING_AUCTION` 주석.
    실패 조건: 없음 — 가용한 멤버는 키 자체가 없다(빈 dict = 전 멤버 가용).
    """
    # `now`를 기본값 없는 인자로 둔 이유: 기본값을 `db.local_now()`로 두면 이 함수가 **벽시계에
    # 의존**하게 되고, 그러면 15:35 이후에 돌린 테스트만 다른 답을 낸다(실제로 겪었다).
    # 판단 시각은 호출측이 이미 갖고 있는 값이다 — 숨기지 말고 넘긴다.
    #
    # 2026-08-05 고도화#4: `scores`를 받는 이유는 성능이 아니라 **일관성**이다. 판단 행에 남는
    # 점수(`member_scores`)와 사유(`member_unavailable`)가 각각 따로 계산되면 둘이 어긋날 수
    # 있고, 그러면 "점수가 있는데 미가용"이라는 해석 불가능한 행이 생긴다. 같은 계산을 쓴다.
    scores = build_member_scores(inputs) if scores is None else scores
    reasons: dict[str, str] = {}
    for name in MEMBER_FIELDS:
        if getattr(scores, name) is not None:
            continue
        if name in UNTRAINED_MEMBER_FIELDS:
            reasons[name] = "미학습(Phase 3)"
        elif name == "regime_hmm":
            reasons[name] = "regime_state 없음" if inputs.regime_state is None else "방향성 없는 레짐"
        elif name == "options_flow":
            missing = [
                label for label, value in (
                    ("gex", inputs.gex), ("spot", inputs.spot),
                    ("기준선(flip/wall)", inputs.gamma_flip if inputs.gamma_flip is not None else inputs.gamma_wall),
                ) if value is None
            ]
            if inputs.spot is None and session.is_preopen(now):
                # 2026-08-06 Fix#5 — 스팟이 없어서 죽은 것이고, 장전에 스팟이 없는 것은 설계다.
                # `spot`이 있는데도 죽었다면 그건 장전이라도 진짜 결함이므로 아래로 떨어뜨린다.
                reasons[name] = MEMBER_UNAVAILABLE_PREOPEN
            elif inputs.spot is None and not session.is_equity_spot_live(now):
                # 2026-08-07 Fix#2 — 같은 논리의 장 마감 쪽. 현물은 15:20에 연속거래가 끝나는데
                # 옵션은 15:45까지 거래되므로 **체인은 살아 있고 스팟만 없는** 25분이 생긴다.
                # `is_preopen`을 먼저 보는 이유는 두 조건이 겹치지 않게 하려는 것이 아니라
                # (겹치지 않는다) 읽는 순서를 하루의 시간 순서와 맞추기 위해서다.
                reasons[name] = MEMBER_UNAVAILABLE_EQUITY_CLOSED
            else:
                reasons[name] = f"입력 없음: {', '.join(missing)}" if missing else "성분 전부 부호 0"
        elif name == "orderflow_ofi_vpin":
            if inputs.ofi is not None:
                reasons[name] = "ofi 부호 0"
            elif session.is_closing_auction(now):
                reasons[name] = MEMBER_UNAVAILABLE_CLOSING_AUCTION
            else:
                reasons[name] = "ofi/queue_imbalance 없음"
        elif name == "flow_position":
            reasons[name] = "foreign_net_flow 없음" if inputs.foreign_net_flow is None else "순매수 부호 0"
        else:
            reasons[name] = "미상"
    return reasons


def _build_signal_inputs(
    conn, regime_state: RegimeState | None, underlying: str = UNDERLYING,
    futures_symbol: str | None = None,
) -> tuple[SignalInputs, dict]:
    """
    입력: DB 커넥션, 이번 사이클의 최신 레짐 상태(RegimeStateMachine.last_state), underlying 라벨,
         (선택) 선물 단축코드 — 주문흐름(OFI) 조회 대상.
    계산: option_analysis_1m 체인 스냅샷에서 **먼슬리 북만** 뽑아(`signal_book_legs`) GEX /
         Gamma Flip / 감마 월 / Charm을, market_raw_1m 최신 1분봉에서 OFI를,
         investor_flow_1m 최신값으로 외국인 순매수 부호를 구성한다.
         **함께 반환하는 dict는 판단 행에 그대로 남길 체인 입력 관측치**다(마이그레이션 022/023).
    해석: 체인/스팟 조회가 비어있거나 실패하면 그 부분만 None으로 남기고 계속 진행한다(다른
         폴러들의 "부분 실패 허용" 원칙과 동일 — Signal Fusion 자체가 None을 안전하게 처리하도록
         설계돼 있음).
         2026-08-03 §5-1: 두 번째 반환값이 있는 이유는 **"그 데이터가 신호까지 도달했는가"를
         사후에 셀 수 있어야 하기 때문**이다. 08-03에 먼슬리 커버리지는 98.8%였는데 감마플립
         산출률은 0%였고, 그 사실을 알아낼 지표가 하나도 없었다.

         2026-08-04(§2-4/§2-5/§2-8) — 이 함수가 앙상블 멤버 **2개를 죽이고 있었다**:
           Fix#2: `ofi=None` 하드코딩. docstring은 *"라이브 집계 파이프라인이 없어"* 라고 적었지만
                  `market_raw_1m.ofi`는 08-04에 선물 410분 **전부** 채워져 있었다(404분이 0 아님).
                  `orderflow_ofi_vpin`은 데이터가 없어서가 아니라 안 읽어서 죽어 있었다.
           Fix#4: `total_charm`/`charm_active` 미배선. 필드도 `vanna_charm_drift()`도 있는데
                  호출만 안 했고, 호출했어도 `charm`이 0이었을 것이다(DB 컬럼 전부 NULL) —
                  그래서 `with_computed_charm()`으로 읽기 시점에 계산해 채운다.
           Fix#3: 감마 월을 폴백 기준선으로 넘긴다(`OPTIONS_FLOW_GAMMA_WALL_FALLBACK`).
    실패 조건: 없음 — 개별 조회 결과 부재는 SignalInputs 필드의 None으로 흡수된다.
    """
    chain_rows = db.latest_option_chain(conn, underlying)
    now = db.local_now()
    # 2026-08-05(§2 이상점 8): 신호 경로에서만 신선도 경계를 켠다 —
    # 장전에는 스팟이 없는 것으로 쳐서(=전일 종가를 쓰지 않아서) GEX/감마플립/VRP가
    # **틀린 값 대신 미가용**이 된다. 근거는 `db.UNDERLYING_SPOT_MAX_AGE_MINUTES` 주석.
    spot = db.latest_underlying_spot(
        conn, underlying, as_of=now, max_age_minutes=db.UNDERLYING_SPOT_MAX_AGE_MINUTES
    )
    flow = db.latest_investor_flow(conn, underlying)
    gex = gamma_flip = gamma_wall = total_charm = None
    legs, gex_expiry = signal_book_legs(chain_rows, now.date()) if chain_rows else ([], None)
    if legs and spot is not None:
        gex = calculate_gex(legs, spot)
        # 2026-08-13 고도화 1 — `today`/`expiry`를 넘겨야 만기 당일 북이 **계산 전에** 빠지고
        # 매분 WARNING 대신 하루 1회 INFO가 남는다(08-13에 그 한 문장이 WARNING의 54.5%였다).
        gamma_flip = find_gamma_flip(legs, spot, today=now.date(), expiry=gex_expiry)
        # 2026-08-04 Fix#3 — 감마 월은 **노출이 0보다 클 때만** 기준선으로 쓴다.
        # `gamma_walls()`는 행사가별 |gamma x OI x ...| 합을 내림차순으로 줄 뿐이라, OI가 전부
        # 0인 북(08-04 weekly_mon이 그랬다)에서도 "노출 0짜리 1등 행사가"를 돌려준다. 그것을
        # 기준선으로 쓰면 딜러 포지션이 없는 북에서 방향 신호를 지어내게 된다 —
        # `find_gamma_flip()`이 전 구간 0인 곡선에서 허수 flip을 냈던 것과 **같은 종류의 결함**이다.
        walls = gamma_walls(legs, spot, top_n=1)
        gamma_wall = walls[0][0] if walls and walls[0][1] > 0 else None
        drift = vanna_charm_drift(with_computed_charm(legs, spot), now.time())
        total_charm = drift["total_charm"]
        charm_active = drift["charm_active"]
    else:
        charm_active = False

    # 2026-08-05(운영점검보고서 2026-08-05 §2 이상점 1 / Fix#1) — 팔레트 열을 정하는 VRP.
    #
    # **GEX와 반드시 같은 북(먼슬리)에서 낸다.** 08-04 Fix#5가 GEX/감마플립을 먼슬리 전용으로
    # 바꾼 것과 같은 이유이고(v6 §11.4), 실무적으로도 위클리는 08-05 실측에서 `rv_5d`가 두 북
    # 모두 전부 0이라 `atm_straddle_vrp()`가 어차피 None을 낸다 — 그걸 섞으면 "적정" 폴백이
    # 위클리 데이터 결손 때문에 발생하는 건지 진짜 적정인 건지 구분할 수 없게 된다.
    #
    # `legs`가 아니라 `chain_rows`를 넘기는 이유: `OptionLeg`에는 rv 필드가 없다(감마 계산에
    # 필요한 값만 담는 구조체다). VRP는 iv와 rv가 **같은 스냅샷의 같은 레그**에서 와야 한다.
    monthly_rows = [row for row in chain_rows if row.get("expiry") == gex_expiry] if gex_expiry else []
    vrp = atm_straddle_vrp(monthly_rows, spot)

    micro = (
        db.latest_market_microstructure(conn, futures_symbol, as_of=now)
        if futures_symbol is not None
        else None
    )

    # timestamp는 `_chain_snapshot()`이 항상 채우지만, 나이는 어디까지나 부가 관측치라 없으면
    # 그 항목만 비운다 — 이것 때문에 판단 자체가 죽으면 안 된다.
    #
    # 2026-08-06(운영점검 장전편 §2-4 / Fix#4) — **`chain_rows`가 아니라 `monthly_rows`에서 잰다.**
    # 종전 구현은 전 북(먼슬리 + 위클리 2)의 최솟값이었는데, 위클리는 2026-08-03 fix로 월=짝수분/
    # 목=홀수분 격분이라 **항상 한 북이 정확히 2분 뒤처져 있다.** 그 뒤처진 북이 매분 최솟값을
    # 가져가므로 이 값은 신선도가 아니라 **격분 설계상수**를 재고 있었다:
    #
    #   08-06 장전 실측: 07:34~07:57 판단 전부 130.039~130.077초 (17분 연속, 편차 0.04초)
    #   08-05 전량 실측: 250초 258분(52%) / 130초 170분 / 190초 64분 / 70초 1분 — 고유값 4종
    #
    # 임계가 7.5분이라 250초로도 **울릴 수 없는 지표**였고, 그래서 아무도 하루의 절반이 250초인
    # 것을 못 봤다. 바로 위 `chain_leg_count`는 "판단에 실제로 쓴 북 기준"이라고 주석까지 달고
    # 먼슬리만 세는데 나이만 전 북 기준이었던 것 — **한 dict 안에서 두 줄이 서로 다른 것을 쟀다.**
    oldest = min((row["timestamp"] for row in monthly_rows if row.get("timestamp") is not None), default=None)
    # 2026-08-11 고도화 B — **판단이 「그 분」 체인을 봤는가.** 마이그레이션 029.
    #
    # 위 `chain_oldest_leg_age_seconds`는 초 단위 연속값이라 "이 분 것인가 아닌가"라는 **이산**
    # 질문에 답하지 않는다. 08-06 §2-4가 같은 함정에 빠졌다(격분 설계상수 130초를 신선도로 착각).
    # 그래서 **가장 새로운** 레그의 분과 판단 분을 직접 비교한다.
    newest = max((row["timestamp"] for row in monthly_rows if row.get("timestamp") is not None), default=None)
    if newest is None:
        chain_input_source = "none"
    elif newest.replace(tzinfo=None).replace(second=0, microsecond=0) == now.replace(second=0, microsecond=0):
        chain_input_source = "current"
    else:
        chain_input_source = "stale"
    chain_inputs = {
        "chain_input_source": chain_input_source,
        "gamma_flip": gamma_flip,
        "gex": gex,
        # 레그 수는 **판단에 실제로 쓴 북 기준**이다(Fix#5로 먼슬리 전용이 됐다). 스냅샷 전체
        # 레그 수를 세면 위클리까지 포함돼 "신호에 쓴 입력의 크기"를 재지 못한다.
        "chain_leg_count": len(legs),
        "chain_oldest_leg_age_seconds": (
            (now - oldest.replace(tzinfo=None)).total_seconds() if oldest is not None else None
        ),
        "gex_expiry": gex_expiry,
        # 마이그레이션 024. None(산출 불가)과 0.0(IV=RV)은 다르다 — 전자만 fair로 폴백한 분이다.
        "vrp": vrp,
    }
    signal_inputs = SignalInputs(
        regime_state=regime_state,
        gex=gex,
        gamma_flip=gamma_flip,
        gamma_wall=gamma_wall,
        spot=spot,
        total_charm=total_charm,
        charm_active=charm_active,
        ofi=micro["ofi"] if micro is not None else None,
        # 큐 임밸런스는 아직 없다 — `market_raw_1m`에 호가 잔량 열이 없고, 체결 기반
        # buy/sell_volume은 OFI와 같은 정보라 성분을 두 번 세게 된다(부호만 쓰는 설계에서
        # 같은 신호를 2표로 만드는 것은 가중치를 조용히 바꾸는 짓이다). 호가 잔량을 적재하게
        # 되면 그때 채운다.
        queue_imbalance=None,
        foreign_net_flow=flow[0] if flow is not None else None,
    )
    return signal_inputs, chain_inputs


def _build_meta_label_context(
    signal_inputs: SignalInputs,
    event_proximity_minutes: float | None = None,
) -> MetaLabelContext:
    """
    입력: 이번 사이클의 SignalInputs.
    계산: v6 §11.2 메타 라벨 입력 중 **호출측만 알 수 있는 4개**를 실데이터로 채운다.
    해석: 2026-08-05(운영점검보고서 2026-08-05 §2 이상점 2 / Fix#3) — 종전에는
         `MetaLabelContext()`를 **인자 없이** 생성했다. 그 기본값은 전부 "페널티 없음"쪽이라
         `classify()`의 곱셈 페널티 4종이 하나도 걸리지 않았고, 특히
         `gamma_regime_stable=True`는 **낙관적 하드코딩**이었다.

         이것은 2026-07-10에 `warmup_fallback(RANGE_BALANCED, macro_score=0.0, gap_zscore=0.0)`을
         하드코딩된 인자로 호출해 레짐이 하루 종일 고정돼 있던 것과 **같은 형태의 결함**이다:
         함수는 입력을 받도록 설계돼 있는데 호출측이 상수를 넣고 있었다.

         실제 피해(08-05): 그날 HIGH_CONVICTION 6건의 `conviction_score`는 정확히 0.75였다
         (= regime_confidence 1.0 x 동조비 3/4, 페널티 0회). 먼슬리 GEX는 −9.9bn(음수)이고
         `stability_flag`는 하루 종일 False였으므로 `gamma_regime_stable`은 **False가 맞았고**,
         그랬다면 0.75 x 0.85 = 0.6375 < standard_max(0.65) → STANDARD로 내려갔어야 한다.
         즉 그 6건은 낙관적 기본값이 만든 한 등급 위의 확신도였다.

         **`gamma_regime_stable`의 정의**는 `MetaLabelInputs` 주석이 이미 적어둔 그대로
         `GEX>=0 & stability_flag`다. 같은 두 값을 `engine.py`가 이미 팔레트 게이트
         (`positive_gex`/`stable_regime`)로 쓰고 있다 — 정의를 새로 만든 게 아니라 **이미 있던
         정의를 메타 라벨에도 연결한 것**이다.

         **나머지 셋을 그대로 두는 근거**(추측으로 채우지 않는다):
           - `recent_slippage_elevated=False` — `trade_history`/`execution_logs`가 **둘 다 0행**이다.
             체결이 없으면 슬리피지도 없으므로 False는 낙관이 아니라 **사실**이다. 실행이
             배선되는 날 이 자리가 채울 곳이다.
           - `recent_same_setup_win_rate=None` — 같은 이유. `classify()`가 None을 "이력 없음
             (중립 1.0배)"으로 정의해 두었으므로 None이 정확한 표현이다.
           - `event_proximity_minutes` — 2026-08-05에 수기 캘린더
             (`mahdi/config/event_calendar.yaml`)로 배선했다. 호출측이
             `fusion.event_calendar.minutes_to_next_event()` 결과를 넘긴다. **캘린더가
             미기입이면 None이 그대로 들어온다** — 그때 페널티를 지어내지 않는 대신 호출측이
             경고를 남긴다(`minutes`가 None인 두 이유를 가르는 것이 그 모듈의 핵심이다).
    실패 조건: 없음 — `regime_state`나 `gex`가 없으면 `gamma_regime_stable`은 False가 된다
              (모르면 안정으로 치지 않는다 = 페널티를 거는 쪽이 보수적이다).
    """
    positive_gex = signal_inputs.gex is not None and signal_inputs.gex >= 0
    stable_regime = (
        signal_inputs.regime_state.stability_flag if signal_inputs.regime_state is not None else False
    )
    return MetaLabelContext(
        gamma_regime_stable=positive_gex and stable_regime,
        event_proximity_minutes=event_proximity_minutes,
    )


def _account_state_snapshot_from_row(row: dict | None) -> BalanceSnapshot | None:
    return BalanceSnapshot(**row) if row is not None else None


def _build_account_state_for_candidate(conn, candidate_side: str, poll_time: datetime) -> AccountState | None:
    """
    입력: 후보 진입 방향("BUY"/"SELL"), 이번 사이클 시각.
    계산: `account_balance_snapshots`에 최신 스냅샷이 없으면(계좌 잔고 폴러가 아직 한 번도
         못 돌았거나 막 기동한 직후) None을 반환해 호출측이 Risk Engine 호출 자체를 건너뛰게
         한다 — 가짜 `AccountState`(전부 0)로 "위반 없음"을 흉내내지 않기 위함. 오늘/이번주
         자정 이전 마지막 스냅샷을 baseline으로, 역대 최고치를 드로우다운 기준으로 넘긴다.
    """
    latest_row = db.latest_account_balance_snapshot(conn)
    if latest_row is None:
        return None

    today_midnight = datetime.combine(poll_time.date(), dtime.min)
    week_start_midnight = today_midnight - timedelta(days=today_midnight.weekday())

    return build_account_state(
        _account_state_snapshot_from_row(latest_row),
        _account_state_snapshot_from_row(db.account_balance_snapshot_before(conn, today_midnight)),
        _account_state_snapshot_from_row(db.account_balance_snapshot_before(conn, week_start_midnight)),
        db.max_account_balance_ever(conn),
        candidate_side=candidate_side,
        daily_trades_by_strategy=db.daily_trade_counts_by_strategy(conn, poll_time.date()),
    )


def _record_risk_snapshot(
    conn,
    poll_time: datetime,
    signal_inputs: SignalInputs,
    account_state: AccountState | None,
    risk_engine: RiskEngine,
    *,
    halt_status: dict | None,
    market_halted: bool,
    decision_label: str,
    risk_engine_state: object,
    risk_gate_invocations: int = 0,
    risk_gate_last_invoked_at: datetime | None = None,
) -> None:
    """
    입력: 이번 사이클의 신호 원재료/계좌 상태/RiskEngine 인스턴스/거래정지 상태/판단 라벨.
    계산: `risk_snapshots`에 (a) 시장 감마 구조(greeks), (b) 일간 손실한도까지 남은 여유
         (loss_buffer), (c) Circuit Breaker·거래소 정지 상태(cb_state)를 한 행으로 남긴다.
    해석: 2026-07-30(운영점검보고서 §2-9/§4 Fix#6) — RiskEngine이 하루 419회 평가를 돌렸는데도
         이 테이블이 0행이라 사후 리스크 재구성이 불가능했다. `signal_decisions.risk_gate_state`
         는 승인여부/사이즈까지만 담고 CB 상태·손실 여유는 담지 않는다.
         `greeks`에 담는 건 **포트폴리오 그릭스가 아니라 시장 감마 구조**다 — 포지션 생애주기
         추적이 아직 없어(ExecutionEngine 미배선) 보유 그릭스라는 개념 자체가 없으므로, 지어내지
         않고 `scope`/`portfolio` 필드로 그 사실을 명시한다.
         2026-08-01(§5-4 "안전장치의 생존 신호"): 종전에는 `circuit_breaker_state`가 "마지막으로
         evaluate()가 불린 시점"의 값이었다 — 일간 래치 설계라 매분 호출하면 HALTED로 고착될 수
         있어 의도적으로 안 불렀고, 그 결과 07-31 기준 **하루 0회 평가**였다. 즉 킬스위치가
         살아있는지 아무도 몰랐다. 이제 상태를 바꾸지 않는 `evaluate_readonly()`로 **매 사이클
         조건을 실제로 평가**해 남긴다(래치는 여전히 실주문 경로의 `evaluate()`에서만 일어난다).
         계좌 상태가 없으면 평가 자체가 불가능하므로 `latched_state`만 남기고 그 사실을 명시한다.
    실패 조건: 기록 실패가 폴링 루프를 막으면 안 되므로 로그만 남기고 넘어간다.
    """
    daily_loss_limit = (get_risk_limits().get("limits") or {}).get("daily_loss_pct")
    loss_buffer = None
    if account_state is not None and daily_loss_limit is not None:
        # 남은 여유 = 오늘 손익률 - 일간 손실한도(음수) → 양수면 아직 여유, 음수면 한도 초과.
        loss_buffer = round(account_state.daily_pnl_pct - float(daily_loss_limit), 4)

    greeks = {
        "scope": "market",
        "portfolio": None,
        "note": "포지션 생애주기 추적 미배선 — 보유 포트폴리오 그릭스 없음(ExecutionEngine 미사용)",
        "gex": signal_inputs.gex,
        "gamma_flip": signal_inputs.gamma_flip,
        "spot": signal_inputs.spot,
    }
    cb_state = {
        # 래치된 상태(하루 안에서 한 번 HALTED면 유지) — 실주문 경로가 실제로 보는 값.
        "circuit_breaker_latched_state": risk_engine.circuit_breaker.state.value,
        "market_halted": market_halted,
        "market_halt_label": (halt_status or {}).get("label"),
        "decision": decision_label,
        "risk_engine": risk_engine_state,
        "account_tracker_ready": account_state is not None,
        # 2026-08-01(§5-4): 진입 게이트 생존 계측. 0회는 "진입 후보가 없었다"는 정상 상태다 —
        # 경고 대상이 아니라 정보다(임계를 두면 상시 오경보가 된다).
        "risk_gate_invocations_today": risk_gate_invocations,
        "risk_gate_last_invoked_at": (
            risk_gate_last_invoked_at.strftime("%H:%M") if risk_gate_last_invoked_at else None
        ),
    }
    if account_state is None:
        cb_state["circuit_breaker_evaluated"] = False
        cb_state["circuit_breaker_note"] = "계좌 상태 없음 — 조건 평가 불가(잔고 폴러 대기 중)"
    else:
        # 상태를 바꾸지 않는 평가 — 이 값이 있다는 것 자체가 "킬스위치가 살아있다"의 증거다.
        readonly = risk_engine.circuit_breaker.evaluate_readonly(account_state, MarketConditions())
        cb_state["circuit_breaker_evaluated"] = True
        cb_state["circuit_breaker_now"] = readonly.state.value
        cb_state["circuit_breaker_triggered_now"] = readonly.triggered_conditions
    try:
        db.insert_risk_snapshot(conn, poll_time, greeks, loss_buffer, cb_state)
    except Exception:
        logger.warning("risk_snapshots 기록 실패 — 판단 자체에는 영향 없음", exc_info=True)


async def poll_signal_fusion_cycle(
    regime_state_machine: RegimeStateMachine,
    underlying: str = UNDERLYING,
    interval_seconds: float = SIGNAL_FUSION_POLL_INTERVAL_SECONDS,
    phase_offset_seconds: float = 0.0,
    futures_symbol: str | None = None,
) -> None:
    """
    입력: 다른 폴러가 매 선물봉마다 갱신하는 RegimeStateMachine(최신 레짐은 last_state로 읽음 —
         2026-07-28 2차 신규), underlying 라벨, (선택) 선물 단축코드 — 주문흐름(OFI) 조회
         대상이며 None이면 `orderflow_ofi_vpin` 멤버만 미가용이 된다(2026-08-04 Fix#2).
    계산: 매 사이클 `SignalFusionEngine.evaluate()`를 실행해 방향/확신도/거래허가/전략 후보를
         계산하고 `signal_decisions`에 기록한다. **실제 주문은 절대 내지 않는다**(ADVISORY
         전용) — 다만 2026-07-28 8차부터 계좌 추적기가 생겨, 진입 후보(`decision="ENTER"`)일
         때는 `RiskEngine.evaluate_entry()`까지 실제로 호출해 "만약 지금 승인 게이트를
         거쳤다면 어떻게 됐을지"를 `risk_gate_state.risk_engine`에 함께 기록한다(v6 §12
         "독립 거부권" — 이 값은 Signal Fusion의 `decision` 자체를 바꾸지 않는다, 별개 게이트).
         `ExecutionEngine`(주문 상태머신/하이브리드 모드 게이트)은 여전히 안 씀 — 포지션
         생애주기 추적이 없어 아직 의미가 없다.
    해석: 계좌 잔고 폴러(`poll_account_balance_cycle`)가 아직 스냅샷을 하나도 못 쌓았으면
         `risk_gate_state.risk_engine`은 `"account_tracker_not_ready"` 문자열로 남는다(가짜
         AccountState로 승인/거부를 지어내지 않음). `PositionSizingInput`의 `target_vol`/
         `realized_vol`/`liquidity_score`/`portfolio_capacity_remaining_pct`는 라이브로 계산하는
         곳이 아직 없어 중립값으로 둔다(백테스트 데이터 어댑터와 동일한 종류의 단순화, 알려진
         한계로 문서화).
    실패 조건: 이번 사이클 조회/계산/적재가 실패하면 로그만 남기고 다음 사이클을 기다린다(다른
              폴러와 동일한 장애 격리 원칙).
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    fusion_engine = SignalFusionEngine()
    risk_engine = RiskEngine()
    # 2026-08-01(§5-4): RiskEngine의 진입 게이트는 **진입 후보가 있을 때만** 불린다(07-31 하루
    # 0회). 그 자체는 정상이지만, 0회라는 사실이 어디에도 안 남으면 "게이트가 죽었는지"와
    # "진입 후보가 없었는지"를 구분할 수 없다. 호출 횟수/마지막 호출 시각을 남긴다 —
    # **0회에 경고를 걸지는 않는다**(그러면 CB 하트비트와 같은 실수: 정상을 이상으로 표시).
    risk_gate_invocations = 0
    risk_gate_last_invoked_at: datetime | None = None
    # 2026-08-05 — 캘린더는 프로세스당 1회만 읽는다(`get_event_calendar()`가 `@lru_cache`).
    # 미기입 경고는 1시간 창으로 억제한다 — 근거는 `LOG_EVENT_CALENDAR_NOT_COVERED` 주석.
    event_calendar_raw = get_event_calendar()
    calendar_throttle = WarningThrottle(logger, EVENT_CALENDAR_WARNING_WINDOW_SECONDS)
    next_tick: float | None = None
    while True:
        poll_time = _grid_poll_minute(db.local_now())
        try:
            with db.get_connection() as conn:
                signal_inputs, chain_inputs = _build_signal_inputs(
                    conn, regime_state_machine.last_state, underlying, futures_symbol=futures_symbol
                )
                # 2026-08-05(§2 이상점 1 / Fix#1) — VRP를 실제로 넘긴다.
                #
                # 종전에는 인자를 생략해 `evaluate()`의 기본값 0.0이 쓰였고, 그것은
                # `_vrp_state(0.0, 0.02)` = **항상 "fair"** 를 뜻했다. v6 §11.4 매트릭스 3열 중
                # 2열이 전 이력 도달 불가였고, 레짐까지 RANGE_BALANCED 고정이라 9칸 중 실제로
                # 도달 가능한 칸은 `wait_and_see` 하나뿐이었다 — 진입 후보가 구조적으로 나올 수
                # 없는 상태였다(08-05 HIGH_CONVICTION 6건이 전부 여기서 버려졌다).
                #
                # 산출 불가(None)일 때 0.0으로 떨어뜨리는 것은 **의도된 안전 폴백**이다:
                # 0.0 = fair = `wait_and_see`(관망)라 08-05 이전의 상시 동작과 같고, 없는 값을
                # 지어내 진입을 만들지 않는다. "못 쟀다"와 "쟀는데 적정이다"의 구분은 팔레트가
                # 아니라 `signal_decisions.vrp`(NULL vs 0.0)가 보존한다.
                # 2026-08-05(§2 이상점 2 / Fix#3) — 메타 라벨 입력도 실데이터로 채운다.
                # 종전의 `MetaLabelContext()`는 전 필드가 "페널티 없음"이라
                # `gamma_regime_stable=True`가 확신도를 한 등급 부풀렸다(근거는 함수 주석).
                # 2026-08-05(§2 이상점 6 / Fix#5) — 하루 전략 상한을 실제로 걸리게 한다.
                # 종전에는 이 인자도 생략돼 항상 `frozenset()`이었고, v6 §11.4의 "하루 우선
                # 전략군 2개 이하" 상한이 전 이력 무력이었다(`db.entry_strategies_used_today`
                # 주석 참고). 조회 실패가 판단 자체를 막지 않도록 이 한 줄만 별도로 감싼다 —
                # 상한은 안전장치이지 판단의 전제가 아니다.
                try:
                    already_used_today = db.entry_strategies_used_today(conn, poll_time.date())
                except Exception:
                    logger.warning("오늘 사용 전략 조회 실패 — 이번 사이클은 상한 없이 진행", exc_info=True)
                    already_used_today = frozenset()
                # 2026-08-11 고도화 D — 전략별 직전 진입 경과. 위와 **같은 이유로 따로 감싼다**:
                # 쿨다운도 안전장치이지 판단의 전제가 아니다. 조회가 실패하면 빈 dict가 되어
                # 아무것도 안 막는다(레버 OFF와 같은 결과).
                try:
                    last_entry_minutes = db.minutes_since_last_entry_by_strategy(conn, poll_time)
                except Exception:
                    logger.warning("직전 진입 시각 조회 실패 — 이번 사이클은 쿨다운 없이 진행", exc_info=True)
                    last_entry_minutes = {}
                # 2026-08-05 — 이벤트 근접도(수기 캘린더). `minutes`가 None인 두 이유를
                # 가르는 것이 이 모듈의 핵심이다: `no_upcoming`(확인했고 없다)은 조용하고,
                # `not_covered`/`empty`(모른다)만 경고한다. 어느 쪽이든 페널티는 지어내지 않는다.
                proximity = minutes_to_next_event(poll_time, event_calendar_raw)
                if proximity.status in EVENT_CALENDAR_NEEDS_ATTENTION:
                    calendar_throttle.warning(
                        "event_calendar_not_covered", LOG_EVENT_CALENDAR_NOT_COVERED,
                        proximity.status, proximity.covered_through, poll_time.date(),
                    )
                vrp = chain_inputs.get("vrp")
                decision = fusion_engine.evaluate(
                    signal_inputs,
                    _build_meta_label_context(
                        signal_inputs, event_proximity_minutes=proximity.minutes
                    ),
                    vrp=vrp if vrp is not None else 0.0,
                    already_used_strategies_today=already_used_today,
                    last_entry_minutes_ago=last_entry_minutes,
                )

                # 2026-07-30(운영점검보고서 §2-2/§4 Fix#1): 예전엔 bool(decision.allowed_strategies)
                # 만 봤는데, §11.4 매트릭스의 "fair" 셀에는 관망 지시(wait_and_see/breakout_wait)가
                # 들어있어 "관망하라"는 결론이 진입 후보로 계수됐다(07-30 하루 419건 전부 이 경우).
                # entry_strategies()로 관망 계열을 걸러낸 뒤 남는 게 있을 때만 진입으로 본다.
                entry_candidates = entry_strategies(decision.allowed_strategies)
                is_entry = decision.trade_permission != TradePermission.NO_TRADE and bool(entry_candidates)

                # 2026-08-06 §2-2 / Fix#1 — v6 §4.2 신규 진입 컷오프(14:50).
                #
                # **`RiskEngine`에만 게이트를 두면 이 표는 안 바뀐다.** `decision` 컬럼은 팔레트
                # 결과(`is_entry`)만 보고 정해지고 리스크 엔진 결과는 `risk_gate_state`에만
                # 들어가기 때문이다 — 08-06의 ENTER 62건은 전부 `risk_engine.approved=true`였다.
                # 그래서 판단 층에도 같은 경계를 둔다(엔진 쪽은 Phase 2 실행 경로를 위한 이중
                # 방어이고, 두 곳 모두 `mahdi.session` 한 상수를 읽는다).
                #
                # **이미 거부된 판단의 사유는 덮지 않는다** — `is_entry`가 True였을 때만 사유를
                # `entry_cutoff`로 바꾼다. 그래야 이 사유의 건수가 정확히 *"진입할 뻔했는데 시각
                # 때문에 막힌 분"* 이 되어 그 자체로 검정 가능한 지표가 된다(관망으로 이미 막힌
                # 분까지 세면 컷오프의 효과가 팔레트 상태에 따라 요동친다).
                entry_cutoff_blocked = is_entry and session.is_after_entry_cutoff(poll_time)
                if entry_cutoff_blocked:
                    is_entry = False

                if entry_cutoff_blocked:
                    reject_reason = _REJECT_REASON_ENTRY_CUTOFF
                elif decision.reject_reasons:
                    reject_reason = decision.reject_reasons[0][:_SIGNAL_DECISION_REJECT_REASON_MAX_LENGTH]
                elif not is_entry and decision.allowed_strategies:
                    # 팔레트는 셀을 찾았지만 그 내용이 관망뿐이라 진입이 아닌 경우 — 신호 부재
                    # (meta_label:no_trade)와 구분해서 남긴다.
                    reject_reason = "strategy_palette:wait_only"
                else:
                    reject_reason = None
                risk_gate_state: dict = {
                    "direction": decision.direction,
                    "conviction_score": decision.conviction_score,
                    "signal_agreement_count": decision.signal_agreement_count,
                    "available_member_count": decision.available_member_count,
                    # 2026-08-06 고도화#2 — 가용 멤버 중 **실제로 의견을 낸** 수.
                    # 08-06 §14-3: `regime_hmm`이 399분 전량 0점이라 가용 4는 실질 3이었다.
                    # 둘의 차이가 곧 죽은 축의 수이고, 그 차이 자체를 매일 리포트에 낸다.
                    "effective_member_count": decision.effective_member_count,
                    "allowed_strategies": decision.allowed_strategies,
                    # 팔레트 원문(allowed_strategies)과 진입 대상(entry_strategies)을 둘 다 남긴다 —
                    # COCKPIT은 "관망 중"을 표시할 수 있어야 하고, 사후 분석은 실제 진입 후보만
                    # 세야 한다.
                    "entry_strategies": entry_candidates,
                    # 2026-08-04 고도화#2 — **어느 멤버가 왜 죽었는가.**
                    # 08-04까지는 `available_member_count`(=2) 한 숫자뿐이라, 그게 어느 멤버인지
                    # 알려면 사람이 코드를 읽어 역산해야 했다(이 보고서가 실제로 그렇게 만들어졌다).
                    # 사유까지 남기면 다음 회귀는 표 한 줄로 잡힌다.
                    # 2026-08-05 §2-8: 판단 시각을 넘긴다 — 종가 단일가의 OFI 부재를
                    # 장애가 아니라 시장 구조로 기록하기 위함(`mahdi.session`).
                    # 2026-08-05 고도화#4: 엔진이 쓴 점수를 그대로 넘겨 사유와 점수가 같은
                    # 계산에서 나오게 한다.
                    "member_unavailable": _member_unavailable_reasons(
                        signal_inputs, poll_time, decision.member_scores
                    ),
                    # 2026-08-05 고도화#4 — **판단이 무엇에 반응했는가.**
                    # `member_unavailable`이 "누가 죽었나"라면 이쪽은 "산 멤버가 뭐라고 했나"다.
                    # 두 dict의 키는 배타적이라 합치면 항상 6멤버가 된다.
                    "member_scores": _member_scores_for_record(decision.member_scores),
                }

                # 2026-07-30 Fix#6: halt 상태와 계좌 상태는 진입 여부와 무관하게 매 사이클 구해
                # 둔다 — risk_snapshots에 "그 시점 리스크 상태"를 남기려면 REJECT 사이클에도
                # 필요하기 때문이다(진입 사이클에서만 조회하면 하루 대부분이 공백이 된다).
                halt_status = db.latest_market_halt_state(conn)
                market_halted = bool(halt_status and halt_status["is_halted"])
                candidate_side = "BUY" if decision.direction > 0 else "SELL"
                account_state = _build_account_state_for_candidate(conn, candidate_side, poll_time)

                if is_entry:
                    if account_state is None:
                        risk_gate_state["risk_engine"] = "account_tracker_not_ready"
                    else:
                        sizing_input = PositionSizingInput(
                            base_size=1.0,
                            regime_confidence=decision.conviction_score,
                            signal_quality=decision.conviction_score,
                            target_vol=0.01,
                            realized_vol=0.01,
                            liquidity_score=1.0,
                            drawdown_pct=account_state.drawdown_pct,
                            portfolio_capacity_remaining_pct=1.0,
                        )
                        risk_decision = risk_engine.evaluate_entry(
                            sizing_input, account_state, entry_candidates[0], MarketConditions(),
                            market_halted=market_halted,
                            # 2026-08-06 Fix#1 — 판단 층이 이미 컷오프를 걸었으므로 여기까지
                            # 오는 사이클은 컷오프 이전이다. 그래도 넘기는 이유: 이 인자가
                            # 비어 있으면 Phase 2에서 실행 엔진이 같은 호출을 복사해 갈 때
                            # 시각 게이트가 조용히 빠진다. **두 층 모두 채워져 있어야 한다.**
                            now=poll_time,
                        )
                        risk_gate_invocations += 1
                        risk_gate_last_invoked_at = poll_time
                        risk_gate_state["risk_engine"] = {
                            "approved": risk_decision.approved,
                            "approved_size": risk_decision.approved_size,
                            "reject_reasons": risk_decision.reject_reasons,
                        }

                db.insert_signal_decision(
                    conn,
                    poll_time,
                    conviction=decision.trade_permission.value,
                    decision="ENTER" if is_entry else "REJECT",
                    reject_reason=reject_reason,
                    risk_gate_state=risk_gate_state,
                    exec_mode="ADVISORY",
                    # 2026-08-03 §5-1: 판단 시점의 체인 입력을 함께 남겨야 "신호 도달률"을 사후에
                    # 셀 수 있다(마이그레이션 022).
                    chain_inputs=chain_inputs,
                )
                _record_risk_snapshot(
                    conn, poll_time, signal_inputs, account_state, risk_engine,
                    halt_status=halt_status, market_halted=market_halted,
                    decision_label="ENTER" if is_entry else "REJECT",
                    risk_engine_state=risk_gate_state.get("risk_engine"),
                    risk_gate_invocations=risk_gate_invocations,
                    risk_gate_last_invoked_at=risk_gate_last_invoked_at,
                )
        except Exception:
            logger.warning("Signal Fusion 사이클 실패 — 이번 사이클 건너뜀", exc_info=True)

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                "Signal Fusion 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기",
                interval_seconds, overrun_seconds, delay,
            )
        await asyncio.sleep(delay)


async def poll_account_balance_cycle(
    rest_client: KISRestClient,
    interval_seconds: float = ACCOUNT_BALANCE_POLL_INTERVAL_SECONDS,
    phase_offset_seconds: float = 0.0,
) -> None:
    """
    입력: REST 클라이언트, 기동 시 최초 사이클을 지연시킬 초(다른 REST 폴러와 겹치지 않게 —
         이 폴러는 실제로 KIS API를 호출하므로 스태거링 대상).
    계산: `rest_client.get_balance()`(2026-07-28 7차에 실측·수정한 필수 파라미터 포함 버전,
         [[DECISION_LOG]] 참고)를 `asyncio.to_thread`로 호출(다른 동기 REST 호출과 동일 패턴) →
         `account_tracker.parse_balance_response()` → `account_balance_snapshots`에 적재한다.
         `poll_signal_fusion_cycle`이 이 테이블을 읽어 `RiskEngine.evaluate_entry()`를 호출할
         AccountState를 만든다.
    실패 조건: 이번 사이클 조회/파싱/적재가 실패하면 로그만 남기고 다음 사이클을 기다린다(다른
              폴러와 동일한 장애 격리 원칙 — 계좌 조회 실패가 관측 루프 전체를 막으면 안 됨).
    """
    await _sleep_until_first_wall_tick(interval_seconds, phase_offset_seconds)

    next_tick: float | None = None
    while True:
        poll_time = _grid_poll_minute(db.local_now())
        try:
            response = await asyncio.to_thread(rest_client.get_balance)
            snapshot = parse_balance_response(response, poll_time)
            with db.get_connection() as conn:
                db.insert_account_balance_snapshot(conn, snapshot_to_row(snapshot))
                # 2026-08-16 (Block B) — 종목별 보유 상세도 남긴다(마이그레이션 030).
                # 종전에는 `output1`이 방향별 개수 두 개로 요약돼 버려졌고, 그래서 「그 분에
                # 무엇을 들고 있었나」에 답할 수 없었다. 포지션이 없으면 아무 행도 안 쓴다.
                #
                # **같은 커넥션·같은 poll_time을 쓴다** — 두 표가 다른 시각을 갖게 되면
                # `unknown_side_count`(잔고 표)와 `side_distribution`(포지션 표)이 서로 다른
                # 사이클을 가리켜 §16-1이 「두 축이 갈렸다」를 오탐한다.
                db.insert_position_snapshots(conn, position_rows(snapshot))
        except Exception:
            logger.warning("계좌 잔고 폴링 사이클 실패 — 이번 사이클 건너뜀", exc_info=True)

        loop_now = asyncio.get_running_loop().time()
        next_tick, delay, overrun_seconds = _advance_fixed_tick(
            next_tick, interval_seconds, loop_now, phase_offset_seconds
        )
        if overrun_seconds > 0:
            logger.warning(
                "계좌 잔고 폴링 사이클이 주기(%.0f초)를 초과해 스케줄이 %.1f초 밀렸습니다 — 위상 격자의 다음 틱까지 %.1f초 대기",
                interval_seconds, overrun_seconds, delay,
            )
        await asyncio.sleep(delay)


def _configure_logging() -> None:
    """
    계산: 콘솔(stdout)과 로테이션 파일(logs/observation_loop.log) 양쪽에 동시에 로깅한다.
         2026-07-19(§5-5) — 예전엔 scripts/start_mahdi_premarket.bat가 stdout을
         `>> logs\\observation_loop.log 2>&1`로 그대로 리다이렉트해서 로테이션이 전혀 없었고
         (105MB까지 무한 누적 확인), Python 로깅은 콘솔에만 나갔다. 이제 Python 로깅이 이 파일을
         직접 소유해 파일당 LOG_MAX_BYTES(10MB), 최근 LOG_BACKUP_COUNT(10)개(최대 약 110MB)만
         유지하고 그 이전은 자동 삭제한다 — 배치파일도 함께 고쳐 stdout 리다이렉트를 없애고
         (콘솔 창엔 여전히 실시간으로 보임) stderr만 별도의 회전 없는 크래시 전용 로그로 남긴다
         (로깅 설정 자체가 안 끝난 극초반 크래시까지 잡기 위함 — 흔치 않은 이벤트라 회전 불필요).
         2026-07-29(운영점검보고서 §2-5) — 그동안 `format=` 없이 기본 포맷(레벨:로거명:메시지)만
         썼는데, 그러면 줄마다 발생 시각이 전혀 안 남아 WARNING이 몇 시에 났는지 로그만으로
         특정할 수 없었다(그날 스케줄 밀림 원인 조사 중 직접 겪음) — `asctime`(시스템 로컬시각
         =KST, `db.local_now()`의 naive-KST 정책과 그대로 일치, 별도 tz 변환 불필요)을 추가한다.
    실패 조건: logs/ 디렉터리가 없으면 미리 만든다(최초 실행 시).
    """
    LOG_DIR.mkdir(parents=True, exist_ok=True)
    file_handler = RotatingFileHandler(LOG_FILE, maxBytes=LOG_MAX_BYTES, backupCount=LOG_BACKUP_COUNT, encoding="utf-8")
    console_handler = logging.StreamHandler(sys.stdout)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s:%(name)s:%(message)s",
        handlers=[file_handler, console_handler],
    )


def _log_startup_gap_since_last_run() -> None:
    """
    계산: LAST_START_MARKER_FILE에 남아있는 직전 정상 기동 시각과 현재 시각의 차이를 INFO로
         남긴 뒤, 이번 기동 시각으로 마커를 갱신한다(2026-07-20 고도화 항목). 예약된 장전 기동이
         하루 이상 건너뛰거나(Docker 미기동으로 조용히 실패하는 경우 등), 반대로 예상보다 훨씬
         일찍(수동 재시작 등) 다시 떴는지를 observation_loop.log 한 줄로 바로 알아챌 수 있다.
    실패 조건: 마커 파일이 없으면(최초 실행) 또는 파싱 실패하면 비교 없이 건너뛰고, 그래도 마커
              갱신은 시도한다. 마커 읽기/쓰기 자체가 실패해도(권한 등) 예외를 삼키고 로그만
              남긴다 — 이 기능 하나 때문에 관측 루프 기동 전체가 죽으면 안 된다.
    """
    try:
        if LAST_START_MARKER_FILE.exists():
            last = datetime.fromisoformat(LAST_START_MARKER_FILE.read_text(encoding="utf-8").strip())
            gap_hours = (db.local_now() - last).total_seconds() / 3600
            logger.info(
                "직전 정상 기동: %s (%.1f시간 전)", last.strftime("%Y-%m-%d %H:%M:%S"), gap_hours,
            )
        else:
            logger.info("직전 정상 기동 기록 없음(최초 실행 또는 마커 파일 삭제됨)")
    except Exception:
        logger.warning("직전 기동 기록 확인 실패", exc_info=True)

    # 2026-08-06 §3-3 / Fix#4 — 트레이스백 예산이 이 프로세스에서 새로 열렸다는 사실을 남긴다.
    # 08-06에 프로세스가 세 번 떠서 `오늘 N번째` 카운터가 두 번 되감겼는데, 그 사실이 로그
    # 어디에도 없어 사후 집계가 205건을 190건으로 봤다.
    logger.info("%s", _TRACEBACK_BUDGET.describe())

    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        LAST_START_MARKER_FILE.write_text(db.local_now().isoformat(), encoding="utf-8")
    except Exception:
        logger.warning("직전 기동 기록 저장 실패", exc_info=True)


async def main() -> None:
    _configure_logging()
    _log_startup_gap_since_last_run()
    kis_settings = get_kis_settings()
    get_db_settings()  # 조기 검증(연결 문자열 구성 오류를 기동 시점에 노출)

    # 종목코드 마스터파일은 매일 갱신되므로 기동 시 1회 내려받아 최근월물/행사가↔단축코드
    # 매핑을 확정한다 (모의투자 REST에는 옵션 체인 전체를 한 번에 주는 API가 없어 필수).
    master = load_index_derivatives_master(SYMBOL_MASTER_CACHE_DIR)
    futures_symbol = master.front_month_future_code("KOSPI200")
    if futures_symbol is None:
        raise RuntimeError("종목코드 마스터파일에서 KOSPI200 선물 최근월물을 찾지 못했습니다")

    # 해외선물 마스터(VX/CNH 근월·차근월)는 국내 마스터와 별개 파일 — 하나가 실패해도 다른
    # 하나는 관측을 계속할 수 있어야 하므로 별도로 로드한다(2026-07-10 신규, Cross-asset
    # stress §7.3). 다운로드 실패 시(네트워크 등) 매크로 폴링만 건너뛰고 나머지 관측은 계속한다.
    try:
        overseas_future_master = load_overseas_future_master(OVERSEAS_FUTURE_MASTER_CACHE_DIR)
    except Exception:
        logger.warning("해외선물 종목코드 마스터 로드 실패 — 매크로 스냅샷 폴링을 건너뜁니다", exc_info=True)
        overseas_future_master = None

    token_daemon = TokenDaemon(kis_settings)
    rest_client = KISRestClient(kis_settings, token_daemon)
    approval_key = ApprovalKeyIssuer(kis_settings).issue()
    regime_state_machine = RegimeStateMachine(underlying=UNDERLYING, futures_symbol=futures_symbol)
    # 2026-08-12 Fix#7 — 오늘 이미 쌓인 피처가 있으면 세션 창을 되살린다(레버가 꺼져 있으면
    # 아무 일도 안 하고 0을 반환한다). 08-12 재기동이 레짐을 29분 WARMUP으로 되돌렸다.
    # **조회 실패는 삼킨다** — 복원은 있으면 좋은 것이지 기동 조건이 아니다.
    try:
        with db.get_connection() as conn:
            regime_state_machine.restore_session_window(conn, db.local_now().date())
    except Exception:
        logger.warning("레짐 세션 창 복원 건너뜀 — warmup부터 시작한다", exc_info=True)
    market_halt_monitor = MarketHaltMonitor()
    ws_liveness = WsLiveness()

    # 시세(H0IOCNT0/H0IOASP0)는 계좌 무관 공개 데이터라 모의투자 전용 도메인이 없다 —
    # is_mock 여부와 상관없이 MARKET_DATA_WS_DOMAIN(실전 도메인) 하나로 접속한다.
    async with websockets.connect(tr_codes.MARKET_DATA_WS_DOMAIN) as raw_ws:
        ws_client = KISWebSocketClient(approval_key=approval_key, connection=_WebsocketsAdapter(raw_ws))
        # 먼슬리(정규 월물)·위클리(월)·위클리(목) 세 북을 별도 매니저로 동시에 굴린다(2026-07-06
        # 먼슬리+위클리 2북 도입, 2026-07-10 위클리를 월/목 두 상품으로 분리) — 3북×ATM±2(10슬롯)
        # + 1(선물) = 31 / MAX_SUBSCRIPTIONS(41). ATM±3(14슬롯)을 유지하면 3북 합계가 43으로
        # 한도를 넘겨(RESEARCH_EXPIRY_SELECTION_v1.md §3.1이 미리 지적한 트레이드오프) 세 북
        # 모두 ATM±2로 축소하기로 결정(사용자 확인, [[DECISION_LOG]] 참고).
        # 2026-08-07(고도화#1) — 세 북이 **한 풀을 공유한다.** 슬롯은 WS 세션당 자원이라
        # 북마다 나눠 주면 3북 날(31/41 사용)에는 북당 3슬롯이라 아무것도 유지하지 못한다.
        retention_pool = SubscriptionRetentionPool(ws_client)
        monthly_manager = RollingSubscriptionManager(
            ws_client,
            tr_id=tr_codes.WS_TR_OPTION_CONTRACT,
            strike_interval=KOSPI200_OPTION_STRIKE_INTERVAL,
            strikes_each_side=STRIKES_EACH_SIDE,
            symbol_formatter=lambda strike, opt: master.option_symbol(opt, strike, underlying="KOSPI200"),
            retention_pool=retention_pool,
        )
        weekly_mon_manager = RollingSubscriptionManager(
            ws_client,
            tr_id=tr_codes.WS_TR_OPTION_CONTRACT,
            strike_interval=KOSPI200_OPTION_STRIKE_INTERVAL,
            strikes_each_side=STRIKES_EACH_SIDE,
            symbol_formatter=lambda strike, opt: master.option_symbol(
                opt, strike, underlying="KOSPI200", series="weekly_mon"
            ),
            retention_pool=retention_pool,
        )
        weekly_thu_manager = RollingSubscriptionManager(
            ws_client,
            tr_id=tr_codes.WS_TR_OPTION_CONTRACT,
            strike_interval=KOSPI200_OPTION_STRIKE_INTERVAL,
            strikes_each_side=STRIKES_EACH_SIDE,
            symbol_formatter=lambda strike, opt: master.option_symbol(
                opt, strike, underlying="KOSPI200", series="weekly_thu"
            ),
            retention_pool=retention_pool,
        )
        books = [
            (monthly_manager, "regular"),
            (weekly_mon_manager, "weekly_mon"),
            (weekly_thu_manager, "weekly_thu"),
        ]
        tasks = [
            run_observation_loop_forever(
                ws_client,
                [monthly_manager, weekly_mon_manager, weekly_thu_manager],
                rest_client,
                futures_symbol=futures_symbol,
                regime_state_machine=regime_state_machine,
                market_halt_monitor=market_halt_monitor,
                approval_key=approval_key,
                ws_liveness=ws_liveness,
            ),
            poll_option_chain(rest_client, books, master, regime_state_machine=regime_state_machine),
            poll_expiry_liquidity(
                rest_client, books, master, phase_offset_seconds=EXPIRY_LIQUIDITY_PHASE_OFFSET_SECONDS
            ),
            poll_investor_flow(rest_client, phase_offset_seconds=INVESTOR_FLOW_PHASE_OFFSET_SECONDS),
            poll_signal_fusion_cycle(
                regime_state_machine,
                phase_offset_seconds=SIGNAL_FUSION_PHASE_OFFSET_SECONDS,
                # 2026-08-04 Fix#2 — 주문흐름(OFI)은 선물 1분봉에서 온다(`market_raw_1m`).
                futures_symbol=futures_symbol,
            ),
            poll_account_balance_cycle(
                rest_client, phase_offset_seconds=ACCOUNT_BALANCE_PHASE_OFFSET_SECONDS
            ),
            # 2026-07-31 §4 우선순위 4 / 2026-08-01 §5-4 — 안전장치 생존 신호는 감시 대상과
            # 독립한 타이머에서 낸다(CB 감지 / WS 연결).
            poll_market_halt_heartbeat(market_halt_monitor),
            poll_ws_heartbeat(ws_liveness),
            # 2026-08-06 §2-1 / Fix#2 — 프로세스 자신의 생존 신호. 위 둘과 달리 DB를 거치지
            # 않는다(DB가 죽는 것과 루프가 죽는 것은 다른 사건이고 조치도 다르다).
            poll_process_heartbeat(),
            # 2026-08-04 고도화#5 — KIS 응답시간을 서비스 품질 지표로 승격(밀림의 90%가 여기서 온다).
            poll_rest_latency_snapshot(rest_client),
        ]
        if overseas_future_master is not None:
            tasks.append(
                poll_macro_snapshot(
                    rest_client, overseas_future_master,
                    phase_offset_seconds=MACRO_SNAPSHOT_PHASE_OFFSET_SECONDS,
                )
            )
        # 2026-07-19(§5-4) — .env에 토큰/채널이 설정된 경우에만 워커를 띄운다. notify.notify()가
        # 이미 미설정 시 조용히 무시하지만, 워커까지 안 띄우면 알림 기능이 꺼진 상태에서 불필요한
        # 태스크가 asyncio.gather에 남지 않는다.
        if get_slack_settings().is_configured:
            tasks.append(notify.run_slack_worker())
        await asyncio.gather(*tasks)


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        logger.info("Ctrl+C로 종료합니다.")
